import type {
  ChatMessageInput,
  PromptMessageInput,
  SummaryBatchInput,
  SummaryCatalog,
  SummaryPromptItem,
  SummarySlice,
} from "../../shared/domain";
import { sourceMessagesHash } from "../../shared/source-hash";
import type { EchoesSettings } from "../state/settings";
import type { SummaryWorldbookState } from "../worldbook/summary-worldbook";
import { preprocessSummaryMessages } from "./preprocess";

export const SUMMARY_OUTPUT_PROTOCOL = `输出必须是一个 JSON 对象：
{"summaries":[{"title":"简短标题","content":"独立完整的事实总结","tags":["可选标签"]}]}
生成 1 至 50 个切片，不要输出 Markdown 代码围栏或 JSON 之外的文字。`;

export interface SummaryPromptBlock {
  id: string;
  title: string;
  role: PromptMessageInput["role"];
  content: string;
}

export interface PreparedSummaryRequest {
  batch: SummaryBatchInput;
  originalMessages: ChatMessageInput[];
  cleanedMessages: ChatMessageInput[];
  promptBlocks: SummaryPromptBlock[];
  promptMessages: PromptMessageInput[];
}

export function currentChatMessages(): ChatMessageInput[] {
  const seen = new Set<string>();
  return SillyTavern.getContext().chat.flatMap((message, index) => {
    const content = String(message.mes ?? message.message ?? "").trim();
    if (!content) return [];
    const rawId = String(message.message_id ?? message.id ?? index);
    const id = seen.has(rawId) ? `${rawId}:${index}` : rawId;
    seen.add(id);
    return [{
      id,
      role: message.is_user === true || message.role === "user" ? "user" as const : "assistant" as const,
      content,
    }];
  });
}

export async function summarySourceHash(messages: ChatMessageInput[]): Promise<string> {
  return sourceMessagesHash(messages);
}

export async function automaticSummaryBatch(
  messages: ChatMessageInput[],
  catalog: SummaryCatalog,
  messageCount: number,
): Promise<{ batch: SummaryBatchInput; messages: ChatMessageInput[] } | null> {
  const checkpointIndex = catalog.lastCommittedMessageId
    ? messages.findIndex((message) => message.id === catalog.lastCommittedMessageId)
    : -1;
  if (catalog.lastCommittedMessageId && checkpointIndex < 0) return null;
  const start = checkpointIndex + 1;
  const threshold = Math.max(2, Math.min(500, Math.floor(messageCount)));
  if (messages.length - start < threshold) return null;
  const boundary = Math.min(messages.length - 1, start + threshold - 1);
  let end = -1;
  for (let index = boundary; index >= start; index -= 1) {
    if (messages[index]?.role !== "assistant") continue;
    if (!messages.slice(index + 1).some((message) => message.role === "user")) continue;
    end = index;
    break;
  }
  if (end < start) return null;
  const selected = messages.slice(start, end + 1);
  const batchNumber = catalog.nextBatchNumber;
  return {
    messages: selected,
    batch: {
      id: `summary_batch_${batchNumber}`,
      batchNumber,
      startMessageId: selected[0]!.id,
      endMessageId: selected.at(-1)!.id,
      messageIds: selected.map((message) => message.id),
      sourceHash: await summarySourceHash(selected),
    },
  };
}

export async function manualSummaryBatch(
  messages: ChatMessageInput[],
  catalog: SummaryCatalog,
  startIndex: number,
  endIndex: number,
  existingBatch?: SummarySlice["batch"],
): Promise<{ batch: SummaryBatchInput; messages: ChatMessageInput[] }> {
  if (!Number.isInteger(startIndex) || !Number.isInteger(endIndex) || startIndex < 0 || endIndex < startIndex) {
    throw new Error("手动总结消息范围无效。");
  }
  const selected = messages.slice(startIndex, endIndex + 1);
  if (selected.length === 0 || selected.length > 500) throw new Error("手动总结范围必须包含 1 至 500 条消息。");
  const batchNumber = existingBatch?.batchNumber ?? catalog.nextBatchNumber;
  return {
    messages: selected,
    batch: {
      id: existingBatch?.id ?? `summary_batch_${batchNumber}`,
      batchNumber,
      startMessageId: selected[0]!.id,
      endMessageId: selected.at(-1)!.id,
      messageIds: selected.map((message) => message.id),
      sourceHash: await summarySourceHash(selected),
    },
  };
}

function macro(value: string, charName: string, userName: string): string {
  return value.replaceAll("{{char}}", charName).replaceAll("{{user}}", userName);
}

function dynamicContent(
  item: SummaryPromptItem,
  cleanedMessages: ChatMessageInput[],
  previousSlices: SummarySlice[],
): string {
  const context = SillyTavern.getContext();
  const character = context.characters?.[context.characterId ?? -1] ?? {};
  const charName = String(character.name ?? "Character");
  const userName = String(context.powerUserSettings?.persona_name ?? context.name1 ?? "User");
  if (item.kind === "custom") return macro(item.content, charName, userName);
  if (item.kind === "character") {
    const description = String(character.description ?? "").trim();
    return description ? `${charName}:\n${description}` : "";
  }
  if (item.kind === "persona") {
    const description = String(context.powerUserSettings?.persona_description ?? "").trim();
    return description ? `${userName}:\n${description}` : "";
  }
  if (item.kind === "previous_summaries") {
    return previousSlices.slice(-item.count).map((slice) => `[${slice.title}] ${slice.content}`).join("\n\n");
  }
  return cleanedMessages.map((message) => {
    const name = message.role === "user" ? userName : charName;
    return `[${message.id}] ${name}: ${message.content}`;
  }).join("\n\n");
}

export async function prepareSummaryRequest(options: {
  batch: SummaryBatchInput;
  messages: ChatMessageInput[];
  state: SummaryWorldbookState;
  settings: EchoesSettings;
}): Promise<PreparedSummaryRequest> {
  const cleanedMessages = await preprocessSummaryMessages(options.messages, options.settings.summary.preprocessRules);
  if (cleanedMessages.length === 0) throw new Error("消息清洗后没有可总结内容。");
  if (!options.settings.summary.promptPreset.items.some((item) => item.enabled && item.kind === "messages")) {
    throw new Error("总结预设至少需要一个启用的待总结消息项。");
  }
  const previousSlices = options.state.slices.filter((slice) =>
    slice.batch.batchNumber < options.batch.batchNumber && slice.batch.state !== "stale");
  const promptBlocks = options.settings.summary.promptPreset.items.flatMap((item): SummaryPromptBlock[] => {
    if (!item.enabled) return [];
    const content = dynamicContent(item, cleanedMessages, previousSlices).trim();
    return content ? [{ id: item.id, title: item.title, role: item.role, content }] : [];
  });
  return {
    batch: options.batch,
    originalMessages: structuredClone(options.messages),
    cleanedMessages,
    promptBlocks,
    promptMessages: promptBlocks.map(({ role, content }) => ({ role, content })),
  };
}

export async function firstStaleBatchNumber(
  state: SummaryWorldbookState,
  messages: ChatMessageInput[],
): Promise<number | null> {
  const byId = new Map(messages.map((message) => [message.id, message]));
  const batches = [...new Map(state.slices.map((slice) => [slice.batch.id, slice.batch])).values()]
    .sort((left, right) => left.batchNumber - right.batchNumber);
  for (const batch of batches) {
    if (batch.source?.kind === "imported") continue;
    if (batch.state === "stale") return batch.batchNumber;
    const current = batch.messageIds.map((id) => byId.get(id));
    if (current.some((message) => !message)) return batch.batchNumber;
    if (await summarySourceHash(current as ChatMessageInput[]) !== batch.sourceHash) return batch.batchNumber;
  }
  return null;
}
