function id(prefix: string): string {
  return `${prefix}_${crypto.randomUUID().replaceAll("-", "")}`;
}

function button(icon: string, title: string, action: string): HTMLButtonElement {
  const element = document.createElement("button");
  element.type = "button";
  element.className = "echoes-icon-button";
  element.title = title;
  element.setAttribute("aria-label", title);
  element.dataset.statusAction = action;
  element.innerHTML = `<i class="fa-solid fa-${icon}"></i>`;
  return element;
}

function previewDialog(title: string, content: string): void {
  const element = dialogShell(title, { closeOnly: true });
  element.querySelector<HTMLElement>(".echoes-dialog-body")!.innerHTML = '<pre class="echoes-status-preview"></pre>';
  element.querySelector("pre")!.textContent = content;
  element.showModal();
}
function diffSummary(current: StatusSnapshot, parent: StatusSnapshot | undefined): string {
  if (!parent) return "初始快照";
  const left = JSON.stringify(parent.state);
  const right = JSON.stringify(current.state);
  if (left === right) return "无变化";
  const keys = new Set([...Object.keys(parent.state), ...Object.keys(current.state)]);
  const changed = [...keys].filter((key) => JSON.stringify(parent.state[key]) !== JSON.stringify(current.state[key]));
  return changed.length > 0 ? changed.join(", ") : "嵌套字段变化";
}

export class StatusPanel {
  private state: StatusWorldbookState | null = null;
  private records: StatusSnapshotRecord[] = [];
  private busy = false;
  private actionChain: Promise<void> = Promise.resolve();
  private queuedActions = 0;
  private renderSequence = 0;

  constructor(private readonly root: HTMLElement) {
    this.bindEvents();
  }

  async render(): Promise<void> {
    const sequence = ++this.renderSequence;
    const chatId = SillyTavern.getContext().chatId;
    const host = this.root.querySelector<HTMLElement>(".echoes-grid-host")!;
    host.innerHTML = '<div class="echoes-grid-message">正在读取普通状态...</div>';
    try {
      const state = await statusCoordinator.load();
      if (sequence !== this.renderSequence
        || !this.root.classList.contains("echoes-status-view")
        || SillyTavern.getContext().chatId !== chatId
        || state.catalog.chatId !== chatId) return;
      this.state = state;
      this.records = statusCoordinator.history(state);
      this.renderSidebar();
      this.renderContent();
    } catch (error) {
      if (sequence !== this.renderSequence
        || !this.root.classList.contains("echoes-status-view")
        || SillyTavern.getContext().chatId !== chatId) return;
      host.innerHTML = "";
      const note = document.createElement("div");
      note.className = "echoes-grid-message error";
      note.textContent = error instanceof Error ? error.message : String(error);
      host.append(note);
    }
  }

  private renderSidebar(): void {
    const heading = this.root.querySelector<HTMLElement>(".echoes-sidebar-heading > span")!;
    const actions = this.root.querySelector<HTMLElement>(".echoes-sidebar-actions")!;
    const list = this.root.querySelector<HTMLElement>(".echoes-table-list")!;
    heading.textContent = "状态历史";
    actions.replaceChildren();
    list.replaceChildren();
    const current = this.state ? statusCoordinator.current(this.state) : null;
    for (const [icon, label, value] of [
      ["power-off", "总开关", this.state?.catalog.enabled ? "开启" : "关闭"],
      ["arrows-rotate", "自动更新", this.state?.catalog.autoUpdate ? "开启" : "关闭"],
      ["clock-rotate-left", "快照", String(this.records.length)],
      ["layer-group", "当前修订", String(current?.snapshot.revision ?? 0)],
    ]) {
      const item = document.createElement("div");
      item.className = "echoes-summary-stat";
      item.innerHTML = `<i class="fa-solid fa-${icon}"></i><span></span><strong></strong>`;
      item.querySelector("span")!.textContent = label!;
      item.querySelector("strong")!.textContent = value!;
      list.append(item);
    }
  }

  private renderContent(): void {
    if (!this.state) return;
    const settings = getSettings();
    const workflow = settings.generationWorkflows.status;
    const workflowGroup = settings.generationGroups.find((group) => group.id === workflow.groupId);
    const current = statusCoordinator.current(this.state);
    const currentState = current?.snapshot.state ?? this.state.catalog.profile.initialState;
    const host = this.root.querySelector<HTMLElement>(".echoes-grid-host")!;
    host.innerHTML = `
      <div class="echoes-status-page">
        <section class="echoes-status-controls">
          <div class="echoes-summary-control-row">
            <label class="echoes-check"><input type="checkbox" data-status-enabled>状态注入</label>
            <label class="echoes-check"><input type="checkbox" data-status-auto>自动更新</label>
            <div class="echoes-api-binding-inline"><span>状态工作流<strong data-status-binding></strong></span><button type="button" class="menu_button" data-action="switch-view" data-view="api"><i class="fa-solid fa-plug"></i> API配置</button></div>
            <button type="button" class="menu_button echoes-primary" data-status-action="sync"><i class="fa-solid fa-arrows-rotate"></i> 手动同步</button>
            <button type="button" class="menu_button" data-status-action="refresh"><i class="fa-solid fa-rotate"></i> 刷新</button>
          </div>
          <div class="echoes-status-sync" data-status-sync></div>
        </section>
        <section class="echoes-summary-section">
          <header><h2>当前状态</h2><div><button type="button" class="menu_button" data-status-action="preview"><i class="fa-solid fa-eye"></i> 最终提示词</button> <button type="button" class="menu_button" data-status-action="reset"><i class="fa-solid fa-rotate-left"></i> 恢复初始值</button> <button type="button" class="menu_button echoes-primary" data-status-action="save-yaml"><i class="fa-solid fa-floppy-disk"></i> 校验并保存</button></div></header>
          <textarea class="echoes-status-yaml" data-status-yaml spellcheck="false"></textarea>
        </section>
        <section class="echoes-summary-section"><header><h2>快照历史</h2></header><div data-status-history></div></section>
        <section class="echoes-summary-section">
          <header><h2>当前聊天配置副本</h2><button type="button" class="menu_button echoes-primary" data-status-action="save-profile"><i class="fa-solid fa-floppy-disk"></i> 保存配置</button></header>
          <div class="echoes-status-profile">
            <label>初始状态 YAML<textarea data-status-initial spellcheck="false"></textarea></label>
            <label>未知字段<select data-status-unknown><option value="allow">允许</option><option value="reject">拒绝</option></select></label>
            <label>注入位置<select data-status-position><option value="before_character">角色定义前</option><option value="after_character">角色定义后</option><option value="at_depth">指定深度</option></select></label>
            <label>角色<select data-status-role><option value="system">system</option><option value="user">user</option><option value="assistant">assistant</option></select></label>
            <label>深度<input type="number" min="0" max="100" data-status-depth></label>
            <label>顺序<input type="number" min="-10000" max="10000" data-status-order></label>
            <label class="echoes-status-template-field">注入模板<textarea data-status-template></textarea></label>
          </div>
        </section>
        <section class="echoes-summary-section"><header><h2>状态提示词</h2><button type="button" class="menu_button" data-status-action="add-prompt"><i class="fa-solid fa-plus"></i> 添加</button></header><div class="echoes-summary-config-list" data-status-prompts></div></section>
        <section class="echoes-summary-section"><header><h2>消息清洗</h2><button type="button" class="menu_button" data-status-action="add-cleaning"><i class="fa-solid fa-plus"></i> 添加</button></header><div class="echoes-summary-config-list" data-status-cleaning></div></section>
        <section class="echoes-summary-section"><header><h2>声明式校验</h2><button type="button" class="menu_button" data-status-action="add-validation"><i class="fa-solid fa-plus"></i> 添加</button></header><div class="echoes-summary-config-list" data-status-validation></div></section>
        <section class="echoes-summary-section"><header><h2>全局状态模板</h2><button type="button" class="menu_button" data-status-action="save-template"><i class="fa-solid fa-plus"></i> 将当前副本保存为模板</button></header><div class="echoes-status-template-picker"><select data-status-template-select></select><button type="button" class="menu_button" data-status-action="apply-template">基于模板重建副本</button><button type="button" class="menu_button" data-status-action="update-template"><i class="fa-solid fa-floppy-disk"></i> 覆盖模板</button><button type="button" class="menu_button" data-status-action="delete-template"><i class="fa-solid fa-trash"></i> 删除模板</button></div></section>
        <section class="echoes-summary-section"><header><h2>最近任务诊断</h2></header><pre class="echoes-recall-trace" data-status-trace></pre></section>
      </div>`;
    host.querySelector<HTMLInputElement>("[data-status-enabled]")!.checked = this.state.catalog.enabled;
    host.querySelector<HTMLInputElement>("[data-status-auto]")!.checked = this.state.catalog.autoUpdate;
    host.querySelector<HTMLElement>("[data-status-binding]")!.textContent = `${workflowGroup?.name ?? "未配置"} · ${{ confirm_ambiguous: "不确定时确认", always: "始终自动切换", definitive_only: "仅明确失败切换" }[workflow.failoverPolicy]}`;
    host.querySelector<HTMLTextAreaElement>("[data-status-yaml]")!.value = renderStatusYaml(currentState);
    this.fillProfile();
    this.renderHistory();
    this.renderPrompts();
    this.renderCleaning();
    this.renderValidation();
    const templateSelect = host.querySelector<HTMLSelectElement>("[data-status-template-select]")!;
    for (const template of settings.statusTemplates) templateSelect.append(new Option(template.name, template.id));
    host.querySelector<HTMLElement>("[data-status-sync]")!.textContent = current
      ? `当前楼层 ${current.messageId} · swipe ${current.swipeId} · 修订 ${current.snapshot.revision} · ${current.snapshot.origin}`
      : "尚无快照，当前使用模板初始状态。";
    host.querySelector<HTMLElement>("[data-status-trace]")!.textContent = JSON.stringify(statusCoordinator.trace ?? { message: "暂无状态任务" }, null, 2);
    this.updateBusyControls();
  }

  private fillProfile(): void {
    if (!this.state) return;
    const profile = this.state.catalog.profile;
    this.root.querySelector<HTMLTextAreaElement>("[data-status-initial]")!.value = renderStatusYaml(profile.initialState);
    this.root.querySelector<HTMLSelectElement>("[data-status-unknown]")!.value = profile.validation.unknownFields;
    this.root.querySelector<HTMLSelectElement>("[data-status-position]")!.value = profile.injection.position;
    this.root.querySelector<HTMLSelectElement>("[data-status-role]")!.value = profile.injection.role;
    this.root.querySelector<HTMLInputElement>("[data-status-depth]")!.value = String(profile.injection.depth);
    this.root.querySelector<HTMLInputElement>("[data-status-order]")!.value = String(profile.injection.order);
    this.root.querySelector<HTMLTextAreaElement>("[data-status-template]")!.value = profile.injection.template;
  }

  private renderHistory(): void {
    const host = this.root.querySelector<HTMLElement>("[data-status-history]")!;
    if (this.records.length === 0) {
      host.innerHTML = '<div class="echoes-empty-note">暂无状态快照。</div>';
      return;
    }
    const byId = new Map(this.records.map((record) => [record.snapshot.snapshotId, record.snapshot]));
    const wrapper = document.createElement("div");
    wrapper.className = "echoes-table-scroll";
    const table = document.createElement("table");
    table.className = "echoes-data-table";
    table.innerHTML = "<thead><tr><th>助手楼层</th><th>Swipe</th><th>来源</th><th>修订</th><th>状态哈希</th><th>变化</th><th>操作</th></tr></thead>";
    const body = document.createElement("tbody");
    for (const record of [...this.records].reverse()) {
      const row = document.createElement("tr");
      for (const value of [
        record.messageId,
        `${record.swipeId}${record.selected ? " · 当前" : ""}`,
        record.snapshot.origin,
        String(record.snapshot.revision),
        record.snapshot.stateHash.slice(0, 12),
        diffSummary(record.snapshot, record.snapshot.parentSnapshotId ? byId.get(record.snapshot.parentSnapshotId) : undefined),
      ]) {
        const cell = document.createElement("td");
        cell.textContent = value;
        row.append(cell);
      }
      const actions = document.createElement("td");
      const inspect = button("eye", "查看完整快照", "inspect-history");
      inspect.dataset.snapshotId = record.snapshot.snapshotId;
      const restore = button("clock-rotate-left", "恢复到当前最后一条助手消息", "restore-history");
      restore.dataset.snapshotId = record.snapshot.snapshotId;
      actions.append(inspect, restore);
      row.append(actions);
      body.append(row);
    }
    table.append(body);
    wrapper.append(table);
    host.replaceChildren(wrapper);
  }

  private configRow(title: string, detail: string, enabled?: boolean): HTMLElement {
    const row = document.createElement("article");
    row.className = "echoes-summary-config-row";
    const text = document.createElement("div");
    const strong = document.createElement("strong");
    strong.textContent = title;
    const small = document.createElement("small");
    small.textContent = detail;
    text.append(strong, small);
    row.append(text);
    if (enabled !== undefined) {
      const toggle = document.createElement("label");
      toggle.className = "echoes-switch";
      const input = document.createElement("input");
      input.type = "checkbox";
      input.setAttribute("aria-label", `启用${title}`);
      input.checked = enabled;
      toggle.append(input, document.createElement("span"));
      row.append(toggle);
    }
    const controls = document.createElement("div");
    controls.className = "echoes-row-actions";
    controls.dataset.controls = "true";
    row.append(controls);
    return row;
  }

  private renderPrompts(): void {
    const host = this.root.querySelector<HTMLElement>("[data-status-prompts]")!;
    host.replaceChildren();
    const items = this.state!.catalog.profile.promptPreset.items;
    items.forEach((item, index) => {
      const row = this.configRow(item.title, `${item.role} · ${item.kind}`, item.enabled);
      row.querySelector<HTMLInputElement>("input")!.dataset.statusPromptToggle = String(index);
      const controls = row.querySelector<HTMLElement>("[data-controls]")!;
      for (const [icon, title, action, disabled] of [
        ["arrow-up", "上移", "prompt-up", index === 0],
        ["arrow-down", "下移", "prompt-down", index === items.length - 1],
        ["pen", "编辑", "edit-prompt", false],
        ["trash", "删除", "delete-prompt", false],
      ] as const) {
        const control = button(icon, title, action);
        control.dataset.index = String(index);
        control.disabled = disabled;
        controls.append(control);
      }
      host.append(row);
    });
  }

  private renderCleaning(): void {
    const host = this.root.querySelector<HTMLElement>("[data-status-cleaning]")!;
    host.replaceChildren();
    const rules = this.state!.catalog.profile.preprocessRules;
    if (rules.length === 0) host.innerHTML = '<div class="echoes-empty-note">暂无清洗规则。</div>';
    rules.forEach((rule, index) => {
      const row = this.configRow(rule.name, `${rule.type} · /${rule.pattern}/${rule.flags}`, rule.enabled);
      row.querySelector<HTMLInputElement>("input")!.dataset.statusCleaningToggle = String(index);
      const controls = row.querySelector<HTMLElement>("[data-controls]")!;
      const up = button("arrow-up", "上移", "cleaning-up");
      up.dataset.index = String(index);
      up.disabled = index === 0;
      const down = button("arrow-down", "下移", "cleaning-down");
      down.dataset.index = String(index);
      down.disabled = index === rules.length - 1;
      const edit = button("pen", "编辑", "edit-cleaning");
      edit.dataset.index = String(index);
      const remove = button("trash", "删除", "delete-cleaning");
      remove.dataset.index = String(index);
      controls.append(up, down, edit, remove);
      host.append(row);
    });
  }

  private renderValidation(): void {
    const host = this.root.querySelector<HTMLElement>("[data-status-validation]")!;
    host.replaceChildren();
    const rules = this.state!.catalog.profile.validation.rules;
    if (rules.length === 0) host.innerHTML = '<div class="echoes-empty-note">暂无字段校验，未知字段按上方策略处理。</div>';
    rules.forEach((rule, index) => {
      const limits = [
        rule.required ? "必填" : "可选",
        rule.minimum !== undefined ? `min ${rule.minimum}` : "",
        rule.maximum !== undefined ? `max ${rule.maximum}` : "",
        rule.maxDelta !== undefined ? `Δ ${rule.maxDelta}` : "",
      ].filter(Boolean).join(" · ");
      const row = this.configRow(rule.name, `${rule.path.join(".")} · ${rule.type} · ${limits}`);
      const controls = row.querySelector<HTMLElement>("[data-controls]")!;
      const edit = button("pen", "编辑", "edit-validation");
      edit.dataset.index = String(index);
      const remove = button("trash", "删除", "delete-validation");
      remove.dataset.index = String(index);
      controls.append(edit, remove);
      host.append(row);
    });
  }

  private bindEvents(): void {
    this.root.addEventListener("click", (event) => {
      const target = (event.target as HTMLElement).closest<HTMLElement>("[data-status-action]");
      if (!target) return;
      this.enqueue(() => this.handleAction(target), "状态操作失败");
    });
    this.root.addEventListener("change", (event) => {
      const target = event.target as HTMLInputElement | HTMLSelectElement;
      if (!target.matches([
        "[data-status-enabled]",
        "[data-status-auto]",
        "[data-status-prompt-toggle]",
        "[data-status-cleaning-toggle]",
      ].join(","))) return;
      this.enqueue(() => this.handleChange(target), "状态配置无效");
    });
  }

  private enqueue(operation: () => Promise<void>, errorTitle: string): void {
    this.queuedActions += 1;
    this.updateBusyControls();
    this.actionChain = this.actionChain
      .then(operation)
      .catch((error) => {
        toastr.error(error instanceof Error ? error.message : String(error), errorTitle);
      })
      .finally(() => {
        this.queuedActions = Math.max(0, this.queuedActions - 1);
        this.updateBusyControls();
      });
  }

  private updateBusyControls(): void {
    const pending = this.queuedActions > 0;
    this.root.dataset.statusBusy = String(pending);
    this.root.querySelectorAll<HTMLButtonElement>("[data-status-action]").forEach((control) => {
      if (pending && !control.disabled) {
        control.dataset.statusBusyDisabled = "true";
        control.disabled = true;
      } else if (!pending && control.dataset.statusBusyDisabled === "true") {
        delete control.dataset.statusBusyDisabled;
        control.disabled = false;
      }
    });
  }

  private async handleChange(target: HTMLInputElement | HTMLSelectElement): Promise<void> {
    if (!this.state) return;
    if (target.matches("[data-status-enabled]")) {
      this.state = await statusCoordinator.worldbook.saveConfiguration(this.state.worldbookName, { enabled: (target as HTMLInputElement).checked });
    } else if (target.matches("[data-status-auto]")) {
      this.state = await statusCoordinator.worldbook.saveConfiguration(this.state.worldbookName, { autoUpdate: (target as HTMLInputElement).checked });
    } else if (target.dataset.statusPromptToggle !== undefined) {
      const index = Number(target.dataset.statusPromptToggle);
      this.state.catalog.profile.promptPreset.items[index]!.enabled = (target as HTMLInputElement).checked;
      await this.saveProfile(false);
    } else if (target.dataset.statusCleaningToggle !== undefined) {
      const index = Number(target.dataset.statusCleaningToggle);
      this.state.catalog.profile.preprocessRules[index]!.enabled = (target as HTMLInputElement).checked;
      await this.saveProfile(false);
    }
    await this.render();
  }

  private async handleAction(target: HTMLElement): Promise<void> {
    if (!this.state) return;
    const action = target.dataset.statusAction ?? "";
    if (action === "refresh") await this.render();
    else if (action === "sync") await this.withBusy(() => statusCoordinator.synchronize());
    else if (action === "save-yaml") {
      const state = statusCoordinator.parseYaml(this.root.querySelector<HTMLTextAreaElement>("[data-status-yaml]")!.value);
      await this.withBusy(() => statusCoordinator.saveManualState(state));
    } else if (action === "reset") {
      await this.withBusy(() => statusCoordinator.saveManualState(this.state!.catalog.profile.initialState));
    } else if (action === "preview") await this.previewPrompt();
    else if (action === "save-profile") await this.saveProfile(true);
    else if (action === "inspect-history") {
      const record = this.records.find((item) => item.snapshot.snapshotId === target.dataset.snapshotId);
      if (record) previewDialog(`状态快照 ${record.messageId}/${record.swipeId}`, renderStatusYaml(record.snapshot.state));
    } else if (action === "restore-history") {
      const record = this.records.find((item) => item.snapshot.snapshotId === target.dataset.snapshotId);
      if (record) await this.withBusy(() => statusCoordinator.restoreSnapshot(record.snapshot));
    } else if (action === "add-prompt") await this.editPrompt();
    else if (action === "edit-prompt") await this.editPrompt(Number(target.dataset.index));
    else if (action === "delete-prompt") {
      this.state.catalog.profile.promptPreset.items.splice(Number(target.dataset.index), 1);
      await this.saveProfile(false);
    } else if (action === "prompt-up" || action === "prompt-down") {
      const from = Number(target.dataset.index);
      const to = from + (action === "prompt-up" ? -1 : 1);
      const [item] = this.state.catalog.profile.promptPreset.items.splice(from, 1);
      if (item) this.state.catalog.profile.promptPreset.items.splice(to, 0, item);
      await this.saveProfile(false);
    } else if (action === "add-cleaning") await this.editCleaning();
    else if (action === "edit-cleaning") await this.editCleaning(Number(target.dataset.index));
    else if (action === "delete-cleaning") {
      this.state.catalog.profile.preprocessRules.splice(Number(target.dataset.index), 1);
      await this.saveProfile(false);
    } else if (action === "cleaning-up" || action === "cleaning-down") {
      const from = Number(target.dataset.index);
      const to = from + (action === "cleaning-up" ? -1 : 1);
      const [rule] = this.state.catalog.profile.preprocessRules.splice(from, 1);
      if (rule) this.state.catalog.profile.preprocessRules.splice(to, 0, rule);
      this.state.catalog.profile.preprocessRules.forEach((item, index) => item.order = index);
      await this.saveProfile(false);
    } else if (action === "add-validation") await this.editValidation();
    else if (action === "edit-validation") await this.editValidation(Number(target.dataset.index));
    else if (action === "delete-validation") {
      this.state.catalog.profile.validation.rules.splice(Number(target.dataset.index), 1);
      await this.saveProfile(false);
    } else if (action === "apply-template") await this.applyTemplate();
    else if (action === "save-template") await this.saveTemplate();
    else if (action === "update-template") this.updateTemplate();
    else if (action === "delete-template") this.deleteTemplate();
    await this.render();
  }

  private async saveProfile(readForm: boolean): Promise<void> {
    if (!this.state) return;
    const profile = structuredClone(this.state.catalog.profile);
    if (readForm) {
      profile.initialState = statusCoordinator.parseYaml(this.root.querySelector<HTMLTextAreaElement>("[data-status-initial]")!.value);
      profile.validation.unknownFields = this.root.querySelector<HTMLSelectElement>("[data-status-unknown]")!.value as "allow" | "reject";
      profile.injection.position = this.root.querySelector<HTMLSelectElement>("[data-status-position]")!.value as StatusProfile["injection"]["position"];
      profile.injection.role = this.root.querySelector<HTMLSelectElement>("[data-status-role]")!.value as StatusProfile["injection"]["role"];
      profile.injection.depth = Number(this.root.querySelector<HTMLInputElement>("[data-status-depth]")!.value);
      profile.injection.order = Number(this.root.querySelector<HTMLInputElement>("[data-status-order]")!.value);
      profile.injection.template = this.root.querySelector<HTMLTextAreaElement>("[data-status-template]")!.value;
    }
    await this.persistProfile(profile);
  }

  private async persistProfile(profile: StatusProfile): Promise<void> {
    if (!this.state) return;
    validateStatusState(profile.initialState, profile.initialState, profile.validation);
    profile.version += 1;
    profile.updatedAt = new Date().toISOString();
    this.state = await statusCoordinator.worldbook.saveConfiguration(this.state.worldbookName, { profile });
  }

  private async previewPrompt(): Promise<void> {
    if (!this.state) return;
    const chat = SillyTavern.getContext().chat;
    let targetIndex = chat.length - 1;
    while (targetIndex >= 0) {
      const message = chat[targetIndex]!;
      if (message.is_user !== true && message.role !== "user"
        && String(message.mes ?? message.message ?? "").trim()) break;
      targetIndex -= 1;
    }
    if (targetIndex < 0) throw new Error("The chat has no assistant message to preview.");
    const previous = statusCoordinator.snapshots.latestBefore(targetIndex, this.state.catalog.namespaceId)?.snapshot ?? null;
    const prepared = await prepareStatusRequest({ catalog: this.state.catalog, baseSnapshot: previous, targetMessageIndex: targetIndex });
    previewDialog("状态更新最终提示词", prepared.promptMessages.map((message) => `[${message.role}]\n${message.content}`).join("\n\n"));
  }

  private async editPrompt(index?: number): Promise<void> {
    if (!this.state) return;
    const current = index === undefined ? undefined : this.state.catalog.profile.promptPreset.items[index];
    const element = dialogShell(current ? "编辑状态提示词" : "添加状态提示词");
    const body = element.querySelector<HTMLElement>(".echoes-dialog-body")!;
    body.innerHTML = `<div class="echoes-form-grid"><label>标题<input name="title" required></label><label>类型<select name="kind"><option value="custom">自定义</option><option value="character">角色设定</option><option value="persona">用户设定</option><option value="current_state">当前状态</option><option value="messages">增量消息</option></select></label><label>角色<select name="role"><option value="system">system</option><option value="user">user</option><option value="assistant">assistant</option></select></label><label class="echoes-wide-field">内容<textarea name="content"></textarea></label></div>`;
    body.querySelector<HTMLInputElement>("[name=title]")!.value = current?.title ?? "自定义状态提示词";
    body.querySelector<HTMLSelectElement>("[name=kind]")!.value = current?.kind ?? "custom";
    body.querySelector<HTMLSelectElement>("[name=role]")!.value = current?.role ?? "system";
    body.querySelector<HTMLTextAreaElement>("[name=content]")!.value = current?.kind === "custom" ? current.content : "";
    await submitDialog(element, async () => {
      const kind = body.querySelector<HTMLSelectElement>("[name=kind]")!.value;
      const item = statusPromptItemSchema.parse({
        id: current?.id ?? newStatusPromptItemId(),
        title: body.querySelector<HTMLInputElement>("[name=title]")!.value,
        kind,
        role: body.querySelector<HTMLSelectElement>("[name=role]")!.value,
        enabled: current?.enabled ?? true,
        ...(kind === "custom" ? { content: body.querySelector<HTMLTextAreaElement>("[name=content]")!.value } : {}),
      }) as StatusPromptItem;
      const profile = structuredClone(this.state!.catalog.profile);
      if (index === undefined) profile.promptPreset.items.push(item);
      else profile.promptPreset.items[index] = item;
      await this.persistProfile(profile);
    }, { errorTitle: "状态提示词无效" });
  }

  private async editCleaning(index?: number): Promise<void> {
    if (!this.state) return;
    const current = index === undefined ? undefined : this.state.catalog.profile.preprocessRules[index];
    const element = dialogShell(current ? "编辑消息清洗" : "添加消息清洗");
    const body = element.querySelector<HTMLElement>(".echoes-dialog-body")!;
    body.innerHTML = `<div class="echoes-form-grid"><label>名称<input name="name" required></label><label>操作<select name="type"><option value="replace">替换</option><option value="remove">删除匹配</option><option value="extract">提取</option></select></label><label>正则<input name="pattern" required></label><label>标志<input name="flags"></label><label>角色<select name="roles" multiple><option value="user">user</option><option value="assistant">assistant</option></select></label><label>替换文本<input name="replacement"></label></div>`;
    body.querySelector<HTMLInputElement>("[name=name]")!.value = current?.name ?? "状态清洗规则";
    body.querySelector<HTMLSelectElement>("[name=type]")!.value = current?.type ?? "replace";
    body.querySelector<HTMLInputElement>("[name=pattern]")!.value = current?.pattern ?? "";
    body.querySelector<HTMLInputElement>("[name=flags]")!.value = current?.flags ?? "g";
    body.querySelector<HTMLInputElement>("[name=replacement]")!.value = current?.replacement ?? "";
    const roles = body.querySelector<HTMLSelectElement>("[name=roles]")!;
    [...roles.options].forEach((option) => option.selected = (current?.roles ?? ["user", "assistant"]).includes(option.value as "user" | "assistant"));
    await submitDialog(element, async () => {
      const pattern = body.querySelector<HTMLInputElement>("[name=pattern]")!.value;
      const flags = body.querySelector<HTMLInputElement>("[name=flags]")!.value;
      new RegExp(pattern, flags);
      const rule = summaryPreprocessRuleSchema.parse({
        id: current?.id ?? id("status_cleaning"),
        name: body.querySelector<HTMLInputElement>("[name=name]")!.value,
        type: body.querySelector<HTMLSelectElement>("[name=type]")!.value,
        pattern,
        flags,
        replacement: body.querySelector<HTMLInputElement>("[name=replacement]")!.value,
        roles: [...roles.selectedOptions].map((option) => option.value),
        enabled: current?.enabled ?? true,
        order: current?.order ?? this.state!.catalog.profile.preprocessRules.length,
      }) as SummaryPreprocessRule;
      const profile = structuredClone(this.state!.catalog.profile);
      if (index === undefined) profile.preprocessRules.push(rule);
      else profile.preprocessRules[index] = rule;
      await this.persistProfile(profile);
    }, { errorTitle: "消息清洗规则无效" });
  }

  private async editValidation(index?: number): Promise<void> {
    if (!this.state) return;
    const current = index === undefined ? undefined : this.state.catalog.profile.validation.rules[index];
    const element = dialogShell(current ? "编辑状态校验" : "添加状态校验");
    const body = element.querySelector<HTMLElement>(".echoes-dialog-body")!;
    body.innerHTML = `<div class="echoes-form-grid"><label>名称<input name="name" required></label><label>路径（点分隔，* 为通配）<input name="path" required></label><label>类型<select name="type"><option value="string">string</option><option value="number">number</option><option value="boolean">boolean</option><option value="object">object</option><option value="array">array</option><option value="null">null</option></select></label><label class="echoes-check"><input type="checkbox" name="required">必填</label><label>枚举（JSON 数组）<input name="enum"></label><label>最小值<input type="number" step="any" name="minimum"></label><label>最大值<input type="number" step="any" name="maximum"></label><label>单次最大变化<input type="number" min="0" step="any" name="delta"></label></div>`;
    body.querySelector<HTMLInputElement>("[name=name]")!.value = current?.name ?? "状态字段";
    body.querySelector<HTMLInputElement>("[name=path]")!.value = current?.path.join(".") ?? "";
    body.querySelector<HTMLSelectElement>("[name=type]")!.value = current?.type ?? "string";
    body.querySelector<HTMLInputElement>("[name=required]")!.checked = current?.required ?? false;
    body.querySelector<HTMLInputElement>("[name=enum]")!.value = current?.enumValues ? JSON.stringify(current.enumValues) : "";
    for (const [name, value] of [["minimum", current?.minimum], ["maximum", current?.maximum], ["delta", current?.maxDelta]] as const) {
      body.querySelector<HTMLInputElement>(`[name=${name}]`)!.value = value === undefined ? "" : String(value);
    }
    await submitDialog(element, async () => {
      const numeric = (name: string) => {
        const value = body.querySelector<HTMLInputElement>(`[name=${name}]`)!.value;
        return value === "" ? undefined : Number(value);
      };
      const enumText = body.querySelector<HTMLInputElement>("[name=enum]")!.value.trim();
      const rule = statusValidationRuleSchema.parse({
        id: current?.id ?? newStatusRuleId(),
        name: body.querySelector<HTMLInputElement>("[name=name]")!.value,
        path: body.querySelector<HTMLInputElement>("[name=path]")!.value.split(".").map((part) => part.trim()),
        type: body.querySelector<HTMLSelectElement>("[name=type]")!.value,
        required: body.querySelector<HTMLInputElement>("[name=required]")!.checked,
        ...(enumText ? { enumValues: JSON.parse(enumText) } : {}),
        ...(numeric("minimum") !== undefined ? { minimum: numeric("minimum") } : {}),
        ...(numeric("maximum") !== undefined ? { maximum: numeric("maximum") } : {}),
        ...(numeric("delta") !== undefined ? { maxDelta: numeric("delta") } : {}),
      }) as StatusValidationRule;
      const profile = structuredClone(this.state!.catalog.profile);
      if (index === undefined) profile.validation.rules.push(rule);
      else profile.validation.rules[index] = rule;
      await this.persistProfile(profile);
    }, { errorTitle: "状态校验规则无效" });
  }

  private async applyTemplate(): Promise<void> {
    if (!this.state) return;
    const templateId = this.root.querySelector<HTMLSelectElement>("[data-status-template-select]")!.value;
    const template = getSettings().statusTemplates.find((item) => item.id === templateId);
    if (!template || !confirm(`基于“${template.name}”重建当前聊天配置副本？现有历史快照不会改变。`)) return;
    const now = new Date().toISOString();
    const profile: StatusProfile = {
      id: id("status_profile"),
      sourceTemplateId: template.id,
      name: template.name,
      description: template.description,
      initialState: structuredClone(template.initialState),
      promptPreset: structuredClone(template.promptPreset),
      preprocessRules: structuredClone(template.preprocessRules),
      validation: structuredClone(template.validation),
      injection: structuredClone(template.injection),
      version: 1,
      createdAt: now,
      updatedAt: now,
    };
    this.state = await statusCoordinator.worldbook.saveConfiguration(this.state.worldbookName, { profile });
  }

  private async saveTemplate(): Promise<void> {
    if (!this.state) return;
    const name = window.prompt("新状态模板名称", `${this.state.catalog.profile.name} 副本`)?.trim();
    if (!name) return;
    const settings = getSettings();
    const now = new Date().toISOString();
    const profile = this.state.catalog.profile;
    const template = statusTemplateSchema.parse({
      id: id("status_template"),
      name,
      description: profile.description,
      initialState: profile.initialState,
      promptPreset: profile.promptPreset,
      preprocessRules: profile.preprocessRules,
      validation: profile.validation,
      injection: profile.injection,
      builtIn: false,
      version: 1,
      createdAt: now,
      updatedAt: now,
    }) as StatusTemplate;
    settings.statusTemplates.push(template);
    saveSettings(settings);
  }

  private deleteTemplate(): void {
    const select = this.root.querySelector<HTMLSelectElement>("[data-status-template-select]")!;
    if (!select.value || select.value === DEFAULT_STATUS_TEMPLATE_ID) return;
    const settings = getSettings();
    settings.statusTemplates = settings.statusTemplates.filter((item) => item.id !== select.value);
    saveSettings(settings);
  }

  private updateTemplate(): void {
    if (!this.state) return;
    const selectedId = this.root.querySelector<HTMLSelectElement>("[data-status-template-select]")!.value;
    if (!selectedId || selectedId === DEFAULT_STATUS_TEMPLATE_ID) return;
    const settings = getSettings();
    const index = settings.statusTemplates.findIndex((item) => item.id === selectedId);
    const current = settings.statusTemplates[index];
    if (!current || !confirm(`用当前聊天配置覆盖“${current.name}”？`)) return;
    const profile = this.state.catalog.profile;
    settings.statusTemplates[index] = statusTemplateSchema.parse({
      ...current,
      description: profile.description,
      initialState: profile.initialState,
      promptPreset: profile.promptPreset,
      preprocessRules: profile.preprocessRules,
      validation: profile.validation,
      injection: profile.injection,
      version: current.version + 1,
      updatedAt: new Date().toISOString(),
    }) as StatusTemplate;
    saveSettings(settings);
  }

  private async withBusy<T>(operation: () => Promise<T>): Promise<T> {
    this.busy = true;
    try {
      return await operation();
    } finally {
      this.busy = false;
    }
  }
}
