import { ECHOES_BUILD_INFO } from "../../shared/build-info";
import type {
  MemoryRow,
  MemoryTypeDefinition,
  MemoryTypeTemplate,
  PromptPresetItem,
} from "../../shared/domain";
import { extractionCoordinator } from "../memory/extraction-coordinator";
import {
  currentExtractionMessages,
  extractionPendingMessageCount,
  prepareExtraction,
} from "../memory/extraction-request";
import {
  deleteTypeTemplate,
  getSettings,
  saveSettings,
  saveTypeTemplate,
} from "../state/settings";
import {
  WorldbookMemoryStore,
  type WorldbookMemoryState,
} from "../worldbook/worldbook-memory";
import {
  openMigrationDialog,
  openExtractionReviewDialog,
  openPreviewDialog,
  openPromptItemDialog,
  openRowDialog,
  openTemplateDialog,
  openTypeDialog,
} from "./dialogs";
import { RetrievalPanel } from "./retrieval-panel";
import { ApiConfigPanel } from "./api-config-panel";
import { RecallPanel } from "./recall-panel";
import { SummaryPanel } from "./summary-panel";
import { StatusPanel } from "./status-panel";
import { MaintenancePanel } from "./maintenance-panel";

type PrimaryView = "api" | "memory" | "memory-settings" | "summary" | "summary-settings" | "status";
type PanelView = PrimaryView | "maintenance";
type StructuredSettingsTab = "automation" | "prompts" | "templates";
type SummarySettingsTab = "generation" | "recall" | "retrieval";

function iconButton(icon: string, title: string, action: string): HTMLButtonElement {
  const button = document.createElement("button");
  button.type = "button";
  button.className = "echoes-icon-button";
  button.dataset.action = action;
  button.title = title;
  button.setAttribute("aria-label", title);
  button.innerHTML = `<i class="fa-solid fa-${icon}"></i>`;
  return button;
}

function commandButton(icon: string, label: string, action: string, primary = false): HTMLButtonElement {
  const button = document.createElement("button");
  button.type = "button";
  button.className = `menu_button${primary ? " echoes-primary" : ""}`;
  button.dataset.action = action;
  button.innerHTML = `<i class="fa-solid fa-${icon}"></i> ${label}`;
  return button;
}

function displayValue(value: unknown): string {
  if (value === undefined || value === null) return "";
  if (typeof value === "object") return JSON.stringify(value);
  if (typeof value === "boolean") return value ? "是" : "否";
  return String(value);
}

function statusLabel(status: MemoryRow["status"]): string {
  return { permanent: "永久", keyword: "关键词", vectorized: "向量化" }[status];
}

export class MemoryPanel {
  private readonly root: HTMLElement;
  private readonly store = new WorldbookMemoryStore();
  private readonly retrievalPanel: RetrievalPanel;
  private readonly summaryPanel: SummaryPanel;
  private readonly apiConfigPanel: ApiConfigPanel;
  private readonly recallPanel: RecallPanel;
  private readonly statusPanel: StatusPanel;
  private readonly maintenancePanel: MaintenancePanel;
  private state: WorldbookMemoryState | null = null;
  private activeTypeId: string | null = null;
  private reloadSequence = 0;
  private view: PanelView = "memory";
  private draggedPromptIndex: number | null = null;
  private lastCompletedExtraction = "";
  private previousPrimaryView: PrimaryView = "memory";
  private structuredSettingsTab: StructuredSettingsTab = "automation";
  private summarySettingsTab: SummarySettingsTab = "generation";

  constructor() {
    this.root = document.createElement("div");
    this.root.id = "echoes-memory-overlay";
    this.root.className = "echoes-overlay echoes-hidden";
    this.root.innerHTML = `
      <div class="echoes-window">
        <header class="echoes-header">
          <div class="echoes-brand"><i class="fa-solid fa-table"></i><strong>Echoes Memory</strong></div>
          <span class="echoes-version-label">${ECHOES_BUILD_INFO.appVersion}</span>
          <div class="echoes-header-actions"></div>
        </header>
        <div class="echoes-workspace">
          <nav class="echoes-primary-nav" aria-label="Echoes 一级菜单">
            <button type="button" data-action="switch-view" data-view="api" aria-label="API配置" title="API配置"><i class="fa-solid fa-plug"></i><span>API配置</span></button>
            <button type="button" data-action="switch-view" data-view="memory" class="active" aria-label="结构化记忆" title="结构化记忆"><i class="fa-solid fa-table-cells"></i><span>结构化记忆</span></button>
            <button type="button" data-action="switch-view" data-view="memory-settings" aria-label="结构化记忆设置" title="结构化记忆设置"><i class="fa-solid fa-table-columns"></i><span>结构化记忆设置</span></button>
            <button type="button" data-action="switch-view" data-view="summary" aria-label="总结记忆" title="总结记忆"><i class="fa-solid fa-clock-rotate-left"></i><span>总结记忆</span></button>
            <button type="button" data-action="switch-view" data-view="summary-settings" aria-label="总结记忆设置" title="总结记忆设置"><i class="fa-solid fa-brain"></i><span>总结记忆设置</span></button>
            <button type="button" data-action="switch-view" data-view="status" aria-label="状态记忆与设置" title="状态记忆与设置"><i class="fa-solid fa-gauge-high"></i><span>状态记忆与设置</span></button>
          </nav>
          <aside class="echoes-sidebar">
            <div class="echoes-sidebar-heading">
              <span>当前对话类型</span>
              <div class="echoes-sidebar-actions">
                <button type="button" class="echoes-icon-button" data-action="migrate" title="从其他对话迁移" aria-label="从其他对话迁移"><i class="fa-solid fa-file-import"></i></button>
                <button type="button" class="echoes-icon-button" data-action="add-type" title="新建类型" aria-label="新建类型"><i class="fa-solid fa-plus"></i></button>
              </div>
            </div>
            <nav class="echoes-table-list" aria-label="记忆类型"></nav>
          </aside>
          <main class="echoes-main">
            <div class="echoes-toolbar">
              <div class="echoes-table-title"><h1>结构化长期记忆</h1><span class="echoes-scope-label"></span></div>
              <div class="echoes-table-actions"></div>
            </div>
            <nav class="echoes-subnav echoes-hidden" aria-label="页面分类"></nav>
            <div class="echoes-job-status echoes-hidden" role="status">
              <div class="echoes-progress"><span></span></div>
              <span data-job-message></span>
            </div>
            <div class="echoes-grid-host"></div>
          </main>
        </div>
      </div>`;
    document.body.append(this.root);
    this.retrievalPanel = new RetrievalPanel(this.root);
    this.summaryPanel = new SummaryPanel(this.root);
    this.apiConfigPanel = new ApiConfigPanel(this.root);
    this.recallPanel = new RecallPanel(this.root);
    this.statusPanel = new StatusPanel(this.root);
    this.maintenancePanel = new MaintenancePanel(this.root);
    const headerActions = this.root.querySelector<HTMLElement>(".echoes-header-actions")!;
    headerActions.append(iconButton("gear", "维护", "maintenance"));
    headerActions.append(iconButton("xmark", "关闭", "close"));
    this.bindEvents();
    extractionCoordinator.subscribe(() => {
      if (!["memory", "memory-settings"].includes(this.view)
        || this.root.classList.contains("echoes-hidden")) return;
      this.renderToolbar();
      if (this.state) {
        if (this.view === "memory") this.renderMemoryGrid();
        else if (this.structuredSettingsTab === "automation") this.renderStructuredSettings();
      }
      const trace = extractionCoordinator.trace();
      const completionKey = trace?.completedAt ? `${trace.state}:${trace.completedAt}` : "";
      if (completionKey && completionKey !== this.lastCompletedExtraction) {
        this.lastCompletedExtraction = completionKey;
        if (trace?.state === "completed") void this.reload();
      }
    });
  }

  async open(): Promise<void> {
    this.root.classList.remove("echoes-hidden");
    await this.reload();
  }

  close(): void {
    this.root.classList.add("echoes-hidden");
  }

  async reloadTables(): Promise<void> {
    await this.reload();
  }

  async reload(): Promise<void> {
    const sequence = ++this.reloadSequence;
    const chatId = SillyTavern.getContext().chatId;
    if (["api", "summary", "summary-settings", "status", "maintenance"].includes(this.view)) {
      this.render();
      return;
    }
    this.setContentMessage("正在读取当前对话世界书...");
    try {
      const state = await this.store.load();
      if (sequence !== this.reloadSequence
        || !["memory", "memory-settings"].includes(this.view)
        || SillyTavern.getContext().chatId !== chatId) return;
      this.state = state;
      if (!state.catalog.types.some((type) => type.id === this.activeTypeId)) {
        this.activeTypeId = state.catalog.types[0]?.id ?? null;
      }
      this.render();
      if (state.issues.length > 0) {
        toastr.warning(`有 ${state.issues.length} 个世界书条目无法解析，请检查条目 YAML。`, "Echoes");
      }
    } catch (error) {
      if (sequence !== this.reloadSequence
        || !["memory", "memory-settings"].includes(this.view)
        || SillyTavern.getContext().chatId !== chatId) return;
      this.state = null;
      this.renderSidebar();
      this.renderToolbar();
      this.setContentMessage(error instanceof Error ? error.message : String(error), true);
    }
  }

  checkSummaryAutomation(): Promise<void> {
    return this.summaryPanel.runAutomatic();
  }

  checkExtractionAutomation(): Promise<void> {
    return extractionCoordinator.runAutomatic();
  }

  private bindEvents(): void {
    this.root.addEventListener("click", (event) => {
      const target = (event.target as HTMLElement).closest<HTMLElement>("[data-action]");
      if (!target) return;
      const action = target.dataset.action;
      if (action === "close") this.close();
      else if (action === "maintenance") {
        if (this.view === "maintenance") this.view = this.previousPrimaryView;
        else {
          this.previousPrimaryView = this.view as PrimaryView;
          this.view = "maintenance";
        }
        this.render();
      } else if (action === "switch-view") {
        this.view = target.dataset.view as PrimaryView;
        this.previousPrimaryView = this.view;
        void this.reload();
      } else if (action === "structured-settings-tab") {
        this.structuredSettingsTab = target.dataset.tab as StructuredSettingsTab;
        this.render();
      } else if (action === "summary-settings-tab") {
        this.summarySettingsTab = target.dataset.tab as SummarySettingsTab;
        this.render();
      } else if (action === "select-type") {
        this.activeTypeId = target.dataset.typeId ?? null;
        if (this.view !== "memory") this.view = "memory";
        this.render();
      } else if (action === "add-type") void this.editType();
      else if (action === "edit-type") void this.editType(this.activeType);
      else if (action === "delete-type") void this.deleteActiveType();
      else if (action === "add-row") void this.editRow();
      else if (action === "edit-row") void this.editRow(this.rowById(target.dataset.rowId));
      else if (action === "delete-row") void this.deleteRow(target.dataset.rowId ?? "");
      else if (action === "extract") void this.extractMemories();
      else if (action === "extraction-stop") void extractionCoordinator.stopCurrent();
      else if (action === "extraction-review") void this.reviewExtraction();
      else if (action === "extraction-retry") void this.retryExtraction();
      else if (action === "extraction-checkpoint-latest") void this.relocateExtractionCheckpoint("latest");
      else if (action === "extraction-checkpoint-clear") void this.relocateExtractionCheckpoint("clear");
      else if (action === "migrate") void this.migrate();
      else if (action === "add-template") void this.editTemplate();
      else if (action === "edit-template") void this.editTemplate(this.templateById(target.dataset.templateId));
      else if (action === "delete-template") void this.deleteTemplate(target.dataset.templateId ?? "");
      else if (action === "add-prompt") void this.editPromptItem();
      else if (action === "edit-prompt") void this.editPromptItem(this.promptItem(Number(target.dataset.index)));
      else if (action === "delete-prompt") void this.deletePromptItem(Number(target.dataset.index));
      else if (action === "move-prompt-up") void this.movePromptItem(Number(target.dataset.index), -1);
      else if (action === "move-prompt-down") void this.movePromptItem(Number(target.dataset.index), 1);
      else if (action === "preview-prompts") this.previewPrompts();
    });

    this.root.addEventListener("change", (event) => {
      const target = event.target as HTMLInputElement;
      if (target.matches("[data-type-toggle]")) {
        void this.toggleType(target.dataset.typeId ?? "", target.checked);
      } else if (target.matches("[data-prompt-toggle]")) {
        void this.togglePrompt(Number(target.dataset.index), target.checked);
      } else if (target.matches("[data-extraction-auto]")) {
        void this.toggleExtractionAutomation(target.checked);
      } else if (target.matches("[data-extraction-message-count]")) {
        const settings = getSettings();
        settings.extractionMessageCount = Math.max(2, Math.min(500, Math.floor(Number(target.value))));
        saveSettings(settings);
        target.value = String(settings.extractionMessageCount);
      }
    });

    this.root.addEventListener("dragstart", (event) => {
      const item = (event.target as HTMLElement).closest<HTMLElement>("[data-prompt-index]");
      this.draggedPromptIndex = item ? Number(item.dataset.promptIndex) : null;
    });
    this.root.addEventListener("dragover", (event) => {
      if ((event.target as HTMLElement).closest("[data-prompt-index]")) event.preventDefault();
    });
    this.root.addEventListener("drop", (event) => {
      const item = (event.target as HTMLElement).closest<HTMLElement>("[data-prompt-index]");
      if (!item || this.draggedPromptIndex === null) return;
      event.preventDefault();
      void this.reorderPrompt(this.draggedPromptIndex, Number(item.dataset.promptIndex));
      this.draggedPromptIndex = null;
    });
    this.root.addEventListener("click", (event) => {
      if (event.target === this.root) this.close();
    });
  }

  private get activeType(): MemoryTypeDefinition | undefined {
    return this.state?.catalog.types.find((type) => type.id === this.activeTypeId);
  }

  private render(): void {
    this.root.classList.toggle("echoes-api-view", this.view === "api");
    this.root.classList.toggle("echoes-retrieval-view", this.view === "summary-settings" && this.summarySettingsTab === "retrieval");
    this.root.classList.toggle("echoes-summary-view", this.view === "summary");
    this.root.classList.toggle("echoes-summary-settings-view", this.view === "summary-settings");
    this.root.classList.toggle("echoes-summary-generation-view", this.view === "summary-settings" && this.summarySettingsTab === "generation");
    this.root.classList.toggle("echoes-recall-view", this.view === "summary-settings" && this.summarySettingsTab === "recall");
    this.root.classList.toggle("echoes-status-view", this.view === "status");
    this.root.classList.toggle("echoes-maintenance-view", this.view === "maintenance");
    this.root.classList.toggle("echoes-context-view", ["memory", "summary", "status", "maintenance"].includes(this.view));
    this.root.querySelectorAll<HTMLElement>(".echoes-primary-nav [data-view]").forEach((button) => {
      button.classList.toggle("active", button.dataset.view === this.view);
    });
    this.renderSubnav();
    this.renderSidebar();
    this.renderToolbar();
    if (this.view === "api") {
      void this.apiConfigPanel.render();
      return;
    }
    if (this.view === "summary") {
      void this.summaryPanel.render("memory");
      return;
    }
    if (this.view === "summary-settings") {
      if (this.summarySettingsTab === "generation") void this.summaryPanel.render("settings");
      else if (this.summarySettingsTab === "recall") void this.recallPanel.render();
      else void this.retrievalPanel.render();
      return;
    }
    if (this.view === "status") {
      void this.statusPanel.render();
      return;
    }
    if (this.view === "maintenance") {
      void this.maintenancePanel.render();
      return;
    }
    if (!this.state) return;
    if (this.view === "memory") this.renderMemoryGrid();
    else if (this.structuredSettingsTab === "prompts") this.renderPromptPreset();
    else if (this.structuredSettingsTab === "templates") this.renderTemplates();
    else this.renderStructuredSettings();
  }

  private renderSubnav(): void {
    const nav = this.root.querySelector<HTMLElement>(".echoes-subnav")!;
    nav.replaceChildren();
    const items: Array<[string, string]> = this.view === "memory-settings"
      ? [["automation", "自动提取"], ["prompts", "提示词预设"], ["templates", "类型模板"]]
      : this.view === "summary-settings"
        ? [["generation", "总结生成"], ["recall", "召回与注入"], ["retrieval", "检索维护"]]
        : [];
    nav.classList.toggle("echoes-hidden", items.length === 0);
    for (const [tab, label] of items) {
      const button = document.createElement("button");
      button.type = "button";
      button.dataset.action = this.view === "memory-settings" ? "structured-settings-tab" : "summary-settings-tab";
      button.dataset.tab = tab;
      button.textContent = label;
      const active = this.view === "memory-settings" ? this.structuredSettingsTab : this.summarySettingsTab;
      button.classList.toggle("active", active === tab);
      nav.append(button);
    }
  }

  private renderSidebar(): void {
    const heading = this.root.querySelector<HTMLElement>(".echoes-sidebar-heading > span")!;
    const actions = this.root.querySelector<HTMLElement>(".echoes-sidebar-actions")!;
    const list = this.root.querySelector<HTMLElement>(".echoes-table-list")!;
    list.replaceChildren();
    if (["api", "memory-settings", "summary-settings"].includes(this.view)) {
      heading.textContent = "";
      actions.replaceChildren();
      return;
    }
    if (this.view === "summary") {
      heading.textContent = "总结状态";
      actions.replaceChildren();
      const loading = document.createElement("p");
      loading.className = "echoes-empty-note";
      loading.textContent = "正在读取...";
      list.append(loading);
      return;
    }
    if (this.view === "status") {
      heading.textContent = "状态历史";
      actions.replaceChildren();
      const loading = document.createElement("p");
      loading.className = "echoes-empty-note";
      loading.textContent = "正在读取...";
      list.append(loading);
      return;
    }
    if (this.view === "maintenance") {
      heading.textContent = "系统状态";
      actions.replaceChildren();
      list.innerHTML = '<p class="echoes-empty-note">正在读取...</p>';
      return;
    }
    heading.textContent = "当前对话类型";
    actions.innerHTML = `
      <button type="button" class="echoes-icon-button" data-action="migrate" title="从其他对话迁移" aria-label="从其他对话迁移"><i class="fa-solid fa-file-import"></i></button>
      <button type="button" class="echoes-icon-button" data-action="add-type" title="新建类型" aria-label="新建类型"><i class="fa-solid fa-plus"></i></button>`;
    const types = this.state?.catalog.types ?? [];
    if (types.length === 0) {
      const empty = document.createElement("p");
      empty.className = "echoes-empty-note";
      empty.textContent = "当前对话没有记忆类型。";
      list.append(empty);
      return;
    }
    for (const type of types) {
      const item = document.createElement("div");
      item.className = `echoes-type-nav${type.id === this.activeTypeId ? " active" : ""}`;
      const select = document.createElement("button");
      select.type = "button";
      select.dataset.action = "select-type";
      select.dataset.typeId = type.id;
      select.innerHTML = '<i class="fa-solid fa-table-columns"></i>';
      const label = document.createElement("span");
      label.textContent = type.name;
      select.append(label);
      const toggle = document.createElement("label");
      toggle.className = "echoes-switch";
      toggle.title = type.enabled ? "关闭类型" : "激活类型";
      const input = document.createElement("input");
      input.type = "checkbox";
      input.checked = type.enabled;
      input.dataset.typeToggle = "true";
      input.dataset.typeId = type.id;
      toggle.append(input, document.createElement("span"));
      item.append(select, toggle);
      list.append(item);
    }
  }

  private renderToolbar(): void {
    const title = this.root.querySelector<HTMLElement>(".echoes-table-title h1")!;
    const scope = this.root.querySelector<HTMLElement>(".echoes-scope-label")!;
    const actions = this.root.querySelector<HTMLElement>(".echoes-table-actions")!;
    actions.replaceChildren();
    scope.textContent = "";

    if (this.view === "api") {
      title.textContent = "API配置";
      scope.textContent = "凭据 · 生成模型 · Embedding · Rerank · 工作流分配";
      return;
    }

    if (this.view === "summary") {
      title.textContent = "总结记忆";
      scope.textContent = "总结记录 · 上下文压缩 · 召回诊断";
      const refresh = iconButton("rotate", "刷新", "unused");
      delete refresh.dataset.action;
      refresh.dataset.summaryAction = "refresh";
      const repair = iconButton("screwdriver-wrench", "修复索引", "unused");
      delete repair.dataset.action;
      repair.dataset.summaryAction = "repair";
      actions.append(refresh, repair);
      return;
    }

    if (this.view === "summary-settings") {
      title.textContent = "总结记忆设置";
      scope.textContent = this.summarySettingsTab === "generation"
        ? "生成规则 · 提示词 · 消息清洗"
        : this.summarySettingsTab === "recall"
          ? "召回来源 · 排序权重 · 查询预设 · 注入"
          : "集合 · 索引 · 数据导入 · 查询实验";
      return;
    }

    if (this.view === "status") {
      title.textContent = "状态记忆与设置";
      scope.textContent = "当前状态 · 历史快照 · 提示词 · 校验 · 注入";
      const refresh = iconButton("rotate", "刷新", "unused");
      delete refresh.dataset.action;
      refresh.dataset.statusAction = "refresh";
      const sync = commandButton("arrows-rotate", "手动同步", "unused", true);
      delete sync.dataset.action;
      sync.dataset.statusAction = "sync";
      actions.append(refresh, sync);
      return;
    }
    if (this.view === "maintenance") {
      title.textContent = "维护与恢复";
      scope.textContent = "版本 · 凭据 · 自检 · 便携备份";
      return;
    }

    if (this.view === "memory-settings") {
      title.textContent = "结构化记忆设置";
      scope.textContent = this.state ? `聊天世界书 · ${this.state.worldbookName}` : "";
      if (this.structuredSettingsTab === "prompts") {
        actions.append(commandButton("eye", "预览", "preview-prompts"));
        actions.append(commandButton("plus", "添加提示词", "add-prompt", true));
      } else if (this.structuredSettingsTab === "templates") {
        actions.append(commandButton("plus", "新建模板", "add-template", true));
      }
      return;
    }

    scope.textContent = this.state ? `聊天世界书 · ${this.state.worldbookName}` : "";
    const type = this.activeType;
    title.textContent = type?.name ?? "请选择记忆类型";
    if (!type) return;
    const running = extractionCoordinator.isRunning();
    const review = extractionCoordinator.review();
    const extract = commandButton("wand-magic-sparkles", "处理下一批", "extract");
    extract.disabled = running;
    actions.append(extract);
    if (running) actions.append(commandButton("stop", "停止", "extraction-stop"));
    if (review) actions.append(commandButton("clipboard-check", "审核", "extraction-review", true));
    else if (extractionCoordinator.pauseReason()) {
      actions.append(commandButton("rotate", "重跑", "extraction-retry"));
    }
    actions.append(commandButton("plus", "添加数据", "add-row", true));
    actions.append(iconButton("pen", "编辑类型", "edit-type"));
    actions.append(iconButton("trash", "删除类型", "delete-type"));
  }

  private renderMemoryGrid(): void {
    const type = this.activeType;
    if (!this.state) return;
    const host = this.root.querySelector<HTMLElement>(".echoes-grid-host")!;
    const page = document.createElement("div");
    page.className = "echoes-memory-page";
    const content = document.createElement("div");
    content.className = "echoes-memory-table-host";
    page.append(content);
    if (!type) {
      content.append(this.gridMessage("新建一种记忆类型后即可开始记录。"));
      host.replaceChildren(page);
      return;
    }
    const rows = this.state.rows.filter((row) => row.typeId === type.id);
    if (rows.length === 0) {
      content.append(this.gridMessage(type.enabled
        ? "该类型暂无数据。可以手动添加，或通过“处理下一批”提取新增聊天。"
        : "该类型已关闭，其世界书条目和副 API 写表上下文均不会启用。"));
      host.replaceChildren(page);
      return;
    }

    const wrapper = document.createElement("div");
    wrapper.className = "echoes-table-scroll";
    const table = document.createElement("table");
    table.className = "echoes-data-table";
    const headings = ["数据名", "关键词", "条目状态", ...type.columns.map((column) => column.name)];
    const head = document.createElement("thead");
    const headingRow = document.createElement("tr");
    for (const heading of headings) {
      const cell = document.createElement("th");
      cell.scope = "col";
      cell.textContent = heading;
      headingRow.append(cell);
    }
    const actionHeading = document.createElement("th");
    actionHeading.scope = "col";
    actionHeading.className = "echoes-row-actions-heading";
    actionHeading.textContent = "操作";
    headingRow.append(actionHeading);
    head.append(headingRow);
    table.append(head);

    const body = document.createElement("tbody");
    for (const row of rows) {
      const tr = document.createElement("tr");
      const fixed = [row.dataName, row.keywords.join(", "), statusLabel(row.status)];
      for (const value of [...fixed, ...type.columns.map((column) => displayValue(row.values[column.id]))]) {
        const cell = document.createElement("td");
        cell.textContent = value;
        cell.title = value;
        tr.append(cell);
      }
      const actionCell = document.createElement("td");
      actionCell.className = "echoes-row-actions";
      const edit = iconButton("pen", "编辑数据", "edit-row");
      edit.dataset.rowId = row.id;
      const remove = iconButton("trash", "删除数据", "delete-row");
      remove.dataset.rowId = row.id;
      actionCell.append(edit, remove);
      tr.append(actionCell);
      body.append(tr);
    }
    table.append(body);
    wrapper.append(table);
    content.append(wrapper);
    host.replaceChildren(page);
  }

  private renderStructuredSettings(): void {
    if (!this.state) return;
    const settings = getSettings();
    const workflow = settings.generationWorkflows.extraction;
    const group = settings.generationGroups.find((candidate) => candidate.id === workflow.groupId);
    const host = this.root.querySelector<HTMLElement>(".echoes-grid-host")!;
    const page = document.createElement("div");
    page.className = "echoes-structured-settings-page";
    const section = document.createElement("section");
    section.className = "echoes-settings-section";
    section.innerHTML = `
      <div class="echoes-section-heading">
        <div><h2>自动提取行为</h2><span>模型和故障策略统一在 API配置中管理</span></div>
        <button type="button" class="menu_button" data-action="switch-view" data-view="api"><i class="fa-solid fa-plug"></i> 前往 API配置</button>
      </div>
      <div class="echoes-workflow-summary">
        <span>生成端点组<strong data-structured-api-group></strong></span>
        <span>故障策略<strong data-structured-api-policy></strong></span>
        <label>批次消息阈值<input type="number" min="2" max="500" data-extraction-message-count></label>
      </div>`;
    section.querySelector<HTMLElement>("[data-structured-api-group]")!.textContent = group?.name ?? "未配置";
    section.querySelector<HTMLElement>("[data-structured-api-policy]")!.textContent = {
      confirm_ambiguous: "不确定时确认",
      always: "始终自动切换",
      definitive_only: "仅明确失败切换",
    }[workflow.failoverPolicy];
    section.querySelector<HTMLInputElement>("[data-extraction-message-count]")!.value = String(settings.extractionMessageCount);
    page.append(section, this.renderExtractionAutomationPanel());
    host.replaceChildren(page);
  }

  private renderExtractionAutomationPanel(): HTMLElement {
    const section = document.createElement("section");
    section.className = "echoes-extraction-automation";
    if (!this.state) return section;
    const trace = extractionCoordinator.trace(this.state.catalog.chatId);
    const review = extractionCoordinator.review(this.state.catalog.chatId);
    const pause = extractionCoordinator.pauseReason(this.state.catalog.chatId);
    let pending: number | null = null;
    let checkpointIssue = "";
    try {
      pending = extractionPendingMessageCount(this.state);
    } catch (error) {
      checkpointIssue = error instanceof Error ? error.message : String(error);
    }
    section.innerHTML = `
      <header>
        <div>
          <h2>结构化记忆自动提取</h2>
          <p>批次阈值 ${getSettings().extractionMessageCount} 条；只提交到已被后续用户消息确认的助手回复。</p>
        </div>
        <label class="echoes-check">
          <input type="checkbox" data-extraction-auto>
          自动提取
        </label>
      </header>
      <div class="echoes-extraction-stats">
        <div><span>检查点</span><strong data-extraction-checkpoint></strong></div>
        <div><span>待处理消息</span><strong data-extraction-pending></strong></div>
        <div><span>当前批次</span><strong data-extraction-batch></strong></div>
        <div><span>运行状态</span><strong data-extraction-state></strong></div>
      </div>
      <div class="echoes-extraction-actions">
        <button type="button" class="menu_button" data-action="extraction-checkpoint-latest"><i class="fa-solid fa-forward-step"></i> 跳到最新消息</button>
        <button type="button" class="menu_button" data-action="extraction-checkpoint-clear"><i class="fa-solid fa-backward-step"></i> 清除并从头处理</button>
      </div>
      <p class="echoes-extraction-warning echoes-hidden" data-extraction-warning></p>
      <details class="echoes-extraction-trace">
        <summary>最近任务诊断</summary>
        <pre></pre>
      </details>`;
    section.querySelector<HTMLInputElement>("[data-extraction-auto]")!.checked =
      this.state.catalog.automation.enabled;
    section.querySelector<HTMLElement>("[data-extraction-checkpoint]")!.textContent =
      this.state.catalog.lastProcessedMessageId ?? "尚未处理";
    section.querySelector<HTMLElement>("[data-extraction-pending]")!.textContent =
      pending === null ? "检查点缺失" : String(pending);
    section.querySelector<HTMLElement>("[data-extraction-batch]")!.textContent = trace?.batch
      ? `${trace.batch.mode === "auto" ? "自动" : "手动"} · ${trace.batch.startMessageId} → ${trace.batch.endMessageId}`
      : "无";
    section.querySelector<HTMLElement>("[data-extraction-state]")!.textContent =
      review ? `待审核 ${review.result.reviewItems.length} 项`
        : trace?.state ?? (pause ? "已暂停" : "空闲");
    const warning = section.querySelector<HTMLElement>("[data-extraction-warning]")!;
    const warningText = checkpointIssue || pause || (review
      ? "批次包含语义无效操作，等待人工审核。审核仅保存在当前页面，刷新后可能重新调用副 API。"
      : "");
    if (warningText) {
      warning.textContent = warningText;
      warning.classList.remove("echoes-hidden");
    }
    section.querySelector<HTMLPreElement>(".echoes-extraction-trace pre")!.textContent =
      trace ? JSON.stringify(trace, null, 2) : "暂无任务记录。";
    return section;
  }

  private gridMessage(message: string): HTMLElement {
    const note = document.createElement("div");
    note.className = "echoes-grid-message empty";
    note.textContent = message;
    return note;
  }

  private renderPromptPreset(): void {
    if (!this.state) return;
    const host = this.root.querySelector<HTMLElement>(".echoes-grid-host")!;
    const list = document.createElement("div");
    list.className = "echoes-prompt-list";
    const items = this.state.catalog.promptPreset.items;
    if (items.length === 0) {
      this.setContentMessage("当前预设为空。副 API 仍会收到运行时表格和增量对话，但不会收到任何自定义规则。", false, true);
      return;
    }
    const typeById = new Map(this.state.catalog.types.map((type) => [type.id, type]));
    items.forEach((item, index) => {
      const row = document.createElement("article");
      row.className = "echoes-prompt-item";
      row.draggable = true;
      row.dataset.promptIndex = String(index);
      const handle = document.createElement("i");
      handle.className = "fa-solid fa-grip-vertical echoes-drag-handle";
      handle.title = "拖动排序";
      const meta = document.createElement("div");
      meta.className = "echoes-prompt-meta";
      const heading = document.createElement("strong");
      heading.textContent = item.title;
      const detail = document.createElement("span");
      const type = item.kind === "type_writer" ? typeById.get(item.typeId) : undefined;
      detail.textContent = item.kind === "type_writer"
        ? `${item.role.toUpperCase()} · 类型写表提示词${type?.enabled === false ? " · 类型已关闭" : ""}`
        : `${item.role.toUpperCase()} · ${item.kind === "main" ? "主提示词" : "自定义提示词"}`;
      const excerpt = document.createElement("small");
      excerpt.textContent = item.kind === "type_writer"
        ? (type?.writePrompt ?? "引用类型不存在")
        : item.content;
      meta.append(heading, detail, excerpt);
      const controls = document.createElement("div");
      controls.className = "echoes-prompt-controls";
      const toggle = document.createElement("label");
      toggle.className = "echoes-switch";
      const input = document.createElement("input");
      input.type = "checkbox";
      input.checked = item.enabled;
      input.dataset.promptToggle = "true";
      input.dataset.index = String(index);
      toggle.append(input, document.createElement("span"));
      const up = iconButton("arrow-up", "上移", "move-prompt-up");
      up.dataset.index = String(index);
      up.disabled = index === 0;
      const down = iconButton("arrow-down", "下移", "move-prompt-down");
      down.dataset.index = String(index);
      down.disabled = index === items.length - 1;
      const edit = iconButton("pen", "编辑提示词", "edit-prompt");
      edit.dataset.index = String(index);
      const remove = iconButton("trash", "删除提示词", "delete-prompt");
      remove.dataset.index = String(index);
      controls.append(toggle, up, down, edit, remove);
      row.append(handle, meta, controls);
      list.append(row);
    });
    host.replaceChildren(list);
  }

  private renderTemplates(): void {
    const host = this.root.querySelector<HTMLElement>(".echoes-grid-host")!;
    const list = document.createElement("div");
    list.className = "echoes-template-list";
    for (const template of getSettings().typeTemplates) {
      const item = document.createElement("article");
      item.className = "echoes-template-item";
      const heading = document.createElement("div");
      const title = document.createElement("strong");
      title.textContent = template.name;
      const badge = document.createElement("span");
      badge.textContent = template.builtIn ? "默认" : "自定义";
      heading.append(title, badge);
      const description = document.createElement("p");
      description.textContent = template.description;
      const columns = document.createElement("small");
      columns.textContent = `表头：${template.columns.map((column) => column.name).join("、")}`;
      const prompt = document.createElement("p");
      prompt.className = "echoes-template-prompt";
      prompt.textContent = template.writePrompt;
      const actions = document.createElement("div");
      actions.className = "echoes-template-actions";
      if (template.builtIn) {
        const lock = document.createElement("span");
        lock.innerHTML = '<i class="fa-solid fa-lock"></i> 内置模板';
        actions.append(lock);
      } else {
        const edit = iconButton("pen", "编辑模板", "edit-template");
        edit.dataset.templateId = template.id;
        const remove = iconButton("trash", "删除模板", "delete-template");
        remove.dataset.templateId = template.id;
        actions.append(edit, remove);
      }
      item.append(heading, description, columns, prompt, actions);
      list.append(item);
    }
    host.replaceChildren(list);
  }

  private async editType(current?: MemoryTypeDefinition): Promise<void> {
    const input = await openTypeDialog(getSettings().typeTemplates, current);
    if (!input) return;
    try {
      const saved = await this.store.saveType(input, current?.id);
      this.activeTypeId = saved.id;
      this.view = "memory";
      await this.reload();
      toastr.success("记忆类型已保存。", "Echoes");
    } catch (error) {
      toastr.error(error instanceof Error ? error.message : String(error), "保存失败");
    }
  }

  private async deleteActiveType(): Promise<void> {
    const type = this.activeType;
    if (!type || !window.confirm(`删除“${type.name}”及其全部世界书条目？此操作不可撤销。`)) return;
    try {
      await this.store.deleteType(type.id);
      this.activeTypeId = null;
      await this.reload();
    } catch (error) {
      toastr.error(error instanceof Error ? error.message : String(error), "删除失败");
    }
  }

  private async toggleType(typeId: string, enabled: boolean): Promise<void> {
    try {
      await this.store.setTypeEnabled(typeId, enabled);
      await this.reload();
    } catch (error) {
      toastr.error(error instanceof Error ? error.message : String(error), "类型状态更新失败");
      await this.reload();
    }
  }

  private rowById(rowId?: string): MemoryRow | undefined {
    return this.state?.rows.find((row) => row.id === rowId);
  }

  private async editRow(current?: MemoryRow): Promise<void> {
    const type = this.activeType;
    if (!type) return;
    const input = await openRowDialog(type, current);
    if (!input) return;
    try {
      await this.store.saveRow(type.id, input, current?.id);
      await this.reload();
    } catch (error) {
      toastr.error(error instanceof Error ? error.message : String(error), "保存失败");
    }
  }

  private async deleteRow(rowId: string): Promise<void> {
    if (!rowId || !window.confirm("删除这条长期记忆？")) return;
    try {
      await this.store.deleteRow(rowId);
      await this.reload();
    } catch (error) {
      toastr.error(error instanceof Error ? error.message : String(error), "删除失败");
    }
  }

  private templateById(templateId?: string): MemoryTypeTemplate | undefined {
    return getSettings().typeTemplates.find((template) => template.id === templateId);
  }

  private async editTemplate(current?: MemoryTypeTemplate): Promise<void> {
    const input = await openTemplateDialog(current);
    if (!input) return;
    try {
      saveTypeTemplate(input, current);
      this.renderTemplates();
      toastr.success("类型模板已保存。", "Echoes");
    } catch (error) {
      toastr.error(error instanceof Error ? error.message : String(error), "模板保存失败");
    }
  }

  private deleteTemplate(templateId: string): void {
    const template = this.templateById(templateId);
    if (!template || !window.confirm(`删除类型模板“${template.name}”？现有类型不会被删除。`)) return;
    if (!deleteTypeTemplate(templateId)) {
      toastr.warning("默认类型模板不能删除。", "Echoes");
      return;
    }
    this.renderTemplates();
  }

  private promptItem(index: number): PromptPresetItem | undefined {
    return this.state?.catalog.promptPreset.items[index];
  }

  private async editPromptItem(current?: PromptPresetItem): Promise<void> {
    if (!this.state) return;
    const item = await openPromptItemDialog(this.state.catalog.types, current);
    if (!item) return;
    const preset = structuredClone(this.state.catalog.promptPreset);
    const index = current ? preset.items.findIndex((candidate) => candidate.id === current.id) : -1;
    if (index >= 0) preset.items[index] = item;
    else preset.items.push(item);
    await this.savePreset(preset.items);
  }

  private async deletePromptItem(index: number): Promise<void> {
    if (!this.state || !this.promptItem(index) || !window.confirm("从预设中删除该提示词？")) return;
    const items = structuredClone(this.state.catalog.promptPreset.items);
    items.splice(index, 1);
    await this.savePreset(items);
  }

  private async togglePrompt(index: number, enabled: boolean): Promise<void> {
    if (!this.state) return;
    const items = structuredClone(this.state.catalog.promptPreset.items);
    const item = items[index];
    if (!item) return;
    item.enabled = enabled;
    await this.savePreset(items);
  }

  private async movePromptItem(index: number, offset: number): Promise<void> {
    await this.reorderPrompt(index, index + offset);
  }

  private async reorderPrompt(from: number, to: number): Promise<void> {
    if (!this.state || from === to || to < 0 || to >= this.state.catalog.promptPreset.items.length) return;
    const items = structuredClone(this.state.catalog.promptPreset.items);
    const [item] = items.splice(from, 1);
    if (!item) return;
    items.splice(to, 0, item);
    await this.savePreset(items);
  }

  private async savePreset(items: PromptPresetItem[]): Promise<void> {
    if (!this.state) return;
    try {
      await this.store.savePromptPreset({
        ...this.state.catalog.promptPreset,
        items,
        updatedAt: new Date().toISOString(),
      });
      await this.reload();
    } catch (error) {
      toastr.error(error instanceof Error ? error.message : String(error), "提示词预设保存失败");
      await this.reload();
    }
  }

  private async previewPrompts(): Promise<void> {
    if (!this.state) return;
    try {
      let prepared;
      try {
        prepared = await prepareExtraction(this.state, getSettings(), "auto");
      } catch {
        prepared = await prepareExtraction(this.state, getSettings(), "manual");
      }
      openPreviewDialog(prepared.promptBlocks, prepared.runtimePreview);
    } catch (error) {
      toastr.warning(error instanceof Error ? error.message : String(error), "无法预览");
    }
  }

  private async migrate(): Promise<void> {
    if (!this.state) return;
    const selection = await openMigrationDialog({
      worldbookNames: this.store.listWorldbooks(),
      currentWorldbookName: this.state.worldbookName,
      loadTypes: async (worldbookName) => (await this.store.inspect(worldbookName)).catalog.types,
    });
    if (!selection) return;
    try {
      const summary = await this.store.migrateFrom(
        selection.sourceWorldbookName,
        selection.typeIds,
        selection.policy,
      );
      await this.reload();
      toastr.success(`迁移完成：新增 ${summary.added} 条，更新 ${summary.updated} 条，替换移除 ${summary.deleted} 条。`, "Echoes");
    } catch (error) {
      toastr.error(error instanceof Error ? error.message : String(error), "迁移失败");
    }
  }

  private async extractMemories(): Promise<void> {
    if (extractionCoordinator.isRunning() || !this.state) return;
    if (extractionCoordinator.review()) {
      await this.reviewExtraction();
      return;
    }
    const settings = getSettings();
    if (!settings.generationGroups.some((group) => group.id === settings.generationWorkflows.extraction.groupId)) {
      toastr.warning("请先配置结构化记忆生成端点组。", "Echoes");
      this.view = "api";
      this.render();
      return;
    }

    try {
      await extractionCoordinator.runManual();
      await this.reload();
      const review = extractionCoordinator.review();
      if (review) {
        toastr.warning("批次包含无效操作，请审核后提交。审核只保存在当前页面内存中。", "结构化长期记忆");
        await this.reviewExtraction();
      } else {
        const trace = extractionCoordinator.trace();
        if (trace?.state === "completed") toastr.success(trace.message ?? "批次已提交。", "结构化长期记忆");
      }
    } catch (error) {
      toastr.warning(error instanceof Error ? error.message : String(error), "无法处理下一批");
    }
  }

  private async reviewExtraction(): Promise<void> {
    if (!this.state) return;
    const review = extractionCoordinator.review();
    if (!review) return;
    const decision = await openExtractionReviewDialog(
      review.result.reviewItems,
      this.state.catalog.types,
      this.state.rows,
    );
    if (!decision) return;
    if (decision.action === "rerun") {
      await this.retryExtraction();
      return;
    }
    if (decision.selectedIndexes.length === 0
      && !window.confirm("没有选择任何有效操作。确定跳过整个批次并推进检查点吗？")) {
      return;
    }
    try {
      const summary = await extractionCoordinator.submitReview(decision.selectedIndexes);
      await this.reload();
      toastr.success(
        `审核已提交：新增 ${summary.added}，修改 ${summary.updated}，删除 ${summary.deleted}。`,
        "结构化长期记忆",
      );
    } catch (error) {
      toastr.error(error instanceof Error ? error.message : String(error), "审核提交失败");
    }
  }

  private async retryExtraction(): Promise<void> {
    try {
      await extractionCoordinator.retryCurrent();
      await this.reload();
      if (extractionCoordinator.review()) await this.reviewExtraction();
    } catch (error) {
      toastr.error(error instanceof Error ? error.message : String(error), "批次重跑失败");
    }
  }

  private async toggleExtractionAutomation(enabled: boolean): Promise<void> {
    try {
      await extractionCoordinator.setAutomationEnabled(enabled);
      await this.reload();
    } catch (error) {
      toastr.error(error instanceof Error ? error.message : String(error), "自动提取设置保存失败");
      await this.reload();
    }
  }

  private async relocateExtractionCheckpoint(mode: "latest" | "clear"): Promise<void> {
    const messages = currentExtractionMessages();
    const messageId = mode === "latest" ? messages.at(-1)?.id ?? null : null;
    const prompt = mode === "latest"
      ? `确定将结构化记忆检查点跳到当前最新消息 ${messageId ?? "（空聊天）"} 吗？未处理消息将被跳过。`
      : "确定清除结构化记忆检查点并从聊天开头重新处理吗？已存在的记忆行不会自动删除。";
    if (!window.confirm(prompt)) return;
    try {
      await extractionCoordinator.relocateCheckpoint(messageId);
      await this.reload();
      toastr.success("结构化记忆检查点已更新。", "Echoes");
    } catch (error) {
      toastr.error(error instanceof Error ? error.message : String(error), "检查点更新失败");
    }
  }

  private setContentMessage(message: string, error = false, empty = false): void {
    const host = this.root.querySelector<HTMLElement>(".echoes-grid-host")!;
    const note = document.createElement("div");
    note.className = `echoes-grid-message${error ? " error" : ""}${empty ? " empty" : ""}`;
    note.textContent = message;
    host.replaceChildren(note);
  }
}
