import type {
  EmbeddingEndpointGroup,
  FailoverDecisionRequired,
  JobRecord,
  RetrievalCollectionStats,
  RetrievalDocumentInput,
  RetrievalQueryRequest,
  RetrievalQueryResult,
  RetrievalUpsertRequest,
  RetrievalUpsertResult,
} from "../../shared/domain";
import {
  retrievalDocumentInputSchema,
} from "../../shared/schemas";
import { echoesApi } from "../api/client";
import { getSettings, saveSettings } from "../state/settings";

const TERMINAL_STATES = new Set(["succeeded", "failed", "cancelled", "ambiguous"]);

function uid(prefix: string): string {
  return `${prefix}_${crypto.randomUUID().replaceAll("-", "")}`;
}

function button(icon: string, label: string, action: string, primary = false): HTMLButtonElement {
  const element = document.createElement("button");
  element.type = "button";
  element.className = `menu_button${primary ? " echoes-primary" : ""}`;
  element.dataset.retrievalAction = action;
  element.innerHTML = `<i class="fa-solid fa-${icon}"></i> ${label}`;
  return element;
}

function iconButton(icon: string, title: string, action: string): HTMLButtonElement {
  const element = document.createElement("button");
  element.type = "button";
  element.className = "echoes-icon-button";
  element.dataset.retrievalAction = action;
  element.title = title;
  element.setAttribute("aria-label", title);
  element.innerHTML = `<i class="fa-solid fa-${icon}"></i>`;
  return element;
}

function score(value: number | undefined): string {
  return value === undefined ? "-" : value.toFixed(5);
}

function errorMessage(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

function selectedValue<T extends HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>(
  root: ParentNode,
  selector: string,
): string {
  return root.querySelector<T>(selector)?.value.trim() ?? "";
}

export class RetrievalPanel {
  private collections: RetrievalCollectionStats[] = [];
  private activeJobId: string | null = null;
  private lastQueryRequest: RetrievalQueryRequest | null = null;
  private renderSequence = 0;

  constructor(private readonly root: HTMLElement) {
    this.root.addEventListener("click", (event) => {
      const target = (event.target as HTMLElement).closest<HTMLElement>("[data-retrieval-action]");
      if (!target) return;
      void this.handleAction(target.dataset.retrievalAction ?? "", target);
    });
    this.root.addEventListener("submit", (event) => {
      const form = event.target as HTMLFormElement;
      if (form.matches("[data-retrieval-manual-form]")) {
        event.preventDefault();
        void this.importManual(form);
      } else if (form.matches("[data-retrieval-query-form]")) {
        event.preventDefault();
        void this.runQuery(form);
      }
    });
  }

  async render(): Promise<void> {
    const sequence = ++this.renderSequence;
    this.setMessage("正在读取检索索引...");
    try {
      const collections = await echoesApi.listRetrievalCollections();
      if (sequence !== this.renderSequence
        || !this.root.classList.contains("echoes-retrieval-view")) return;
      this.collections = collections;
      this.renderSidebar();
      this.renderWorkspace();
    } catch (error) {
      if (sequence !== this.renderSequence
        || !this.root.classList.contains("echoes-retrieval-view")) return;
      this.setMessage(errorMessage(error), true);
    }
  }

  private async handleAction(action: string, target: HTMLElement): Promise<void> {
    try {
      if (action === "retrieval-refresh") await this.render();
      else if (action === "add-collection") await this.createCollection();
      else if (action === "delete-collection") await this.deleteCollection(target.dataset.id ?? "");
      else if (action === "repair-collection") await this.rebuildCollection(target.dataset.id ?? "", true);
      else if (action === "rebuild-collection") await this.rebuildCollection(target.dataset.id ?? "", false);
      else if (action === "import-jsonl") await this.importJsonl();
      else if (action === "cancel-job" && this.activeJobId) await echoesApi.cancelJob(this.activeJobId);
    } catch (error) {
      toastr.error(errorMessage(error), "Echoes 检索");
    }
  }

  private renderSidebar(): void {
    const heading = this.root.querySelector<HTMLElement>(".echoes-sidebar-heading > span")!;
    const actions = this.root.querySelector<HTMLElement>(".echoes-sidebar-actions")!;
    const list = this.root.querySelector<HTMLElement>(".echoes-table-list")!;
    heading.textContent = "检索集合";
    actions.replaceChildren(iconButton("rotate", "刷新集合", "retrieval-refresh"));
    list.replaceChildren();
    if (this.collections.length === 0) {
      const empty = document.createElement("p");
      empty.className = "echoes-empty-note";
      empty.textContent = "暂无集合";
      list.append(empty);
      return;
    }
    for (const item of this.collections) {
      const row = document.createElement("div");
      row.className = "echoes-retrieval-collection-nav";
      const name = document.createElement("strong");
      name.textContent = item.collection.name;
      const counts = document.createElement("small");
      counts.textContent = `${item.documents} 文档 · ${item.ready} 就绪`;
      row.append(name, counts);
      list.append(row);
    }
  }

  private renderWorkspace(): void {
    const host = this.root.querySelector<HTMLElement>(".echoes-grid-host")!;
    const settings = getSettings();
    host.innerHTML = `
      <div class="echoes-retrieval-page">
        <section class="echoes-retrieval-section echoes-api-binding-section">
          <div class="echoes-section-heading"><div><h2>检索运行配置</h2><span>端点、模型、凭据和故障策略统一在 API配置中管理</span></div><button type="button" class="menu_button" data-action="switch-view" data-view="api"><i class="fa-solid fa-plug"></i> 前往 API配置</button></div>
          <div class="echoes-workflow-summary">
            <span>总结 Embedding<strong data-retrieval-binding-embedding></strong></span><span>Rerank<strong data-retrieval-binding-rerank></strong></span><span>故障策略<strong data-retrieval-binding-policy></strong></span>
          </div>
        </section>
        <section class="echoes-retrieval-section" data-section="collections">
          <div class="echoes-section-heading"><div><h2>集合与索引</h2><span>文档先持久化，向量状态独立修复</span></div><div data-collection-actions></div></div>
          <div class="echoes-table-scroll" data-collection-table></div>
        </section>
        <section class="echoes-retrieval-section echoes-retrieval-ingest" data-section="ingest">
          <div class="echoes-section-heading"><div><h2>数据导入</h2><span>JSONL 按 100 条分批提交</span></div></div>
          <form class="echoes-retrieval-form" data-retrieval-manual-form>
            <label>集合<select name="collectionId" required></select></label>
            <label>来源 ID<input name="sourceId" required maxlength="500"></label>
            <label>标签<input name="tags" placeholder="逗号分隔"></label>
            <label class="echoes-form-span">正文<textarea name="text" rows="5" required maxlength="100000"></textarea></label>
            <div class="echoes-retrieval-form-actions"><button class="menu_button echoes-primary" type="submit"><i class="fa-solid fa-plus"></i> 添加文本</button></div>
          </form>
          <div class="echoes-jsonl-row"><label>JSONL 文件<input type="file" accept=".jsonl,.ndjson,application/x-ndjson" data-jsonl-file></label><button class="menu_button" type="button" data-retrieval-action="import-jsonl"><i class="fa-solid fa-file-import"></i> 导入 JSONL</button></div>
        </section>
        <section class="echoes-retrieval-section" data-section="query">
          <div class="echoes-section-heading"><div><h2>查询实验台</h2><span>向量与 BM25 并行，RRF k=60</span></div></div>
          <form class="echoes-retrieval-query" data-retrieval-query-form>
            <div class="echoes-query-collections" data-query-collections></div>
            <div class="echoes-query-options">
              <label><input type="checkbox" name="vectorEnabled"> 向量</label>
              <label><input type="checkbox" name="bm25Enabled"> BM25</label>
              <label><input type="checkbox" name="rerankEnabled"> rerank</label>
              <label>结果数<input type="number" name="finalTopK" min="1" max="100"></label>
            </div>
            <label class="echoes-query-text">查询<textarea name="query" rows="3" required maxlength="20000"></textarea></label>
            <div class="echoes-retrieval-form-actions"><button class="menu_button echoes-primary" type="submit"><i class="fa-solid fa-magnifying-glass"></i> 查询</button></div>
          </form>
          <div data-query-status></div>
          <div class="echoes-table-scroll" data-query-results></div>
        </section>
      </div>`;

    const embeddingGroup = settings.retrieval.embeddingGroups.find((group) => group.id === settings.summary.embeddingGroupId);
    const rerankSet = settings.retrieval.rerankSets.find((set) => set.id === settings.retrieval.recall.rerankSetId);
    host.querySelector<HTMLElement>("[data-retrieval-binding-embedding]")!.textContent = embeddingGroup?.name ?? "未配置";
    host.querySelector<HTMLElement>("[data-retrieval-binding-rerank]")!.textContent = rerankSet?.name ?? "未配置";
    host.querySelector<HTMLElement>("[data-retrieval-binding-policy]")!.textContent = {
      confirm_ambiguous: "不确定时确认",
      always: "始终自动切换",
      definitive_only: "仅明确失败切换",
    }[settings.retrieval.failoverPolicy];
    host.querySelector<HTMLElement>("[data-collection-actions]")!
      .append(button("plus", "新建集合", "add-collection", true));
    this.renderCollectionTable(host.querySelector<HTMLElement>("[data-collection-table]")!);
    this.populateCollectionControls(host);
  }

  private renderCollectionTable(host: HTMLElement): void {
    if (this.collections.length === 0) {
      const empty = document.createElement("p");
      empty.className = "echoes-empty-note";
      empty.textContent = "暂无检索集合";
      host.replaceChildren(empty);
      return;
    }
    const table = document.createElement("table");
    table.className = "echoes-data-table echoes-collection-table";
    table.innerHTML = "<thead><tr><th>集合</th><th>文档</th><th>就绪</th><th>待处理</th><th>失败</th><th>不确定</th><th>维度</th><th>索引</th><th>操作</th></tr></thead>";
    const body = document.createElement("tbody");
    for (const item of this.collections) {
      const row = document.createElement("tr");
      for (const value of [
        item.collection.name,
        item.documents,
        item.ready,
        item.pending,
        item.failed,
        item.ambiguous,
        item.dimensions,
        item.vectorIndex === "hnsw_sq" ? "HNSW-SQ" : "Flat",
      ]) {
        const cell = document.createElement("td");
        cell.textContent = String(value);
        row.append(cell);
      }
      const actions = document.createElement("td");
      actions.className = "echoes-row-actions echoes-retrieval-row-actions";
      for (const [icon, title, action] of [
        ["screwdriver-wrench", "修复未就绪向量", "repair-collection"],
        ["rotate", "重建全部向量", "rebuild-collection"],
        ["trash", "删除集合", "delete-collection"],
      ]) {
        const control = iconButton(icon!, title!, action!);
        control.dataset.id = item.collection.id;
        actions.append(control);
      }
      row.append(actions);
      body.append(row);
    }
    table.append(body);
    host.replaceChildren(table);
  }

  private populateCollectionControls(host: HTMLElement): void {
    const select = host.querySelector<HTMLSelectElement>("[name=collectionId]")!;
    const queryCollections = host.querySelector<HTMLElement>("[data-query-collections]")!;
    for (const item of this.collections) {
      const option = document.createElement("option");
      option.value = item.collection.id;
      option.textContent = item.collection.name;
      select.append(option);
      const label = document.createElement("label");
      const input = document.createElement("input");
      input.type = "checkbox";
      input.name = "collectionIds";
      input.value = item.collection.id;
      input.checked = true;
      label.append(input, document.createTextNode(` ${item.collection.name}`));
      queryCollections.append(label);
    }
    const query = getSettings().retrieval.query;
    host.querySelector<HTMLInputElement>("[name=vectorEnabled]")!.checked = query.vectorEnabled;
    host.querySelector<HTMLInputElement>("[name=bm25Enabled]")!.checked = query.bm25Enabled;
    host.querySelector<HTMLInputElement>("[name=rerankEnabled]")!.checked = query.rerankEnabled;
    host.querySelector<HTMLInputElement>("[name=finalTopK]")!.value = String(query.finalTopK);
  }

  private async createCollection(): Promise<void> {
    const groups = getSettings().retrieval.embeddingGroups;
    if (groups.length === 0) throw new Error("请先配置 Embedding 端点组和嵌入空间。");
    const dialog = document.createElement("dialog");
    dialog.className = "echoes-dialog echoes-compact-dialog";
    dialog.innerHTML = `
      <form method="dialog" class="echoes-dialog-frame">
        <header class="echoes-dialog-header"><h2>新建检索集合</h2></header>
        <div class="echoes-dialog-body"><div class="echoes-form-grid">
          <label>名称<input name="name" required maxlength="120"></label>
          <label>集合 ID<input name="id" required pattern="[a-zA-Z][a-zA-Z0-9_-]*"></label>
          <label>嵌入空间<select name="groupId"></select></label>
          <label class="echoes-form-span">说明<textarea name="description" rows="3" maxlength="1000"></textarea></label>
        </div></div>
        <footer class="echoes-dialog-footer"><button type="button" class="menu_button" data-close>取消</button><button type="submit" class="menu_button echoes-primary">创建</button></footer>
      </form>`;
    document.body.append(dialog);
    const form = dialog.querySelector<HTMLFormElement>("form")!;
    (form.elements.namedItem("id") as HTMLInputElement).value = uid("collection");
    const select = form.elements.namedItem("groupId") as HTMLSelectElement;
    groups.forEach((group) => select.add(new Option(`${group.name} · ${group.dimensions} 维`, group.id)));
    dialog.querySelector("[data-close]")!.addEventListener("click", () => dialog.close("cancel"));
    await new Promise<void>((resolve) => {
      form.addEventListener("submit", (event) => {
        event.preventDefault();
        const group = groups.find((item) => item.id === select.value)!;
        void echoesApi.createRetrievalCollection({
          id: selectedValue<HTMLInputElement>(form, "[name=id]"),
          name: selectedValue<HTMLInputElement>(form, "[name=name]"),
          description: selectedValue<HTMLTextAreaElement>(form, "[name=description]"),
          embeddingSpaceId: group.embeddingSpaceId,
          dimensions: group.dimensions,
        }).then(() => dialog.close("saved")).catch((error) => toastr.error(errorMessage(error), "集合创建失败"));
      });
      dialog.addEventListener("close", () => { dialog.remove(); resolve(); }, { once: true });
      dialog.showModal();
    });
    await this.render();
  }

  private async deleteCollection(collectionId: string): Promise<void> {
    if (!collectionId || !confirm("删除集合及其权威文档和向量？")) return;
    const completed = await this.waitForJob(await echoesApi.deleteRetrievalCollection(collectionId));
    if (completed.status !== "succeeded") throw new Error(completed.error?.message ?? completed.message);
    await this.render();
  }

  private embeddingGroupForCollection(collectionId: string): EmbeddingEndpointGroup | undefined {
    const collection = this.collections.find((item) => item.collection.id === collectionId)?.collection;
    if (!collection) return undefined;
    return getSettings().retrieval.embeddingGroups.find((group) =>
      group.embeddingSpaceId === collection.embeddingSpaceId && group.dimensions === collection.dimensions);
  }

  private async rebuildCollection(collectionId: string, repair: boolean): Promise<void> {
    const group = this.embeddingGroupForCollection(collectionId);
    if (!group) throw new Error("没有与该集合嵌入空间和维度匹配的端点组。");
    if (!repair && !confirm("重建会重新生成该集合的全部向量。继续？")) return;
    const settings = getSettings();
    const completed = await this.waitForJob(await echoesApi.rebuildRetrievalIndex({
      collectionIds: [collectionId],
      embeddingGroup: group,
      failoverPolicy: settings.retrieval.failoverPolicy,
    }, repair));
    if (completed.status !== "succeeded" || !completed.result) throw new Error(completed.error?.message ?? completed.message);
    if (completed.result.decisionRequired) {
      const proceed = await this.confirmAmbiguous(completed.result.decisionRequired);
      if (proceed) {
        await this.waitForJob(await echoesApi.rebuildRetrievalIndex({
          collectionIds: [collectionId],
          embeddingGroup: group,
          failoverPolicy: settings.retrieval.failoverPolicy,
          resumeAfterEndpointId: completed.result.decisionRequired.failedEndpointId,
        }, true));
      }
    }
    await this.render();
  }

  private async importManual(form: HTMLFormElement): Promise<void> {
    const collectionId = selectedValue<HTMLSelectElement>(form, "[name=collectionId]");
    const document = retrievalDocumentInputSchema.parse({
      collectionId,
      sourceType: "manual",
      sourceId: selectedValue<HTMLInputElement>(form, "[name=sourceId]"),
      text: selectedValue<HTMLTextAreaElement>(form, "[name=text]"),
      tags: selectedValue<HTMLInputElement>(form, "[name=tags]").split(",").map((item) => item.trim()).filter(Boolean),
      metadata: {},
    });
    await this.submitDocuments([document]);
    form.reset();
    await this.render();
  }

  private async importJsonl(): Promise<void> {
    const input = this.root.querySelector<HTMLInputElement>("[data-jsonl-file]")!;
    const fallbackCollectionId = this.root.querySelector<HTMLSelectElement>("[name=collectionId]")!.value;
    const file = input.files?.[0];
    if (!file) throw new Error("请选择 JSONL 文件。");
    const lines = (await file.text()).split(/\r?\n/).filter((line) => line.trim());
    let imported = 0;
    for (let offset = 0; offset < lines.length; offset += 100) {
      const documents = lines.slice(offset, offset + 100).map((line, index) => {
        let raw: Record<string, unknown>;
        try {
          raw = JSON.parse(line!) as Record<string, unknown>;
        } catch {
          throw new Error(`JSONL 第 ${offset + index + 1} 行不是有效 JSON。`);
        }
        return retrievalDocumentInputSchema.parse({
          ...raw,
          collectionId: raw.collectionId ?? fallbackCollectionId,
          sourceType: raw.sourceType ?? "jsonl",
          sourceId: raw.sourceId ?? `line_${offset + index + 1}`,
          tags: raw.tags ?? [],
          metadata: raw.metadata ?? {},
        });
      });
      await this.submitDocuments(documents);
      imported += documents.length;
    }
    toastr.success(`已导入 ${imported} 条文档。`, "JSONL 导入完成");
    input.value = "";
    await this.render();
  }

  private async submitDocuments(documents: RetrievalDocumentInput[]): Promise<RetrievalUpsertResult> {
    const collectionIds = [...new Set(documents.map((document) => document.collectionId))];
    const groups = collectionIds.map((id) => this.embeddingGroupForCollection(id)).filter(Boolean);
    const embeddingGroup = groups.length === collectionIds.length
      && groups.every((group) => group!.id === groups[0]!.id)
      ? groups[0]
      : undefined;
    const settings = getSettings();
    let request: RetrievalUpsertRequest = {
      documents,
      failoverPolicy: settings.retrieval.failoverPolicy,
      ...(embeddingGroup ? { embeddingGroup } : {}),
    };
    while (true) {
      const completed = await this.waitForJob(await echoesApi.upsertRetrievalDocuments(request));
      if (completed.status !== "succeeded" || !completed.result) throw new Error(completed.error?.message ?? completed.message);
      if (!completed.result.decisionRequired) return completed.result;
      const proceed = await this.confirmAmbiguous(completed.result.decisionRequired);
      if (!proceed || !completed.result.decisionRequired.nextEndpointId) return completed.result;
      request = { ...request, resumeAfterEndpointId: completed.result.decisionRequired.failedEndpointId };
    }
  }

  private async runQuery(form: HTMLFormElement): Promise<void> {
    const settings = getSettings();
    const collectionIds = [...form.querySelectorAll<HTMLInputElement>("[name=collectionIds]:checked")]
      .map((input) => input.value);
    if (collectionIds.length === 0) throw new Error("至少选择一个集合。");
    const vectorEnabled = form.querySelector<HTMLInputElement>("[name=vectorEnabled]")!.checked;
    const bm25Enabled = form.querySelector<HTMLInputElement>("[name=bm25Enabled]")!.checked;
    const rerankEnabled = form.querySelector<HTMLInputElement>("[name=rerankEnabled]")!.checked;
    const embeddingGroups = collectionIds.map((id) => this.embeddingGroupForCollection(id));
    const embeddingGroup = embeddingGroups[0];
    if (vectorEnabled && (!embeddingGroup || embeddingGroups.some((group) => group?.id !== embeddingGroup.id))) {
      throw new Error("向量查询要求所选集合使用同一个已配置的嵌入空间。");
    }
    const rerankSet = settings.retrieval.rerankSets.find((set) =>
      set.id === settings.retrieval.recall.rerankSetId);
    if (rerankEnabled && !rerankSet) throw new Error("请先在 API配置中绑定 Rerank 端点组。");
    const request: RetrievalQueryRequest = {
      collectionIds,
      query: selectedValue<HTMLTextAreaElement>(form, "[name=query]"),
      vectorEnabled,
      bm25Enabled,
      rerankEnabled,
      vectorTopK: 30,
      bm25TopK: 30,
      finalTopK: Number(selectedValue<HTMLInputElement>(form, "[name=finalTopK]")),
      rerankTopK: 30,
      failoverPolicy: settings.retrieval.failoverPolicy,
      ...(vectorEnabled && embeddingGroup ? { embeddingGroup } : {}),
      ...(rerankEnabled && rerankSet ? { rerankSet } : {}),
    };
    settings.retrieval.query = { vectorEnabled, bm25Enabled, rerankEnabled, finalTopK: request.finalTopK };
    saveSettings(settings);
    this.lastQueryRequest = request;
    await this.executeQuery(request);
  }

  private async executeQuery(request: RetrievalQueryRequest): Promise<void> {
    const completed = await this.waitForJob(await echoesApi.queryRetrieval(request));
    await this.handleQueryResult(request, completed);
  }

  private async handleQueryResult(
    request: RetrievalQueryRequest,
    completed: JobRecord<RetrievalQueryResult>,
  ): Promise<void> {
    if (completed.status !== "succeeded" || !completed.result) throw new Error(completed.error?.message ?? completed.message);
    this.renderQueryResult(completed.result);
    if (!completed.result.decisionRequired) return;
    const proceed = await this.confirmAmbiguous(completed.result.decisionRequired);
    if (!proceed || !completed.result.continuation) return;
    const continued = await this.waitForJob(await echoesApi.continueRetrievalQuery({
      token: completed.result.continuation.token,
      failoverPolicy: request.failoverPolicy,
      ...(request.embeddingGroup ? { embeddingGroup: request.embeddingGroup } : {}),
      ...(request.rerankSet ? { rerankSet: request.rerankSet } : {}),
    }));
    await this.handleQueryResult(request, continued);
  }

  private renderQueryResult(result: RetrievalQueryResult): void {
    const status = this.root.querySelector<HTMLElement>("[data-query-status]")!;
    status.className = "echoes-query-branch-status";
    status.replaceChildren();
    for (const [name, branch] of Object.entries(result.branches)) {
      const item = document.createElement("span");
      item.className = branch.state;
      item.textContent = `${name}: ${branch.state} · ${branch.durationMs} ms${branch.message ? ` · ${branch.message}` : ""}`;
      status.append(item);
    }
    const host = this.root.querySelector<HTMLElement>("[data-query-results]")!;
    const table = document.createElement("table");
    table.className = "echoes-data-table echoes-query-result-table";
    table.innerHTML = "<thead><tr><th>来源</th><th>正文</th><th>向量</th><th>BM25</th><th>RRF</th><th>Rerank</th></tr></thead>";
    const body = document.createElement("tbody");
    for (const hit of result.hits) {
      const row = document.createElement("tr");
      for (const value of [
        `${hit.document.sourceType}:${hit.document.sourceId}`,
        hit.document.text,
        score(hit.vectorScore),
        score(hit.bm25Score),
        score(hit.rrfScore),
        score(hit.rerankScore),
      ]) {
        const cell = document.createElement("td");
        cell.textContent = value;
        cell.title = value;
        row.append(cell);
      }
      body.append(row);
    }
    table.append(body);
    host.replaceChildren(table);
  }

  private confirmAmbiguous(decision: FailoverDecisionRequired): Promise<boolean> {
    const dialog = document.createElement("dialog");
    dialog.className = "echoes-dialog echoes-confirm-dialog";
    dialog.innerHTML = `
      <div class="echoes-dialog-frame">
        <header class="echoes-dialog-header"><h2>提供商结果不确定</h2></header>
        <div class="echoes-dialog-body"><p></p></div>
        <footer class="echoes-dialog-footer"><button type="button" class="menu_button" data-stop>停止并使用降级结果</button><button type="button" class="menu_button echoes-primary" data-next ${decision.nextEndpointId ? "" : "disabled"}>切换下一端点</button></footer>
      </div>`;
    dialog.querySelector("p")!.textContent = decision.message;
    document.body.append(dialog);
    return new Promise((resolve) => {
      dialog.querySelector("[data-stop]")!.addEventListener("click", () => { resolve(false); dialog.close(); });
      dialog.querySelector("[data-next]")!.addEventListener("click", () => { resolve(true); dialog.close(); });
      dialog.addEventListener("close", () => dialog.remove(), { once: true });
      dialog.showModal();
    });
  }

  private async waitForJob<TResult>(initial: JobRecord<TResult>): Promise<JobRecord<TResult>> {
    let job = initial;
    this.activeJobId = job.id;
    for (let attempt = 0; attempt < 2_000; attempt += 1) {
      this.showJob(job);
      if (TERMINAL_STATES.has(job.status)) {
        this.activeJobId = null;
        setTimeout(() => this.hideJob(), 2_500);
        return job;
      }
      await new Promise((resolve) => setTimeout(resolve, 300));
      job = await echoesApi.getJob<TResult>(job.id);
    }
    this.activeJobId = null;
    throw new Error("等待检索任务超时。");
  }

  private showJob(job: JobRecord): void {
    const host = this.root.querySelector<HTMLElement>(".echoes-job-status")!;
    host.classList.remove("echoes-hidden");
    host.querySelector<HTMLElement>(".echoes-progress span")!.style.width = `${Math.round(job.progress * 100)}%`;
    host.querySelector<HTMLElement>("[data-job-message]")!.textContent = job.message;
    let cancel = host.querySelector<HTMLButtonElement>("[data-retrieval-action=cancel-job]");
    if (!cancel) {
      cancel = iconButton("stop", "取消任务", "cancel-job");
      host.append(cancel);
    }
    cancel.classList.toggle("echoes-hidden", TERMINAL_STATES.has(job.status));
  }

  private hideJob(): void {
    this.root.querySelector(".echoes-job-status")?.classList.add("echoes-hidden");
  }

  private setMessage(message: string, error = false): void {
    const host = this.root.querySelector<HTMLElement>(".echoes-grid-host")!;
    const note = document.createElement("div");
    note.className = `echoes-grid-message${error ? " error" : ""}`;
    note.textContent = message;
    host.replaceChildren(note);
  }
}
