import type {
  RetrievalDocumentInput,
  SummarySlice,
} from "../../shared/domain";

async function hashIdentifier(value: string): Promise<string> {
  const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(value));
  return [...new Uint8Array(digest)]
    .map((byte) => byte.toString(16).padStart(2, "0"))
    .join("");
}

export async function summaryRetrievalDocumentId(
  collectionId: string,
  sliceId: string,
): Promise<string> {
  return `summary_doc_${(await hashIdentifier(`${collectionId}\0${sliceId}`)).slice(0, 48)}`;
}

export function summaryRetrievalText(slice: Pick<SummarySlice, "title" | "content">): string {
  return `${slice.title}\n${slice.content}`;
}

export async function summaryRetrievalContentHash(
  slice: Pick<SummarySlice, "title" | "content">,
): Promise<string> {
  return hashIdentifier(summaryRetrievalText(slice));
}

export async function summaryRetrievalDocument(
  collectionId: string,
  slice: SummarySlice,
  chatId: string,
): Promise<RetrievalDocumentInput> {
  return {
    documentId: await summaryRetrievalDocumentId(collectionId, slice.id),
    collectionId,
    sourceType: "chat_summary",
    sourceId: slice.id,
    text: summaryRetrievalText(slice),
    tags: slice.tags,
    metadata: {
      chatId,
      batchId: slice.batch.id,
      batchNumber: slice.batch.batchNumber,
      sliceNumber: slice.sliceNumber,
      startMessageId: slice.batch.startMessageId,
      endMessageId: slice.batch.endMessageId,
      messageIds: slice.batch.messageIds,
      sourceHash: slice.batch.sourceHash,
      revision: slice.batch.revision,
    },
  };
}
