import { stringify as stringifyYaml } from "yaml";

import type {
  ChatMessageInput,
  PromptMessageInput,
  StatusCatalog,
  StatusPromptItem,
  StatusSnapshot,
  StatusState,
} from "../../shared/domain";
import { sourceMessagesHash } from "../../shared/source-hash";
import { canonicalStatusJson } from "../../shared/status-core";
import { preprocessSummaryMessages } from "../summary/preprocess";
import { statusMessageId } from "./status-snapshots";

export interface StatusChatMessage extends ChatMessageInput {
  messageIndex: number;
}

export interface PreparedStatusRequest {
  originalMessages: ChatMessageInput[];
  cleanedMessages: ChatMessageInput[];
  promptMessages: PromptMessageInput[];
  sourceHash: string;
}

export function currentStatusMessages(): StatusChatMessage[] {
  return SillyTavern.getContext().chat.flatMap((message, messageIndex) => {
    const content = String(message.mes ?? message.message ?? "").trim();
    if (!content) return [];
    return [{
      id: statusMessageId(message, messageIndex),
      messageIndex,
      role: message.is_user === true || message.role === "user" ? "user" as const : "assistant" as const,
      content,
    }];
  });
}

export async function statusSourceHash(messages: ChatMessageInput[]): Promise<string> {
  return sourceMessagesHash(messages);
}

export function renderStatusYaml(state: StatusState): string {
  return stringifyYaml(state, { lineWidth: 0 }).trim() || "{}";
}

function macro(value: string, charName: string, userName: string): string {
  return value.replaceAll("{{char}}", charName).replaceAll("{{user}}", userName);
}

function itemContent(
  item: StatusPromptItem,
  state: StatusState,
  messages: ChatMessageInput[],
): string {
  const context = SillyTavern.getContext();
  const character = context.characters?.[context.characterId ?? -1] ?? {};
  const charName = String(character.name ?? "Character");
  const userName = String(context.powerUserSettings?.persona_name ?? context.name1 ?? "User");
  if (item.kind === "custom") return macro(item.content, charName, userName);
  if (item.kind === "character") {
    const description = String(character.description ?? "").trim();
    return description ? `${charName}:\n${description}` : "";
  }
  if (item.kind === "persona") {
    const description = String(context.powerUserSettings?.persona_description ?? "").trim();
    return description ? `${userName}:\n${description}` : "";
  }
  if (item.kind === "current_state") return `Current complete state:\n${renderStatusYaml(state)}`;
  return messages.map((message) => {
    const name = message.role === "user" ? userName : charName;
    return `[${message.id}] ${name}: ${message.content}`;
  }).join("\n\n");
}

export async function prepareStatusRequest(options: {
  catalog: StatusCatalog;
  baseSnapshot: StatusSnapshot | null;
  targetMessageIndex: number;
}): Promise<PreparedStatusRequest> {
  const all = currentStatusMessages();
  const baseIndex = options.baseSnapshot
    ? all.find((message) => message.id === options.baseSnapshot!.targetMessageId)?.messageIndex ?? -1
    : -1;
  const selected = all
    .filter((message) => message.messageIndex > baseIndex && message.messageIndex <= options.targetMessageIndex)
    .map(({ id, role, content }) => ({ id, role, content }));
  if (selected.length === 0 || selected.length > 500) {
    throw new Error("Status updates require between 1 and 500 incremental messages.");
  }
  const cleaned = await preprocessSummaryMessages(selected, options.catalog.profile.preprocessRules);
  if (cleaned.length === 0) throw new Error("No status evidence remains after message preprocessing.");
  if (!options.catalog.profile.promptPreset.items.some((item) => item.enabled && item.kind === "messages")) {
    throw new Error("The status prompt preset requires an enabled incremental messages item.");
  }
  const baseState = options.baseSnapshot?.state ?? options.catalog.profile.initialState;
  const promptMessages = options.catalog.profile.promptPreset.items.flatMap((item): PromptMessageInput[] => {
    if (!item.enabled) return [];
    const content = itemContent(item, baseState, cleaned).trim();
    return content ? [{ role: item.role, content }] : [];
  });
  if (promptMessages.length === 0) throw new Error("The status prompt is empty.");
  return {
    originalMessages: selected,
    cleanedMessages: cleaned,
    promptMessages,
    sourceHash: await statusSourceHash(selected),
  };
}

export function statusStateDebugValue(state: StatusState): string {
  return canonicalStatusJson(state);
}
