import type {
  CredentialMetadata,
  DiagnosticCheck,
  EchoesBackupV1,
  JobRecord,
  RepairKind,
  RestoreMode,
  RestorePlan,
  SystemStatus,
} from "../../shared/domain";
import { echoesApi } from "../api/client";
import { EchoesBackupManager, serializeBackup } from "../maintenance/backup";
import {
  applyCredentialMigration,
  getSettings,
  legacyCredentialEndpoints,
  saveSettings,
  storedSettingsFormatVersion,
} from "../state/settings";
import { worldbookWriteCoordinator } from "../worldbook/worldbook-write-coordinator";
