import type {
  AttachedRecallSource,
  RetrievalQueryPresetItem,
  RetrievalTraceSource,
} from "../../shared/domain";
import { prepareRecallQuery } from "../recall-query";
import { recallCoordinator } from "../recall-coordinator";
import { dialogShell } from "./dialogs";
import {
  getSettings,
  newRecallPromptItemId,
  saveSettings,
} from "../state/settings";
import type { SummaryWorldbookState } from "../worldbook/summary-worldbook";

function actionButton(icon: string, title: string, action: string): HTMLButtonElement {
  const button = document.createElement("button");
  button.type = "button";
  button.className = "echoes-icon-button";
  button.title = title;
  button.setAttribute("aria-label", title);
  button.dataset.recallAction = action;
  button.innerHTML = `<i class="fa-solid fa-${icon}"></i>`;
  return button;
}

function queryIdentity() {
  const context = SillyTavern.getContext();
  const character = context.characters?.[context.characterId ?? -1] ?? {};
  return {
    characterName: String(character.name ?? "Character"),
    characterDescription: String(character.description ?? ""),
    userName: String(context.powerUserSettings?.persona_name ?? context.name1 ?? "User"),
    personaDescription: String(context.powerUserSettings?.persona_description ?? ""),
  };
}


function compatibilityLabel(source: RetrievalTraceSource | undefined): string {
  if (!source) return "未检查";
  if (source.mode === "vector_bm25") return "向量 + BM25";
  if (source.mode === "bm25_only") return "仅 BM25";
  return source.message ?? "不可用";
}

export class RecallPanel {
  private current: SummaryWorldbookState | null = null;
  private available: SummaryWorldbookState[] = [];
  private sourceTraces: RetrievalTraceSource[] = [];
  private draggedNamespace: string | null = null;
  private renderSequence = 0;

  constructor(private readonly root: HTMLElement) {
    this.bindEvents();
  }

  async render(): Promise<void> {
    const sequence = ++this.renderSequence;
    const chatId = SillyTavern.getContext().chatId;
    const host = this.root.querySelector<HTMLElement>(".echoes-grid-host")!;
    host.innerHTML = '<div class="echoes-grid-message">正在读取召回配置...</div>';
    try {
      const overview = await recallCoordinator.sourceOverview();
      if (sequence !== this.renderSequence
        || !this.root.classList.contains("echoes-recall-view")
        || SillyTavern.getContext().chatId !== chatId
        || overview.current.catalog.chatId !== chatId) return;
      this.current = overview.current;
      this.available = overview.available;
      this.sourceTraces = overview.sources;
      this.renderSidebar();
      this.renderContent();
    } catch (error) {
      if (sequence !== this.renderSequence
        || !this.root.classList.contains("echoes-recall-view")
        || SillyTavern.getContext().chatId !== chatId) return;
      const note = document.createElement("div");
      note.className = "echoes-grid-message error";
      note.textContent = error instanceof Error ? error.message : String(error);
      host.replaceChildren(note);
    }
  }

  renderSidebar(): void {
    const heading = this.root.querySelector<HTMLElement>(".echoes-sidebar-heading > span")!;
    const actions = this.root.querySelector<HTMLElement>(".echoes-sidebar-actions")!;
    const list = this.root.querySelector<HTMLElement>(".echoes-table-list")!;
    heading.textContent = "召回来源";
    actions.replaceChildren(actionButton("plus", "附加聊天", "attach-source"));
    list.replaceChildren();
    for (const source of [...this.sourceTraces].sort((left, right) => left.order - right.order)) {
      const item = document.createElement("div");
      item.className = "echoes-recall-source-nav";
      const icon = document.createElement("i");
      icon.className = `fa-solid fa-${source.mode === "unavailable" ? "triangle-exclamation" : "database"}`;
      const text = document.createElement("span");
      text.textContent = source.chatId;
      text.title = source.worldbookName;
      const badge = document.createElement("small");
      badge.textContent = source.mode === "vector_bm25" ? "混合" : source.mode === "bm25_only" ? "BM25" : "异常";
      item.append(icon, text, badge);
      list.append(item);
    }
  }

  private bindEvents(): void {
    this.root.addEventListener("click", (event) => {
      const target = (event.target as HTMLElement).closest<HTMLElement>("[data-recall-action]");
      if (!target) return;
      const action = target.dataset.recallAction;
      if (action === "refresh") void this.render();
      else if (action === "preview") void this.preview();
      else if (action === "attach-source") void this.attachSource();
      else if (action === "remove-source") void this.removeSource(target.dataset.namespaceId ?? "");
      else if (action === "source-up") void this.moveSource(target.dataset.namespaceId ?? "", -1);
      else if (action === "source-down") void this.moveSource(target.dataset.namespaceId ?? "", 1);
      else if (action === "prompt-up") this.movePrompt(Number(target.dataset.index), -1);
      else if (action === "prompt-down") this.movePrompt(Number(target.dataset.index), 1);
      else if (action === "prompt-delete") this.deletePrompt(Number(target.dataset.index));
      else if (action === "prompt-add") void this.addPrompt();
      else if (action === "query-preview") this.previewQuery();
    });

    this.root.addEventListener("change", (event) => {
      const target = event.target as HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement;
      if (target.matches("[data-recall-enabled]")) void this.saveSourceConfiguration();
      else if (target.matches("[data-source-weight]")) void this.saveSourceConfiguration();
      else if (target.matches("[data-source-enabled]")) void this.saveSourceConfiguration();
      else if (target.matches("[data-recall-setting]")) this.saveRecallSettings();
      else if (target.matches("[data-recall-prompt]")) this.savePromptSettings();
    });

    this.root.addEventListener("dragstart", (event) => {
      const source = (event.target as HTMLElement).closest<HTMLElement>("[data-source-namespace]");
      this.draggedNamespace = source?.dataset.sourceNamespace ?? null;
    });
    this.root.addEventListener("dragover", (event) => {
      if ((event.target as HTMLElement).closest("[data-source-namespace]")) event.preventDefault();
    });
    this.root.addEventListener("drop", (event) => {
      const target = (event.target as HTMLElement).closest<HTMLElement>("[data-source-namespace]");
      if (!target || !this.draggedNamespace) return;
      event.preventDefault();
      void this.dropSource(this.draggedNamespace, target.dataset.sourceNamespace ?? "");
      this.draggedNamespace = null;
    });
  }

  private renderContent(): void {
    if (!this.current) return;
    const settings = getSettings();
    const recall = settings.retrieval.recall;
    const host = this.root.querySelector<HTMLElement>(".echoes-grid-host")!;
    const page = document.createElement("div");
    page.className = "echoes-recall-page";
    page.innerHTML = `
      <section class="echoes-recall-controls">
        <label class="echoes-check">
          <input type="checkbox" data-recall-enabled>
          总结召回总开关
        </label>
        <label>最终 Top K
          <input type="number" min="1" max="100" data-recall-setting="finalTopK">
        </label>
        <label>Vector K
          <input type="number" min="1" max="200" data-recall-setting="vectorTopK">
        </label>
        <label>BM25 K
          <input type="number" min="1" max="200" data-recall-setting="bm25TopK">
        </label>
        <label>Rerank K
          <input type="number" min="1" max="100" data-recall-setting="rerankTopK">
        </label>
        <label class="echoes-check"><input type="checkbox" data-recall-setting="vectorEnabled">向量</label>
        <label class="echoes-check"><input type="checkbox" data-recall-setting="bm25Enabled">BM25</label>
        <label class="echoes-check"><input type="checkbox" data-recall-setting="rerankEnabled">Rerank</label>
        <div class="echoes-api-binding-inline"><span>Rerank 组<strong data-recall-rerank-binding></strong></span><button type="button" class="menu_button" data-action="switch-view" data-view="api"><i class="fa-solid fa-plug"></i> API配置</button></div>
        <button type="button" class="menu_button" data-recall-action="preview">
          <i class="fa-solid fa-flask"></i> 检索预览
        </button>
      </section>
      <section>
        <div class="echoes-section-heading">
          <h2>来源排序与权重</h2>
          <button type="button" class="menu_button" data-recall-action="attach-source">
            <i class="fa-solid fa-plus"></i> 附加聊天
          </button>
        </div>
        <div class="echoes-recall-sources" data-recall-sources></div>
      </section>
      <section>
        <div class="echoes-section-heading">
          <h2>查询预设</h2>
          <div>
            <button type="button" class="menu_button" data-recall-action="query-preview">
              <i class="fa-solid fa-eye"></i> 预览查询词
            </button>
            <button type="button" class="menu_button" data-recall-action="prompt-add">
              <i class="fa-solid fa-plus"></i> 添加自定义项
            </button>
          </div>
        </div>
        <div class="echoes-recall-prompts" data-recall-prompts></div>
      </section>
      <section>
        <div class="echoes-section-heading"><h2>注入位置</h2></div>
        <div class="echoes-recall-injection">
          <label>位置<select data-recall-setting="position">
            <option value="before_character">角色定义前</option>
            <option value="after_character">角色定义后</option>
            <option value="at_depth">@D</option>
          </select></label>
          <label>Role<select data-recall-setting="role">
            <option value="system">system</option>
            <option value="user">user</option>
            <option value="assistant">assistant</option>
          </select></label>
          <label>Depth<input type="number" min="0" max="100" data-recall-setting="depth"></label>
          <label>Order<input type="number" min="-10000" max="10000" data-recall-setting="order"></label>
          <label>等待秒数<input type="number" min="1" max="300" data-recall-setting="maxWaitSeconds"></label>
          <label class="echoes-recall-template">模板
            <textarea rows="5" data-recall-setting="template"></textarea>
          </label>
        </div>
      </section>
      <section>
        <div class="echoes-section-heading"><h2>最近一次诊断</h2></div>
        <div class="echoes-recall-trace-summary" data-recall-trace-summary></div>
        <pre class="echoes-recall-trace" data-recall-trace></pre>
      </section>`;
    page.querySelector<HTMLInputElement>("[data-recall-enabled]")!.checked =
      this.current.catalog.recallEnabled;
    for (const key of ["vectorEnabled", "bm25Enabled", "rerankEnabled"] as const) {
      page.querySelector<HTMLInputElement>(`[data-recall-setting=${key}]`)!.checked = recall[key];
    }
    for (const key of ["finalTopK", "vectorTopK", "bm25TopK", "rerankTopK"] as const) {
      page.querySelector<HTMLInputElement>(`[data-recall-setting=${key}]`)!.value = String(recall[key]);
    }
    const rerankSet = settings.retrieval.rerankSets.find((set) => set.id === recall.rerankSetId);
    page.querySelector<HTMLElement>("[data-recall-rerank-binding]")!.textContent =
      rerankSet?.name ?? (recall.rerankEnabled ? "未配置" : "未启用");
    page.querySelector<HTMLSelectElement>("[data-recall-setting=position]")!.value =
      recall.injection.position;
    page.querySelector<HTMLSelectElement>("[data-recall-setting=role]")!.value =
      recall.injection.role;
    page.querySelector<HTMLInputElement>("[data-recall-setting=depth]")!.value =
      String(recall.injection.depth);
    page.querySelector<HTMLInputElement>("[data-recall-setting=order]")!.value =
      String(recall.injection.order);
    page.querySelector<HTMLInputElement>("[data-recall-setting=maxWaitSeconds]")!.value =
      String(Math.round(recall.injection.maxWaitMs / 1_000));
    page.querySelector<HTMLTextAreaElement>("[data-recall-setting=template]")!.value =
      recall.injection.template;
    const trace = recallCoordinator.trace;
    const traceSummary = page.querySelector<HTMLElement>("[data-recall-trace-summary]")!;
    for (const [label, value] of [
      ["固定近期批次", trace ? String(trace.recentBatchIds.length) : "-"],
      ["固定近期切片", trace ? String(trace.recentSliceCount) : "-"],
      ["语义 Top K", trace ? String(trace.semanticReturned) : "-"],
      ["最终注入", trace ? String(trace.injected) : "-"],
    ] as Array<[string, string]>) {
      const item = document.createElement("div");
      const name = document.createElement("span");
      name.textContent = label;
      const strong = document.createElement("strong");
      strong.textContent = value;
      item.append(name, strong);
      traceSummary.append(item);
    }
    page.querySelector<HTMLElement>("[data-recall-trace]")!.textContent =
      trace ? JSON.stringify(trace, null, 2) : "尚无召回记录。";
    host.replaceChildren(page);
    this.renderSources();
    this.renderPrompts();
  }

  private renderSources(): void {
    if (!this.current) return;
    const host = this.root.querySelector<HTMLElement>("[data-recall-sources]")!;
    const attachedByNamespace = new Map(
      this.current.catalog.attachedRecallSources.map((source) => [source.namespaceId, source]),
    );
    const sources = [...this.sourceTraces].sort((left, right) => left.order - right.order);
    host.replaceChildren();
    sources.forEach((source, index) => {
      const attached = attachedByNamespace.get(source.namespaceId);
      const row = document.createElement("article");
      row.className = "echoes-recall-source-row";
      row.draggable = true;
      row.dataset.sourceNamespace = source.namespaceId;
      const handle = document.createElement("i");
      handle.className = "fa-solid fa-grip-vertical echoes-drag-handle";
      const meta = document.createElement("div");
      meta.className = "echoes-recall-source-meta";
      const title = document.createElement("strong");
      title.textContent = attached ? source.chatId : `${source.chatId}（当前）`;
      const detail = document.createElement("small");
      detail.textContent = `${source.worldbookName} · ${compatibilityLabel(source)}`;
      meta.append(title, detail);
      const weight = document.createElement("label");
      weight.textContent = "权重 ";
      const weightInput = document.createElement("input");
      weightInput.type = "number";
      weightInput.min = "0.1";
      weightInput.max = "10";
      weightInput.step = "0.1";
      weightInput.value = String(source.weight);
      weightInput.dataset.sourceWeight = source.namespaceId;
      weight.append(weightInput);
      const controls = document.createElement("div");
      controls.className = "echoes-prompt-controls";
      if (attached) {
        const toggle = document.createElement("label");
        toggle.className = "echoes-switch";
        const input = document.createElement("input");
        input.type = "checkbox";
        input.checked = attached.enabled;
        input.dataset.sourceEnabled = source.namespaceId;
        toggle.append(input, document.createElement("span"));
        controls.append(toggle);
      }
      const up = actionButton("arrow-up", "上移", "source-up");
      up.dataset.namespaceId = source.namespaceId;
      up.disabled = index === 0;
      const down = actionButton("arrow-down", "下移", "source-down");
      down.dataset.namespaceId = source.namespaceId;
      down.disabled = index === sources.length - 1;
      controls.append(up, down);
      if (attached) {
        const remove = actionButton("trash", "移除来源", "remove-source");
        remove.dataset.namespaceId = source.namespaceId;
        controls.append(remove);
      }
      row.append(handle, meta, weight, controls);
      host.append(row);
    });
  }

  private renderPrompts(): void {
    const settings = getSettings();
    const items = settings.retrieval.recall.queryPreset.items;
    const host = this.root.querySelector<HTMLElement>("[data-recall-prompts]")!;
    host.replaceChildren();
    items.forEach((item, index) => {
      const row = document.createElement("article");
      row.className = "echoes-recall-prompt-row";
      row.innerHTML = `
        <label class="echoes-check"><input type="checkbox" data-recall-prompt="enabled" data-index="${index}"></label>
        <input type="text" data-recall-prompt="title" data-index="${index}">
        <small></small>
        <div data-value></div>
        <div class="echoes-prompt-controls"></div>`;
      row.querySelector<HTMLInputElement>("[data-recall-prompt=enabled]")!.checked = item.enabled;
      row.querySelector<HTMLInputElement>("[data-recall-prompt=title]")!.value = item.title;
      row.querySelector("small")!.textContent = item.kind;
      const valueHost = row.querySelector<HTMLElement>("[data-value]")!;
      if (item.kind === "recent_messages") {
        const count = document.createElement("input");
        count.type = "number";
        count.min = "0";
        count.max = "100";
        count.value = String(item.count);
        count.dataset.recallPrompt = "count";
        count.dataset.index = String(index);
        valueHost.append(count);
      } else if (item.kind === "custom") {
        const content = document.createElement("textarea");
        content.rows = 2;
        content.value = item.content;
        content.dataset.recallPrompt = "content";
        content.dataset.index = String(index);
        valueHost.append(content);
      }
      const controls = row.querySelector<HTMLElement>(".echoes-prompt-controls")!;
      const up = actionButton("arrow-up", "上移", "prompt-up");
      up.dataset.index = String(index);
      up.disabled = index === 0;
      const down = actionButton("arrow-down", "下移", "prompt-down");
      down.dataset.index = String(index);
      down.disabled = index === items.length - 1;
      const remove = actionButton("trash", "删除", "prompt-delete");
      remove.dataset.index = String(index);
      controls.append(up, down, remove);
      host.append(row);
    });
  }

  private async attachSource(): Promise<void> {
    if (!this.current) return;
    const attached = new Set(this.current.catalog.attachedRecallSources.map((source) => source.namespaceId));
    const options = this.available.filter((source) =>
      source.catalog.namespaceId !== this.current!.catalog.namespaceId
      && !attached.has(source.catalog.namespaceId));
    const picker = dialogShell("附加聊天总结源", { className: "echoes-preview-dialog", closeOnly: true });
    const body = picker.querySelector<HTMLElement>(".echoes-dialog-body")!;
    const select = document.createElement("select");
    for (const source of options) {
      const option = document.createElement("option");
      option.value = source.catalog.namespaceId;
      option.textContent = `${source.catalog.chatId} · ${source.worldbookName}`;
      select.append(option);
    }
    const add = document.createElement("button");
    add.type = "button";
    add.className = "menu_button echoes-primary";
    add.textContent = "附加";
    add.disabled = options.length === 0;
    body.append(select, add);
    add.addEventListener("click", async () => {
      const source = options.find((candidate) => candidate.catalog.namespaceId === select.value);
      if (!source) return;
      this.current!.catalog.attachedRecallSources.push({
        chatId: source.catalog.chatId,
        namespaceId: source.catalog.namespaceId,
        worldbookName: source.worldbookName,
        enabled: true,
        weight: 1,
        order: Math.max(-1, ...this.sourceTraces.map((item) => item.order)) + 1,
      });
      await this.saveSourceConfiguration();
      picker.close();
    });
    picker.showModal();
  }

  private async removeSource(namespaceId: string): Promise<void> {
    if (!this.current) return;
    this.current.catalog.attachedRecallSources =
      this.current.catalog.attachedRecallSources.filter((source) => source.namespaceId !== namespaceId);
    await this.saveSourceConfiguration();
  }

  private async saveSourceConfiguration(): Promise<void> {
    if (!this.current) return;
    const enabled = this.root.querySelector<HTMLInputElement>("[data-recall-enabled]")?.checked
      ?? this.current.catalog.recallEnabled;
    const weightInputs = new Map(
      [...this.root.querySelectorAll<HTMLInputElement>("[data-source-weight]")]
        .map((input) => [input.dataset.sourceWeight!, Number(input.value)]),
    );
    const enabledInputs = new Map(
      [...this.root.querySelectorAll<HTMLInputElement>("[data-source-enabled]")]
        .map((input) => [input.dataset.sourceEnabled!, input.checked]),
    );
    const currentWeight = weightInputs.get(this.current.catalog.namespaceId)
      ?? this.current.catalog.recallSourceWeight;
    const attached = this.current.catalog.attachedRecallSources.map((source) => ({
      ...source,
      weight: weightInputs.get(source.namespaceId) ?? source.weight,
      enabled: enabledInputs.get(source.namespaceId) ?? source.enabled,
    }));
    this.current = await recallCoordinator.summaryStore.saveRecallConfiguration(
      this.current.worldbookName,
      {
        enabled,
        weight: Math.max(0.1, Math.min(10, currentWeight)),
        order: this.current.catalog.recallSourceOrder,
        attachedSources: attached,
      },
    );
    if (!enabled) await recallCoordinator.clear();
    await this.render();
  }

  private async moveSource(namespaceId: string, direction: -1 | 1): Promise<void> {
    const ordered = [...this.sourceTraces].sort((left, right) => left.order - right.order);
    const index = ordered.findIndex((source) => source.namespaceId === namespaceId);
    const target = index + direction;
    if (index < 0 || target < 0 || target >= ordered.length) return;
    [ordered[index], ordered[target]] = [ordered[target]!, ordered[index]!];
    await this.saveSourceOrder(ordered.map((source) => source.namespaceId));
  }

  private async dropSource(sourceNamespace: string, targetNamespace: string): Promise<void> {
    const ordered = [...this.sourceTraces]
      .sort((left, right) => left.order - right.order)
      .map((source) => source.namespaceId);
    const from = ordered.indexOf(sourceNamespace);
    const to = ordered.indexOf(targetNamespace);
    if (from < 0 || to < 0 || from === to) return;
    const [moved] = ordered.splice(from, 1);
    ordered.splice(to, 0, moved!);
    await this.saveSourceOrder(ordered);
  }

  private async saveSourceOrder(namespaces: string[]): Promise<void> {
    if (!this.current) return;
    const currentNamespace = this.current.catalog.namespaceId;
    this.current.catalog.recallSourceOrder = namespaces.indexOf(currentNamespace);
    this.current.catalog.attachedRecallSources = this.current.catalog.attachedRecallSources.map((source) => ({
      ...source,
      order: namespaces.indexOf(source.namespaceId),
    }));
    await this.saveSourceConfiguration();
  }

  private saveRecallSettings(): void {
    const settings = getSettings();
    const recall = settings.retrieval.recall;
    const input = (key: string) =>
      this.root.querySelector<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>(
        `[data-recall-setting=${key}]`,
      )!;
    recall.vectorEnabled = (input("vectorEnabled") as HTMLInputElement).checked;
    recall.bm25Enabled = (input("bm25Enabled") as HTMLInputElement).checked;
    recall.rerankEnabled = (input("rerankEnabled") as HTMLInputElement).checked;
    recall.finalTopK = Math.max(1, Math.min(100, Number(input("finalTopK").value)));
    recall.vectorTopK = Math.max(1, Math.min(200, Number(input("vectorTopK").value)));
    recall.bm25TopK = Math.max(1, Math.min(200, Number(input("bm25TopK").value)));
    recall.rerankTopK = Math.max(1, Math.min(100, Number(input("rerankTopK").value)));
    recall.injection.position = input("position").value as typeof recall.injection.position;
    recall.injection.role = input("role").value as typeof recall.injection.role;
    recall.injection.depth = Math.max(0, Math.min(100, Number(input("depth").value)));
    recall.injection.order = Math.max(-10_000, Math.min(10_000, Number(input("order").value)));
    recall.injection.maxWaitMs = Math.max(
      1_000,
      Math.min(300_000, Number(input("maxWaitSeconds").value) * 1_000),
    );
    recall.injection.template = input("template").value || "{{memories}}";
    saveSettings(settings);
  }

  private savePromptSettings(): void {
    const settings = getSettings();
    const items = settings.retrieval.recall.queryPreset.items;
    this.root.querySelectorAll<HTMLInputElement | HTMLTextAreaElement>("[data-recall-prompt]")
      .forEach((input) => {
        const item = items[Number(input.dataset.index)];
        if (!item) return;
        if (input.dataset.recallPrompt === "enabled") item.enabled = (input as HTMLInputElement).checked;
        else if (input.dataset.recallPrompt === "title") item.title = input.value.trim() || item.title;
        else if (input.dataset.recallPrompt === "count" && item.kind === "recent_messages") {
          item.count = Math.max(0, Math.min(100, Number(input.value)));
        } else if (input.dataset.recallPrompt === "content" && item.kind === "custom") {
          item.content = input.value;
        }
      });
    settings.retrieval.recall.queryPreset.updatedAt = new Date().toISOString();
    saveSettings(settings);
  }

  private movePrompt(index: number, direction: -1 | 1): void {
    const settings = getSettings();
    const items = settings.retrieval.recall.queryPreset.items;
    const target = index + direction;
    if (!items[index] || target < 0 || target >= items.length) return;
    [items[index], items[target]] = [items[target]!, items[index]!];
    settings.retrieval.recall.queryPreset.updatedAt = new Date().toISOString();
    saveSettings(settings);
    this.renderContent();
  }

  private deletePrompt(index: number): void {
    const settings = getSettings();
    settings.retrieval.recall.queryPreset.items.splice(index, 1);
    settings.retrieval.recall.queryPreset.updatedAt = new Date().toISOString();
    saveSettings(settings);
    this.renderContent();
  }

  private async addPrompt(): Promise<void> {
    const picker = dialogShell("添加召回查询项", { className: "echoes-preview-dialog", closeOnly: true });
    const body = picker.querySelector<HTMLElement>(".echoes-dialog-body")!;
    body.innerHTML = `
      <div class="echoes-form-grid">
        <label>类型<select name="kind">
          <option value="current_message">当前消息</option>
          <option value="recent_messages">此前消息</option>
          <option value="character">角色设定</option>
          <option value="persona">用户设定</option>
          <option value="custom">自定义文本</option>
        </select></label>
        <label>标题<input name="title" type="text" value="当前消息"></label>
        <label data-count>消息数量<input name="count" type="number" min="0" max="100" value="4"></label>
        <label class="echoes-form-span" data-content>自定义文本
          <textarea name="content" rows="5"></textarea>
        </label>
      </div>
      <button type="button" class="menu_button echoes-primary" data-add>添加</button>`;
    const kind = body.querySelector<HTMLSelectElement>("[name=kind]")!;
    const title = body.querySelector<HTMLInputElement>("[name=title]")!;
    const countHost = body.querySelector<HTMLElement>("[data-count]")!;
    const contentHost = body.querySelector<HTMLElement>("[data-content]")!;
    const titles: Record<RetrievalQueryPresetItem["kind"], string> = {
      current_message: "当前消息",
      recent_messages: "此前消息",
      character: "角色设定",
      persona: "用户设定",
      custom: "自定义查询文本",
    };
    const refresh = () => {
      const selected = kind.value as RetrievalQueryPresetItem["kind"];
      title.value = titles[selected];
      countHost.classList.toggle("echoes-hidden", selected !== "recent_messages");
      contentHost.classList.toggle("echoes-hidden", selected !== "custom");
    };
    kind.addEventListener("change", refresh);
    refresh();
    body.querySelector("[data-add]")!.addEventListener("click", () => {
      const selected = kind.value as RetrievalQueryPresetItem["kind"];
      const base = {
        id: newRecallPromptItemId(),
        title: title.value.trim() || titles[selected],
        enabled: true,
      };
      let item: RetrievalQueryPresetItem;
      if (selected === "recent_messages") {
        item = {
          ...base,
          kind: selected,
          count: Math.max(
            0,
            Math.min(100, Number(body.querySelector<HTMLInputElement>("[name=count]")!.value)),
          ),
        };
      } else if (selected === "custom") {
        item = {
          ...base,
          kind: selected,
          content: body.querySelector<HTMLTextAreaElement>("[name=content]")!.value,
        };
      } else {
        item = { ...base, kind: selected };
      }
      const settings = getSettings();
      settings.retrieval.recall.queryPreset.items.push(item);
      settings.retrieval.recall.queryPreset.updatedAt = new Date().toISOString();
      saveSettings(settings);
      picker.close();
      this.renderContent();
    });
    picker.showModal();
  }

  private previewQuery(): void {
    this.savePromptSettings();
    const settings = getSettings();
    const prepared = prepareRecallQuery({
      chat: SillyTavern.getContext().chat,
      preset: settings.retrieval.recall.queryPreset,
      ...queryIdentity(),
    });
    const preview = dialogShell("召回查询词预览", { className: "echoes-preview-dialog", closeOnly: true });
    const pre = document.createElement("pre");
    pre.textContent = prepared.query || "查询词为空。";
    preview.querySelector<HTMLElement>(".echoes-dialog-body")!.append(pre);
    preview.showModal();
  }

  private async preview(): Promise<void> {
    try {
      const result = await recallCoordinator.preview();
      const preview = dialogShell("召回结果预览", { className: "echoes-preview-dialog", closeOnly: true });
      const pre = document.createElement("pre");
      const recentBatches = new Map<string, typeof result.recentSlices>();
      for (const slice of result.recentSlices) {
        const current = recentBatches.get(slice.batch.id) ?? [];
        current.push(slice);
        recentBatches.set(slice.batch.id, current);
      }
      pre.textContent = [
        `Query:\n${result.trace.query}`,
        "",
        `固定近期总结（不占语义 Top K，共 ${result.recentSlices.length} 个切片）`,
        ...([...recentBatches.values()].length > 0
          ? [...recentBatches.values()].flatMap((slices) => [
              `批次 ${slices[0]!.batch.batchNumber}`,
              ...slices.map((slice) => `- [${slice.title}] ${slice.content}`),
            ])
          : ["无"]),
        "",
        `语义 Top K（${result.hits.length} 条）`,
        ...result.hits.map((hit, index) =>
          `${index + 1}. ${hit.document.text}\n`
          + `RRF=${hit.rrfScore} rerank=${hit.rerankScore ?? "-"} weighted=${hit.weightedScore ?? "-"}`),
        ...(result.hits.length === 0 ? ["无"] : []),
      ].join("\n");
      preview.querySelector<HTMLElement>(".echoes-dialog-body")!.append(pre);
      preview.showModal();
      this.renderContent();
    } catch (error) {
      toastr.error(error instanceof Error ? error.message : String(error), "召回预览失败");
    }
  }
}
