import type {
  FailoverDecisionRequired,
  JobRecord,
  RetrievalDocumentSyncResult,
  SummaryBatchInput,
  SummaryGenerationRequest,
  SummaryGenerationResult,
  SummaryCompressionConfig,
  SummarySlice,
  SummarySliceCandidate,
  SummarySyncState,
} from "../../shared/domain";
import { echoesApi } from "../api/client";
import { getSettings } from "../state/settings";
import {
  SummaryWorldbookStore,
  type SummaryWorldbookState,
} from "../worldbook/summary-worldbook";
import {
  automaticSummaryBatch,
  currentChatMessages,
  firstStaleBatchNumber,
  manualSummaryBatch,
  prepareSummaryRequest,
  summarySourceHash,
  type PreparedSummaryRequest,
} from "./summary-request";
import { CompressionCoordinator } from "./compression-coordinator";
import type { CompressionStatus } from "./compression-coordinator";
import {
  summaryRetrievalDocument,
  summaryRetrievalDocumentId,
} from "./retrieval-document";

const TERMINAL_STATES = new Set(["succeeded", "failed", "cancelled", "ambiguous"]);

export type AmbiguousDecisionHandler = (decision: FailoverDecisionRequired) => Promise<boolean>;

async function hashIdentifier(value: string): Promise<string> {
  const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(value));
  return [...new Uint8Array(digest)].map((byte) => byte.toString(16).padStart(2, "0")).join("");
}

async function waitForJob<TResult>(job: JobRecord<TResult>): Promise<JobRecord<TResult>> {
  const deadline = Date.now() + 2 * 60 * 60_000;
  let current = job;
  while (!TERMINAL_STATES.has(current.status) && Date.now() < deadline) {
    await new Promise((resolve) => setTimeout(resolve, 1_000));
    current = await echoesApi.getJob<TResult>(current.id);
  }
  if (!TERMINAL_STATES.has(current.status)) throw new Error("等待后台任务超时。");
  if (current.status !== "succeeded" || !current.result) {
    throw new Error(current.error?.message ?? current.message);
  }
  return current;
}

function defaultDecision(decision: FailoverDecisionRequired): Promise<boolean> {
  if (!decision.nextEndpointId) return Promise.resolve(false);
  return Promise.resolve(window.confirm(
    `${decision.message}\n\n继续会向下一个端点创建新请求，并可能产生重复计费。是否继续？`,
  ));
}

export class SummaryCoordinator {
  readonly store = new SummaryWorldbookStore();
  readonly compression = new CompressionCoordinator(this.store);
  private readonly activeRuns = new Map<string, Promise<SummaryWorldbookState | null>>();
  private readonly rerunAutomatic = new Set<string>();

  load(): Promise<SummaryWorldbookState> {
    return this.store.load();
  }

  async checkIntegrity(currentState?: SummaryWorldbookState): Promise<SummaryWorldbookState> {
    const state = currentState ?? await this.load();
    if (SillyTavern.getContext().chatId !== state.catalog.chatId
      || window.TavernHelper?.getChatWorldbookName("current") !== state.worldbookName) {
      return state;
    }
    const stale = await firstStaleBatchNumber(state, currentChatMessages());
    if (SillyTavern.getContext().chatId !== state.catalog.chatId
      || window.TavernHelper?.getChatWorldbookName("current") !== state.worldbookName) {
      return state;
    }
    if (stale === null || state.slices.every((slice) =>
      slice.batch.batchNumber < stale || slice.batch.state === "stale")) return state;
    const activeBatches = [...new Map(state.slices
      .filter((slice) => slice.batch.state !== "stale" && slice.batch.source?.kind !== "imported")
      .map((slice) => [slice.batch.id, slice.batch])).values()];
    const checkpointBatchNumbers = activeBatches
      .filter((batch) => batch.endMessageId === state.catalog.lastCommittedMessageId)
      .map((batch) => batch.batchNumber);
    const latestCommittedBatchNumber = checkpointBatchNumbers.length > 0
      ? Math.min(...checkpointBatchNumbers)
      : Math.max(0, ...activeBatches.map((batch) => batch.batchNumber));
    if (stale === latestCommittedBatchNumber) {
      const batchIds = [...new Set(state.slices
        .filter((slice) => slice.batch.batchNumber === stale)
        .map((slice) => slice.batch.id))];
      await this.compression.restoreBatch(state, batchIds, false);
      const reset = await this.store.resetFrom(state.worldbookName, stale);
      try {
        return await this.syncSlices(reset, [], reset.catalog.pendingRetrievalDeletes);
      } catch {
        return this.store.inspect(reset.worldbookName);
      }
    }
    const marked = await this.store.markStaleFrom(state.worldbookName, stale);
    try {
      return await this.syncSlices(marked, [], marked.catalog.pendingRetrievalDeletes);
    } catch {
      return this.store.inspect(marked.worldbookName);
    }
  }

  async setAutoRun(enabled: boolean): Promise<SummaryWorldbookState> {
    const state = await this.load();
    return this.store.setAutoRun(state.worldbookName, enabled);
  }

  async setRecallEnabled(enabled: boolean): Promise<SummaryWorldbookState> {
    const state = await this.load();
    return this.store.saveRecallConfiguration(state.worldbookName, {
      enabled,
      weight: state.catalog.recallSourceWeight,
      order: state.catalog.recallSourceOrder,
      attachedSources: state.catalog.attachedRecallSources,
    });
  }

  async saveCompression(
    compression: SummaryCompressionConfig,
  ): Promise<{ state: SummaryWorldbookState; status: CompressionStatus }> {
    const state = await this.load();
    const updated = await this.store.saveCompressionConfiguration(
      state.worldbookName,
      compression,
    );
    const status = await this.compression.reconcile(updated);
    return { state: updated, status };
  }

  runAutomatic(
    decide: AmbiguousDecisionHandler = defaultDecision,
  ): Promise<SummaryWorldbookState | null> {
    const lockedChatId = SillyTavern.getContext().chatId;
    if (!lockedChatId) return Promise.resolve(null);
    const existing = this.activeRuns.get(lockedChatId);
    if (existing) {
      this.rerunAutomatic.add(lockedChatId);
      return existing;
    }
    const operation = this.performAutomatic(lockedChatId, decide).finally(() => {
      this.finishRun(lockedChatId, operation, decide);
    });
    this.activeRuns.set(lockedChatId, operation);
    return operation;
  }

  private async performAutomatic(
    lockedChatId: string,
    decide: AmbiguousDecisionHandler,
  ): Promise<SummaryWorldbookState | null> {
    if (SillyTavern.getContext().chatId !== lockedChatId) return null;
    let state = await this.checkIntegrity();
    if (state.catalog.chatId !== lockedChatId) {
      throw new Error("The summary catalog does not belong to the locked chat.");
    }
    if (state.slices.some((slice) => slice.batch.state === "stale"
      && slice.batch.source?.kind !== "imported")) return state;
    if (!state.catalog.autoRun) {
      await this.compression.reconcile(state);
      return state;
    }
    while (SillyTavern.getContext().chatId === lockedChatId) {
      const candidate = await automaticSummaryBatch(
        currentChatMessages(),
        state.catalog,
        getSettings().summary.messageCount,
      );
      if (!candidate) break;
      const next = await this.generate(state, candidate.batch, candidate.messages, decide, true);
      if (!next) break;
      state = next;
    }
    await this.compression.reconcile(state);
    return state;
  }

  runManual(
    startIndex: number,
    endIndex: number,
    decide: AmbiguousDecisionHandler = defaultDecision,
  ): Promise<SummaryWorldbookState | null> {
    const lockedChatId = SillyTavern.getContext().chatId;
    if (!lockedChatId) return Promise.resolve(null);
    if (this.activeRuns.has(lockedChatId)) {
      return Promise.reject(new Error("This chat already has a summary task running."));
    }
    const operation = this.performManual(lockedChatId, startIndex, endIndex, decide).finally(() => {
      this.finishRun(lockedChatId, operation, defaultDecision);
    });
    this.activeRuns.set(lockedChatId, operation);
    return operation;
  }

  private async performManual(
    lockedChatId: string,
    startIndex: number,
    endIndex: number,
    decide: AmbiguousDecisionHandler,
  ): Promise<SummaryWorldbookState | null> {
    if (SillyTavern.getContext().chatId !== lockedChatId) return null;
    const state = await this.checkIntegrity();
    if (state.catalog.chatId !== lockedChatId) {
      throw new Error("The summary catalog does not belong to the locked chat.");
    }
    const messages = currentChatMessages();
    const candidate = await manualSummaryBatch(
      messages,
      state.catalog,
      startIndex,
      endIndex,
    );
    const checkpointIndex = state.catalog.lastCommittedMessageId
      ? messages.findIndex((message) => message.id === state.catalog.lastCommittedMessageId)
      : -1;
    const advancesCheckpoint = startIndex === checkpointIndex + 1;
    return this.generate(state, candidate.batch, candidate.messages, decide, advancesCheckpoint);
  }

  rebuildBatch(
    batchNumber: number,
    decide: AmbiguousDecisionHandler = defaultDecision,
  ): Promise<SummaryWorldbookState | null> {
    const lockedChatId = SillyTavern.getContext().chatId;
    if (!lockedChatId) return Promise.resolve(null);
    if (this.activeRuns.has(lockedChatId)) {
      return Promise.reject(new Error("This chat already has a summary task running."));
    }
    const operation = this.performRebuild(lockedChatId, batchNumber, decide).finally(() => {
      this.finishRun(lockedChatId, operation, defaultDecision);
    });
    this.activeRuns.set(lockedChatId, operation);
    return operation;
  }

  private async performRebuild(
    lockedChatId: string,
    batchNumber: number,
    decide: AmbiguousDecisionHandler,
  ): Promise<SummaryWorldbookState | null> {
    if (SillyTavern.getContext().chatId !== lockedChatId) return null;
    const state = await this.load();
    if (state.catalog.chatId !== lockedChatId) {
      throw new Error("The summary catalog does not belong to the locked chat.");
    }
    const existing = state.slices.find((slice) => slice.batch.batchNumber === batchNumber)?.batch;
    if (!existing) throw new Error("总结批次不存在。");
    const messages = currentChatMessages();
    const start = messages.findIndex((message) => message.id === existing.startMessageId);
    const end = messages.findIndex((message) => message.id === existing.endMessageId);
    if (start < 0 || end < start) throw new Error("原消息范围已不存在，请从该批次重置后重新总结。");
    const candidate = await manualSummaryBatch(messages, state.catalog, start, end, existing);
    return this.generate(state, candidate.batch, candidate.messages, decide, false);
  }

  async previewManual(startIndex: number, endIndex: number): Promise<PreparedSummaryRequest> {
    const state = await this.load();
    const candidate = await manualSummaryBatch(
      currentChatMessages(),
      state.catalog,
      startIndex,
      endIndex,
    );
    return prepareSummaryRequest({
      batch: candidate.batch,
      messages: candidate.messages,
      state,
      settings: getSettings(),
    });
  }

  async editSlice(sliceId: string, candidate: SummarySliceCandidate): Promise<SummaryWorldbookState> {
    const state = await this.load();
    const updated = await this.store.saveSlice(state.worldbookName, sliceId, candidate);
    const slice = updated.slices.find((item) => item.id === sliceId);
    if (!slice) throw new Error("总结切片不存在。");
    const synced = await this.syncSlices(updated, [slice], updated.catalog.pendingRetrievalDeletes);
    await this.compression.reconcile(synced);
    return synced;
  }

  async deleteSlice(sliceId: string): Promise<SummaryWorldbookState> {
    const state = await this.load();
    const updated = await this.store.deleteSlice(state.worldbookName, sliceId);
    return this.syncSlices(updated, [], updated.catalog.pendingRetrievalDeletes);
  }

  async resetFrom(batchNumber: number): Promise<SummaryWorldbookState> {
    const state = await this.load();
    const updated = await this.store.resetFrom(state.worldbookName, batchNumber);
    return this.syncSlices(updated, [], updated.catalog.pendingRetrievalDeletes);
  }

  async repairIndex(decide: AmbiguousDecisionHandler = defaultDecision): Promise<SummaryWorldbookState> {
    let state = await this.load();
    const active = state.slices.filter((slice) => slice.batch.state !== "stale");
    if (active.length === 0 && state.catalog.pendingRetrievalDeletes.length > 0) {
      return this.syncSlices(state, [], state.catalog.pendingRetrievalDeletes, decide);
    }
    for (let offset = 0; offset < active.length; offset += 50) {
      state = await this.syncSlices(
        state,
        active.slice(offset, offset + 50),
        offset === 0 ? state.catalog.pendingRetrievalDeletes : [],
        decide,
      );
    }
    await this.compression.reconcile(state);
    return state;
  }

  private async generate(
    state: SummaryWorldbookState,
    batch: SummaryBatchInput,
    messages: SummaryGenerationRequest["messages"],
    decide: AmbiguousDecisionHandler,
    advanceCheckpoint: boolean,
  ): Promise<SummaryWorldbookState | null> {
    const settings = getSettings();
    const workflow = settings.generationWorkflows.summary;
    const group = settings.generationGroups.find((candidate) => candidate.id === workflow.groupId);
    if (!group) throw new Error("请先配置总结生成端点组。");
    const prepared = await prepareSummaryRequest({ batch, messages, state, settings });
    let resumeAfterEndpointId: string | undefined;
    let result: SummaryGenerationResult;
    while (true) {
      const request: SummaryGenerationRequest = {
        chatId: state.catalog.chatId,
        batch,
        messages: prepared.originalMessages,
        promptMessages: prepared.promptMessages,
        generationGroup: group,
        failoverPolicy: workflow.failoverPolicy,
        ...(resumeAfterEndpointId ? { resumeAfterEndpointId } : {}),
      };
      result = (await waitForJob(await echoesApi.startSummary(request))).result!;
      if (!result.decisionRequired) break;
      if (!await decide(result.decisionRequired)) return null;
      resumeAfterEndpointId = result.decisionRequired.failedEndpointId;
    }
    if (result.outcome !== "completed" || result.slices.length === 0) return null;
    await this.assertCurrentSourceUnchanged(state, batch);
    const existingBatch = state.slices.find((slice) => slice.batch.id === batch.id)?.batch;
    const committed = await this.store.commitBatch({
      worldbookName: state.worldbookName,
      catalog: state.catalog,
      batch,
      candidates: result.slices,
      advanceCheckpoint,
      expectedCheckpoint: state.catalog.lastCommittedMessageId ?? null,
      expectedNextBatchNumber: state.catalog.nextBatchNumber,
      expectedBatchRevision: existingBatch?.revision ?? null,
    });
    const slices = committed.slices.filter((slice) => slice.batch.id === batch.id);
    const synced = await this.syncSlices(
      committed,
      slices,
      committed.catalog.pendingRetrievalDeletes,
      decide,
    );
    await this.compression.reconcile(synced);
    return synced;
  }

  private async assertCurrentSourceUnchanged(
    state: SummaryWorldbookState,
    batch: SummaryBatchInput,
  ): Promise<void> {
    if (SillyTavern.getContext().chatId !== state.catalog.chatId) return;
    const current = currentChatMessages();
    const start = current.findIndex((message) => message.id === batch.startMessageId);
    const end = current.findIndex((message) => message.id === batch.endMessageId);
    const selected = start >= 0 && end >= start ? current.slice(start, end + 1) : [];
    if (selected.length !== batch.messageIds.length
      || selected.some((message, index) => message.id !== batch.messageIds[index])
      || await summarySourceHash(selected) !== batch.sourceHash) {
      throw new Error("The summary source messages changed while the generation task was running.");
    }
  }

  private finishRun(
    chatId: string,
    operation: Promise<SummaryWorldbookState | null>,
    decide: AmbiguousDecisionHandler,
  ): void {
    if (this.activeRuns.get(chatId) === operation) this.activeRuns.delete(chatId);
    if (!this.rerunAutomatic.delete(chatId) || SillyTavern.getContext().chatId !== chatId) return;
    queueMicrotask(() => {
      void this.runAutomatic(decide).catch((error) => {
        console.error("[Echoes] Deferred summary automation failed.", error);
      });
    });
  }

  private async syncSlices(
    initialState: SummaryWorldbookState,
    slices: SummarySlice[],
    deletedSliceIds: string[],
    decide: AmbiguousDecisionHandler = defaultDecision,
  ): Promise<SummaryWorldbookState> {
    const settings = getSettings();
    const embeddingGroup = settings.retrieval.embeddingGroups.find((group) =>
      group.id === settings.summary.embeddingGroupId);
    if (!embeddingGroup) {
      let state = initialState;
      if (state.catalog.retrievalCollectionId) {
        for (let offset = 0; offset < deletedSliceIds.length; offset += 1_000) {
          const sliceIds = deletedSliceIds.slice(offset, offset + 1_000);
          const deleteDocumentIds = await Promise.all(sliceIds.map((id) =>
            summaryRetrievalDocumentId(state.catalog.retrievalCollectionId!, id)));
          await waitForJob(await echoesApi.syncRetrievalDocuments({
            documents: [],
            deleteDocumentIds,
            failoverPolicy: settings.retrieval.failoverPolicy,
          }));
          state = await this.store.clearPendingDeletes(state.worldbookName, sliceIds);
        }
      }
      const batches = [...new Set(slices.map((slice) => slice.batch.id))];
      for (const batchId of batches) state = await this.store.markBatchState(state.worldbookName, batchId, "pending");
      return state;
    }
    const previousCollectionId = initialState.catalog.retrievalCollectionId;
    let state = await this.ensureCollection(initialState, embeddingGroup.id);
    const collectionId = state.catalog.retrievalCollectionId!;
    const collectionChanged = collectionId !== previousCollectionId;
    const targetSlices = collectionChanged
      ? state.slices.filter((slice) => slice.batch.state !== "stale")
      : slices;
    if (targetSlices.length > 100 || deletedSliceIds.length > 1_000) {
      const batches = Math.max(
        Math.ceil(targetSlices.length / 100),
        Math.ceil(deletedSliceIds.length / 1_000),
      );
      for (let index = 0; index < batches; index += 1) {
        state = await this.syncSlices(
          state,
          targetSlices.slice(index * 100, (index + 1) * 100),
          deletedSliceIds.slice(index * 1_000, (index + 1) * 1_000),
          decide,
        );
      }
      return state;
    }
    const batches = [...new Set(targetSlices.map((slice) => slice.batch.id))];
    const documents = await Promise.all(targetSlices.map((slice) =>
      summaryRetrievalDocument(collectionId, slice, state.catalog.chatId)));
    const deleteDocumentIds = await Promise.all(deletedSliceIds.map((id) =>
      summaryRetrievalDocumentId(collectionId, id)));
    let resumeAfterEndpointId: string | undefined;
    let result: RetrievalDocumentSyncResult;
    try {
      while (true) {
        result = (await waitForJob(await echoesApi.syncRetrievalDocuments({
          documents,
          deleteDocumentIds,
          embeddingGroup,
          failoverPolicy: settings.retrieval.failoverPolicy,
          ...(resumeAfterEndpointId ? { resumeAfterEndpointId } : {}),
        }))).result!;
        if (!result.decisionRequired) break;
        if (!await decide(result.decisionRequired)) break;
        resumeAfterEndpointId = result.decisionRequired.failedEndpointId;
      }
    } catch (error) {
      for (const batchId of batches) state = await this.store.markBatchState(state.worldbookName, batchId, "failed");
      throw error;
    }
    if (documents.length > 0) {
      const statuses = await echoesApi.retrievalDocumentStatus(documents.map((document) => document.documentId!));
      const stateByDocumentId = new Map(statuses.documents.map((document) => [document.documentId, document.vectorState]));
      const documentIdBySliceId = new Map(targetSlices.map((slice, index) => [slice.id, documents[index]!.documentId!]));
      for (const batchId of batches) {
        const vectorStates = targetSlices
          .filter((slice) => slice.batch.id === batchId)
          .map((slice) => stateByDocumentId.get(documentIdBySliceId.get(slice.id)!));
        const syncState: SummarySyncState = vectorStates.includes("ambiguous")
          ? "ambiguous"
          : vectorStates.includes("failed")
            ? "failed"
            : vectorStates.includes("pending") || vectorStates.includes(undefined)
              ? "pending"
              : "ready";
        state = await this.store.markBatchState(state.worldbookName, batchId, syncState);
      }
    }
    if (result.deleted >= 0 && deletedSliceIds.length > 0) {
      state = await this.store.clearPendingDeletes(state.worldbookName, deletedSliceIds);
    }
    return state;
  }

  private async ensureCollection(
    state: SummaryWorldbookState,
    embeddingGroupId: string,
  ): Promise<SummaryWorldbookState> {
    const group = getSettings().retrieval.embeddingGroups.find((candidate) => candidate.id === embeddingGroupId)!;
    if (state.catalog.retrievalCollectionId && state.catalog.retrievalEmbeddingSpaceId === group.embeddingSpaceId) {
      return state;
    }
    const digest = await hashIdentifier(`${state.catalog.namespaceId}\0${group.embeddingSpaceId}`);
    const collectionId = `summary_${digest.slice(0, 48)}`;
    const collections = await echoesApi.listRetrievalCollections();
    if (!collections.some((item) => item.collection.id === collectionId)) {
      try {
        await echoesApi.createRetrievalCollection({
          id: collectionId,
          name: `聊天总结 - ${state.catalog.chatId}`.slice(0, 120),
          description: "Echoes 根据聊天世界书重建的总结检索集合。",
          embeddingSpaceId: group.embeddingSpaceId,
          dimensions: group.dimensions,
        });
      } catch (error) {
        const refreshed = await echoesApi.listRetrievalCollections();
        if (!refreshed.some((item) => item.collection.id === collectionId)) throw error;
      }
    }
    return this.store.setRetrievalBinding(state.worldbookName, collectionId, group.embeddingSpaceId);
  }

}
