import type {
  AttachedRecallSource,
  SummaryBatchInput,
  SummaryCatalog,
  SummarySlice,
  SummarySliceCandidate,
  SummarySyncState,
} from "../../shared/domain";
import {
  summaryCatalogSchema,
  summarySliceCandidateSchema,
  summarySliceSchema,
} from "../../shared/schemas";
import { worldbookWriteCoordinator } from "./worldbook-write-coordinator";

interface SummaryCatalogMetadata {
  kind: "summary_catalog";
  version: 1 | 2;
  catalog: SummaryCatalog;
}

interface SummarySliceMetadata {
  kind: "summary_slice";
  version: 1 | 2;
  summaryId: string;
  title: string;
  tags: string[];
  batch: SummarySlice["batch"];
  sliceNumber: number;
}

export interface SummaryWorldbookState {
  worldbookName: string;
  catalog: SummaryCatalog;
  slices: SummarySlice[];
}

function helper(): TavernHelperApi {
  if (!window.TavernHelper) throw new Error("Echoes requires TavernHelper for summary storage.");
  return window.TavernHelper;
}

function uniqueId(prefix: string): string {
  return `${prefix}_${crypto.randomUUID().replaceAll("-", "")}`;
}

function metadata(entry: TavernWorldbookEntry): SummaryCatalogMetadata | SummarySliceMetadata | null {
  const value = entry.extra?.echoes as { version?: unknown; kind?: unknown } | undefined;
  if (!value || (value.version !== 1 && value.version !== 2)) return null;
  if (value.kind !== "summary_catalog" && value.kind !== "summary_slice") return null;
  return value as SummaryCatalogMetadata | SummarySliceMetadata;
}

function createCatalog(chatId: string): SummaryCatalog {
  return {
    formatVersion: 2,
    chatId,
    namespaceId: uniqueId("summary_namespace"),
    autoRun: false,
    recallEnabled: false,
    recallSourceWeight: 1,
    recallSourceOrder: 0,
    attachedRecallSources: [],
    compression: {
      enabled: false,
      keepRecentMessages: 30,
      recentBatchCount: 2,
      deletionPolicy: "confirm_restore",
    },
    nextBatchNumber: 1,
    pendingRetrievalDeletes: [],
    updatedAt: new Date().toISOString(),
  };
}

function catalogEntry(catalog: SummaryCatalog): Partial<TavernWorldbookEntry> {
  return {
    name: "Echoes Summary Catalog",
    enabled: false,
    strategy: { type: "constant", keys: [] },
    content: "Echoes summary catalog. Managed by the Echoes extension.",
    extra: { echoes: { kind: "summary_catalog", version: 2, catalog } satisfies SummaryCatalogMetadata },
  };
}

function summaryId(namespaceId: string, batchNumber: number, sliceNumber: number): string {
  const namespace = namespaceId.replace(/^summary_namespace_/, "").slice(0, 32);
  return `summary_${namespace}_${batchNumber}_${sliceNumber}`;
}

function sliceEntry(slice: SummarySlice): Partial<TavernWorldbookEntry> {
  return {
    name: `总结 ${slice.batch.batchNumber}.${slice.sliceNumber} - ${slice.title}`,
    enabled: false,
    strategy: { type: "selective", keys: slice.tags },
    content: slice.content,
    extra: {
      echoes: {
        kind: "summary_slice",
        version: 2,
        summaryId: slice.id,
        title: slice.title,
        tags: slice.tags,
        batch: slice.batch,
        sliceNumber: slice.sliceNumber,
      } satisfies SummarySliceMetadata,
    },
  };
}

function readState(worldbookName: string, entries: TavernWorldbookEntry[]): SummaryWorldbookState | null {
  const catalogWorldbookEntry = entries.find((entry) => metadata(entry)?.kind === "summary_catalog");
  if (!catalogWorldbookEntry) return null;
  const catalogMetadata = metadata(catalogWorldbookEntry) as SummaryCatalogMetadata;
  const catalog = summaryCatalogSchema.parse(catalogMetadata.catalog);
  const slices = entries.flatMap((entry): SummarySlice[] => {
    const item = metadata(entry);
    if (!item || item.kind !== "summary_slice") return [];
    return [summarySliceSchema.parse({
      id: item.summaryId,
      title: item.title,
      content: entry.content,
      tags: item.tags,
      batch: item.batch,
      sliceNumber: item.sliceNumber,
      worldbookUid: entry.uid,
    })];
  }).sort((left, right) => left.batch.batchNumber - right.batch.batchNumber || left.sliceNumber - right.sliceNumber);
  return { worldbookName, catalog, slices };
}

function structuredCatalogChatId(entries: TavernWorldbookEntry[]): string | null {
  for (const entry of entries) {
    const echoes = entry.extra?.echoes as { kind?: unknown; catalog?: { chatId?: unknown } } | undefined;
    if (echoes?.kind === "catalog" && typeof echoes.catalog?.chatId === "string") return echoes.catalog.chatId;
  }
  return null;
}

export class SummaryWorldbookStore {
  async load(): Promise<SummaryWorldbookState> {
    const chatId = SillyTavern.getContext().chatId;
    if (!chatId) throw new Error("Open a SillyTavern chat before using summaries.");
    const api = helper();
    const boundWorldbookName = api.getChatWorldbookName("current");
    return worldbookWriteCoordinator.run(boundWorldbookName ?? `chat:${chatId}`, async () => {
      if (SillyTavern.getContext().chatId !== chatId) {
        throw new Error("The active chat changed before the summary operation started.");
      }
      const baseName = chatId.replace(/\.(json|jsonl)$/i, "");
      let worldbookName = boundWorldbookName;
      if (!worldbookName) {
        worldbookName = await api.getOrCreateChatWorldbook("current", `Echoes-${baseName}`);
        if (SillyTavern.getContext().chatId !== chatId) {
          throw new Error("The active chat changed while the summary worldbook was being created.");
        }
      }
      let entries = await api.getWorldbook(worldbookName);
      let state = readState(worldbookName, entries);
      if ((state && state.catalog.chatId !== chatId)
        || (!state && structuredCatalogChatId(entries) && structuredCatalogChatId(entries) !== chatId)) {
        const names = new Set(api.getWorldbookNames());
        let candidate = `Echoes-${baseName}`;
        let suffix = 2;
        while (names.has(candidate)) candidate = `Echoes-${baseName}-${suffix++}`;
        await api.createWorldbook(candidate);
        if (SillyTavern.getContext().chatId !== chatId) {
          throw new Error("The active chat changed before the summary worldbook could be rebound.");
        }
        await api.rebindChatWorldbook("current", candidate);
        if (SillyTavern.getContext().chatId !== chatId) {
          throw new Error("The active chat changed while the summary worldbook was being rebound.");
        }
        worldbookName = candidate;
        entries = [];
        state = null;
      }
      if (!state) {
        await api.createWorldbookEntries(worldbookName, [catalogEntry(createCatalog(chatId))]);
        entries = await api.getWorldbook(worldbookName);
        state = readState(worldbookName, entries);
      }
      if (!state) throw new Error("Failed to initialize the Echoes summary catalog.");
      return state;
    });
  }

  inspect(worldbookName: string): Promise<SummaryWorldbookState> {
    return helper().getWorldbook(worldbookName).then((entries) => {
      const state = readState(worldbookName, entries);
      if (!state) throw new Error("The worldbook has no Echoes summary catalog.");
      return state;
    });
  }

  async listAvailableSources(): Promise<SummaryWorldbookState[]> {
    const inspected = await Promise.allSettled(
      helper().getWorldbookNames().map((worldbookName) => this.inspect(worldbookName)),
    );
    return inspected.flatMap((result) => result.status === "fulfilled" ? [result.value] : []);
  }

  commitBatch(options: {
    worldbookName: string;
    catalog: SummaryCatalog;
    batch: SummaryBatchInput;
    candidates: SummarySliceCandidate[];
    advanceCheckpoint?: boolean | undefined;
    expectedCheckpoint?: string | null | undefined;
    expectedNextBatchNumber?: number | undefined;
    expectedBatchRevision?: number | null | undefined;
  }): Promise<SummaryWorldbookState> {
    return this.serialize(options.worldbookName, async () => {
      const api = helper();
      const now = new Date().toISOString();
      await api.updateWorldbookWith(options.worldbookName, (entries) => {
        const currentState = readState(options.worldbookName, entries);
        if (!currentState || currentState.catalog.namespaceId !== options.catalog.namespaceId) {
          throw new Error("The summary worldbook changed while the generation task was running.");
        }
        const existing = currentState.slices.filter((slice) => slice.batch.id === options.batch.id);
        if (options.expectedCheckpoint !== undefined
          && (currentState.catalog.lastCommittedMessageId ?? null) !== options.expectedCheckpoint) {
          throw new Error("The summary checkpoint changed while the generation task was running.");
        }
        if (options.expectedNextBatchNumber !== undefined
          && currentState.catalog.nextBatchNumber !== options.expectedNextBatchNumber) {
          throw new Error("The summary batch sequence changed while the generation task was running.");
        }
        if (options.expectedBatchRevision !== undefined) {
          const currentRevision = existing.length > 0
            ? Math.max(...existing.map((slice) => slice.batch.revision))
            : null;
          if (currentRevision !== options.expectedBatchRevision) {
            throw new Error("The summary batch revision changed while the generation task was running.");
          }
        }
        const revision = Math.max(0, ...existing.map((slice) => slice.batch.revision)) + 1;
        const createdAt = existing[0]?.batch.createdAt ?? now;
        const slices: SummarySlice[] = options.candidates.map((candidate, index) => ({
          ...summarySliceCandidateSchema.parse(candidate),
          id: summaryId(currentState.catalog.namespaceId, options.batch.batchNumber, index + 1),
          sliceNumber: index + 1,
          batch: {
            ...options.batch,
            source: { kind: "chat_messages" },
            state: "pending",
            revision,
            createdAt,
            updatedAt: now,
          },
        }));
        const desiredIds = new Set(slices.map((slice) => slice.id));
        const removedIds = existing.map((slice) => slice.id).filter((id) => !desiredIds.has(id));
        const existingIds = new Set(existing.map((slice) => slice.id));
        const nextCatalog = summaryCatalogSchema.parse({
          ...currentState.catalog,
          ...(options.advanceCheckpoint !== false
            ? { lastCommittedMessageId: options.batch.endMessageId }
            : {}),
          nextBatchNumber: Math.max(currentState.catalog.nextBatchNumber, options.batch.batchNumber + 1),
          pendingRetrievalDeletes: [...new Set([
            ...currentState.catalog.pendingRetrievalDeletes,
            ...removedIds,
          ])],
          updatedAt: now,
        });
        const nextEntries = entries.flatMap((entry) => {
          const item = metadata(entry);
          if (item?.kind === "summary_catalog") {
            return [{ ...entry, ...catalogEntry(nextCatalog) }];
          }
          if (item?.kind === "summary_slice" && item.batch.id === options.batch.id) {
            const replacement = slices.find((slice) => slice.id === item.summaryId);
            return replacement ? [{ ...entry, ...sliceEntry(replacement) }] : [];
          }
          return [entry];
        });
        nextEntries.push(...slices
          .filter((slice) => !existingIds.has(slice.id))
          .map((slice) => sliceEntry(slice) as TavernWorldbookEntry));
        return nextEntries;
      });
      return this.inspect(options.worldbookName);
    });
  }

  setAutoRun(worldbookName: string, enabled: boolean): Promise<SummaryWorldbookState> {
    return this.updateState(worldbookName, (catalog) => ({ ...catalog, autoRun: enabled }));
  }

  saveCompressionConfiguration(
    worldbookName: string,
    compression: SummaryCatalog["compression"],
  ): Promise<SummaryWorldbookState> {
    return this.updateState(worldbookName, (catalog) => ({
      ...catalog,
      compression: structuredClone(compression),
    }));
  }

  saveRecallConfiguration(
    worldbookName: string,
    configuration: {
      enabled: boolean;
      weight: number;
      order: number;
      attachedSources: AttachedRecallSource[];
    },
  ): Promise<SummaryWorldbookState> {
    return this.updateState(worldbookName, (catalog) => ({
      ...catalog,
      recallEnabled: configuration.enabled,
      recallSourceWeight: configuration.weight,
      recallSourceOrder: configuration.order,
      attachedRecallSources: structuredClone(configuration.attachedSources),
    }));
  }

  setRetrievalBinding(
    worldbookName: string,
    collectionId: string,
    embeddingSpaceId: string,
  ): Promise<SummaryWorldbookState> {
    return this.updateState(worldbookName, (catalog) => ({
      ...catalog,
      retrievalCollectionId: collectionId,
      retrievalEmbeddingSpaceId: embeddingSpaceId,
    }));
  }

  markBatchState(worldbookName: string, batchId: string, state: SummarySyncState): Promise<SummaryWorldbookState> {
    return this.serialize(worldbookName, async () => {
      const api = helper();
      const now = new Date().toISOString();
      await api.updateWorldbookWith(worldbookName, (entries) => entries.map((entry) => {
        const item = metadata(entry);
        if (item?.kind !== "summary_slice" || item.batch.id !== batchId) return entry;
        return {
          ...entry,
          extra: {
            ...entry.extra,
            echoes: { ...item, batch: { ...item.batch, state, updatedAt: now } },
          },
        };
      }));
      return this.inspect(worldbookName);
    });
  }

  markStaleFrom(worldbookName: string, batchNumber: number): Promise<SummaryWorldbookState> {
    return this.serialize(worldbookName, async () => {
      const api = helper();
      const now = new Date().toISOString();
      const state = await this.inspect(worldbookName);
      const staleIds = state.slices
        .filter((slice) => slice.batch.source?.kind !== "imported"
          && slice.batch.batchNumber >= batchNumber)
        .map((slice) => slice.id);
      await api.updateWorldbookWith(worldbookName, (entries) => entries.map((entry) => {
        const item = metadata(entry);
        if (item?.kind !== "summary_slice"
          || item.batch.source?.kind === "imported"
          || item.batch.batchNumber < batchNumber) return entry;
        return {
          ...entry,
          extra: {
            ...entry.extra,
            echoes: { ...item, batch: { ...item.batch, state: "stale", updatedAt: now } },
          },
        };
      }));
      await this.updateCatalog(worldbookName, {
        ...state.catalog,
        pendingRetrievalDeletes: [...new Set([
          ...state.catalog.pendingRetrievalDeletes,
          ...staleIds,
        ])],
        updatedAt: now,
      });
      return this.inspect(worldbookName);
    });
  }

  saveSlice(worldbookName: string, sliceId: string, candidate: SummarySliceCandidate): Promise<SummaryWorldbookState> {
    return this.serialize(worldbookName, async () => {
      const api = helper();
      const parsed = summarySliceCandidateSchema.parse(candidate);
      const now = new Date().toISOString();
      await api.updateWorldbookWith(worldbookName, (entries) => entries.map((entry) => {
        const item = metadata(entry);
        if (item?.kind !== "summary_slice" || item.summaryId !== sliceId) return entry;
        const updated: SummarySlice = {
          ...parsed,
          id: item.summaryId,
          sliceNumber: item.sliceNumber,
          worldbookUid: entry.uid,
          batch: {
            ...item.batch,
            state: "pending",
            revision: item.batch.revision + 1,
            updatedAt: now,
          },
        };
        return { ...entry, ...sliceEntry(updated) };
      }));
      return this.inspect(worldbookName);
    });
  }

  deleteSlice(worldbookName: string, sliceId: string): Promise<SummaryWorldbookState> {
    return this.serialize(worldbookName, async () => {
      const state = await this.inspect(worldbookName);
      await helper().updateWorldbookWith(worldbookName, (entries) => entries.filter((entry) => {
        const item = metadata(entry);
        return item?.kind !== "summary_slice" || item.summaryId !== sliceId;
      }));
      await this.updateCatalog(worldbookName, {
        ...state.catalog,
        pendingRetrievalDeletes: [...new Set([...state.catalog.pendingRetrievalDeletes, sliceId])],
        updatedAt: new Date().toISOString(),
      });
      return this.inspect(worldbookName);
    });
  }

  resetFrom(worldbookName: string, batchNumber: number): Promise<SummaryWorldbookState> {
    return this.serialize(worldbookName, async () => {
      const state = await this.inspect(worldbookName);
      const removed = state.slices.filter((slice) => slice.batch.source?.kind !== "imported"
        && slice.batch.batchNumber >= batchNumber);
      const retained = state.slices.filter((slice) => slice.batch.source?.kind !== "imported"
        && slice.batch.batchNumber < batchNumber);
      const previous = retained.at(-1)?.batch;
      await helper().updateWorldbookWith(worldbookName, (entries) => entries.filter((entry) => {
        const item = metadata(entry);
        return item?.kind !== "summary_slice"
          || item.batch.source?.kind === "imported"
          || item.batch.batchNumber < batchNumber;
      }));
      const nextCatalog: SummaryCatalog = {
        ...state.catalog,
        nextBatchNumber: batchNumber,
        pendingRetrievalDeletes: [...new Set([
          ...state.catalog.pendingRetrievalDeletes,
          ...removed.map((slice) => slice.id),
        ])],
        updatedAt: new Date().toISOString(),
      };
      if (previous) nextCatalog.lastCommittedMessageId = previous.endMessageId;
      else delete nextCatalog.lastCommittedMessageId;
      await this.updateCatalog(worldbookName, nextCatalog);
      return this.inspect(worldbookName);
    });
  }

  clearPendingDeletes(worldbookName: string, deletedIds: string[]): Promise<SummaryWorldbookState> {
    const removed = new Set(deletedIds);
    return this.updateState(worldbookName, (catalog) => ({
      ...catalog,
      pendingRetrievalDeletes: catalog.pendingRetrievalDeletes.filter((id) => !removed.has(id)),
    }));
  }

  private updateState(
    worldbookName: string,
    updater: (catalog: SummaryCatalog) => SummaryCatalog,
  ): Promise<SummaryWorldbookState> {
    return this.serialize(worldbookName, async () => {
      const state = await this.inspect(worldbookName);
      const catalog = {
        ...updater(structuredClone(state.catalog)),
        updatedAt: new Date().toISOString(),
      };
      await this.updateCatalog(worldbookName, catalog);
      return this.inspect(worldbookName);
    });
  }

  private async updateCatalog(worldbookName: string, catalog: SummaryCatalog): Promise<void> {
    const parsed = summaryCatalogSchema.parse(catalog);
    await helper().updateWorldbookWith(worldbookName, (entries) => entries.map((entry) => {
      const item = metadata(entry);
      return item?.kind === "summary_catalog" ? { ...entry, ...catalogEntry(parsed) } : entry;
    }));
  }

  private serialize<T>(worldbookName: string, operation: () => Promise<T>): Promise<T> {
    return worldbookWriteCoordinator.run(worldbookName, operation);
  }
}
