import type {
  RetrievalInjectionConfig,
  StatusCatalog,
  StatusProfile,
} from "../../shared/domain";
import { statusCatalogSchema } from "../../shared/schemas";
import { instantiateStatusProfile } from "../state/settings";
import { worldbookWriteCoordinator } from "./worldbook-write-coordinator";

interface StatusCatalogMetadata {
  kind: "status_catalog";
  version: 1;
  catalog: StatusCatalog;
}

interface StatusInjectionMetadata {
  kind: "status_injection";
  version: 1;
  chatId: string;
  namespaceId: string;
  createdAt: string;
  updatedAt: string;
}

export interface StatusWorldbookState {
  worldbookName: string;
  catalog: StatusCatalog;
}

const CATALOG_NAME = "[Echoes] Status Catalog";
const INJECTION_NAME = "[Echoes] Status Injection";
const STALE_MS = 5 * 60_000;

function helper(): TavernHelperApi {
  if (!window.TavernHelper) throw new Error("Echoes requires TavernHelper for status storage.");
  return window.TavernHelper;
}

function uniqueId(prefix: string): string {
  return `${prefix}_${crypto.randomUUID().replaceAll("-", "")}`;
}

function catalogMetadata(entry: TavernWorldbookEntry): StatusCatalogMetadata | null {
  const value = entry.extra?.echoes as Partial<StatusCatalogMetadata> | undefined;
  return value?.kind === "status_catalog" && value.version === 1
    ? value as StatusCatalogMetadata
    : null;
}

function injectionMetadata(entry: TavernWorldbookEntry): StatusInjectionMetadata | null {
  const value = entry.extra?.echoes as Partial<StatusInjectionMetadata> | undefined;
  return value?.kind === "status_injection" && value.version === 1
    ? value as StatusInjectionMetadata
    : null;
}

function createCatalog(chatId: string): StatusCatalog {
  return {
    formatVersion: 1,
    chatId,
    namespaceId: uniqueId("status_namespace"),
    enabled: false,
    autoUpdate: false,
    profile: instantiateStatusProfile(),
    updatedAt: new Date().toISOString(),
  };
}

function catalogEntry(catalog: StatusCatalog): Partial<TavernWorldbookEntry> {
  return {
    name: CATALOG_NAME,
    enabled: false,
    strategy: { type: "constant", keys: [] },
    content: "Echoes status catalog. Managed by the Echoes extension.",
    extra: {
      echoes: { kind: "status_catalog", version: 1, catalog } satisfies StatusCatalogMetadata,
    },
  };
}

function injectionEntry(options: {
  chatId: string;
  namespaceId: string;
  content: string;
  config: RetrievalInjectionConfig;
  createdAt: string;
}): Partial<TavernWorldbookEntry> {
  const now = new Date().toISOString();
  return {
    name: INJECTION_NAME,
    enabled: Boolean(options.content.trim()),
    strategy: { type: "constant", keys: [] },
    position: {
      type: options.config.position === "before_character"
        ? "before_character_definition"
        : options.config.position === "after_character"
          ? "after_character_definition"
          : "at_depth",
      role: options.config.role,
      depth: options.config.depth,
      order: options.config.order,
    },
    content: options.content,
    probability: 100,
    extra: {
      echoes: {
        kind: "status_injection",
        version: 1,
        chatId: options.chatId,
        namespaceId: options.namespaceId,
        createdAt: options.createdAt,
        updatedAt: now,
      } satisfies StatusInjectionMetadata,
    },
  };
}

function readState(worldbookName: string, entries: TavernWorldbookEntry[]): StatusWorldbookState | null {
  const entry = entries.find((candidate) => catalogMetadata(candidate));
  if (!entry) return null;
  return {
    worldbookName,
    catalog: statusCatalogSchema.parse(catalogMetadata(entry)!.catalog),
  };
}

function ownedChatId(entries: TavernWorldbookEntry[]): string | null {
  for (const entry of entries) {
    const value = entry.extra?.echoes as {
      kind?: unknown;
      catalog?: { chatId?: unknown };
    } | undefined;
    if (["catalog", "summary_catalog", "status_catalog"].includes(String(value?.kind))
      && typeof value?.catalog?.chatId === "string") return value.catalog.chatId;
  }
  return null;
}

export class StatusWorldbookStore {
  async load(): Promise<StatusWorldbookState> {
    const chatId = SillyTavern.getContext().chatId;
    if (!chatId) throw new Error("Open a SillyTavern chat before using status memory.");
    const api = helper();
    const boundWorldbookName = api.getChatWorldbookName("current");
    return worldbookWriteCoordinator.run(boundWorldbookName ?? `chat:${chatId}`, async () => {
      if (SillyTavern.getContext().chatId !== chatId) {
        throw new Error("The active chat changed before the status operation started.");
      }
      const baseName = chatId.replace(/\.(json|jsonl)$/i, "");
      let worldbookName = boundWorldbookName;
      if (!worldbookName) {
        worldbookName = await api.getOrCreateChatWorldbook("current", `Echoes-${baseName}`);
        if (SillyTavern.getContext().chatId !== chatId) {
          throw new Error("The active chat changed while the status worldbook was being created.");
        }
      }
      let entries = await api.getWorldbook(worldbookName);
      let state = readState(worldbookName, entries);
      const owner = ownedChatId(entries);
      if ((state && state.catalog.chatId !== chatId)
        || (!state && owner && owner !== chatId)) {
        const names = new Set(api.getWorldbookNames());
        let candidate = `Echoes-${baseName}`;
        let suffix = 2;
        while (names.has(candidate)) candidate = `Echoes-${baseName}-${suffix++}`;
        await api.createWorldbook(candidate);
        if (SillyTavern.getContext().chatId !== chatId) {
          throw new Error("The active chat changed before the status worldbook could be rebound.");
        }
        await api.rebindChatWorldbook("current", candidate);
        if (SillyTavern.getContext().chatId !== chatId) {
          throw new Error("The active chat changed while the status worldbook was being rebound.");
        }
        worldbookName = candidate;
        entries = [];
        state = null;
      }
      if (!state) {
        await api.createWorldbookEntries(worldbookName, [catalogEntry(createCatalog(chatId))]);
        entries = await api.getWorldbook(worldbookName);
        state = readState(worldbookName, entries);
      }
      if (!state) throw new Error("Failed to initialize the Echoes status catalog.");
      return state;
    });
  }

  inspect(worldbookName: string): Promise<StatusWorldbookState> {
    return helper().getWorldbook(worldbookName).then((entries) => {
      const state = readState(worldbookName, entries);
      if (!state) throw new Error("The worldbook has no Echoes status catalog.");
      return state;
    });
  }

  saveConfiguration(worldbookName: string, patch: {
    enabled?: boolean;
    autoUpdate?: boolean;
    profile?: StatusProfile;
  }): Promise<StatusWorldbookState> {
    return worldbookWriteCoordinator.run(worldbookName, async () => {
      const state = await this.inspect(worldbookName);
      const catalog = statusCatalogSchema.parse({
        ...state.catalog,
        ...patch,
        updatedAt: new Date().toISOString(),
      });
      await helper().updateWorldbookWith(worldbookName, (entries) => entries.map((entry) =>
        catalogMetadata(entry) ? { ...entry, ...catalogEntry(catalog) } : entry));
      return { worldbookName, catalog };
    });
  }

  async writeInjection(
    state: StatusWorldbookState,
    content: string,
  ): Promise<void> {
    await worldbookWriteCoordinator.run(state.worldbookName, async () => {
      const api = helper();
      const entries = await api.getWorldbook(state.worldbookName);
      const existing = entries.find((candidate) => injectionMetadata(candidate));
      const createdAt = existing
        ? injectionMetadata(existing)!.createdAt
        : new Date().toISOString();
      const replacement = injectionEntry({
        chatId: state.catalog.chatId,
        namespaceId: state.catalog.namespaceId,
        content,
        config: state.catalog.profile.injection,
        createdAt,
      });
      if (existing) {
        await api.updateWorldbookWith(state.worldbookName, (current) => current.map((entry) =>
          injectionMetadata(entry) ? { ...entry, ...replacement } : entry));
      } else {
        await api.createWorldbookEntries(state.worldbookName, [replacement]);
      }
    });
  }

  async clearInjection(worldbookName: string): Promise<void> {
    await worldbookWriteCoordinator.run(worldbookName, async () => {
      await helper().updateWorldbookWith(worldbookName, (entries) => entries.map((entry) =>
        injectionMetadata(entry)
          ? { ...entry, enabled: false, content: "" }
          : entry));
    });
  }

  async cleanupStale(worldbookName: string, now = Date.now()): Promise<void> {
    await worldbookWriteCoordinator.run(worldbookName, async () => {
      await helper().updateWorldbookWith(worldbookName, (entries) => entries.map((entry) => {
        const item = injectionMetadata(entry);
        return item && entry.enabled && now - Date.parse(item.updatedAt) > STALE_MS
          ? { ...entry, enabled: false, content: "" }
          : entry;
      }));
    });
  }
}
