import type {
  CredentialMetadata,
  EmbeddingEndpointGroup,
  GenerationEndpoint,
  GenerationEndpointGroup,
  JobRecord,
  RerankEndpointSet,
  RetrievalEndpoint,
} from "../../shared/domain";
import {
  embeddingEndpointGroupSchema,
  generationEndpointGroupSchema,
  rerankEndpointSetSchema,
} from "../../shared/schemas";
import { echoesApi } from "../api/client";
import {
  applyCredentialMigration,
  getSettings,
  legacyCredentialEndpoints,
  saveSettings,
} from "../state/settings";
import { dialogShell, submitDialog } from "./dialogs";

type ApiTab = "workflows" | "generation" | "embedding" | "rerank" | "credentials";
type RetrievalKind = "embedding" | "rerank";

const TERMINAL_STATES = new Set(["succeeded", "failed", "cancelled", "ambiguous"]);

function uid(prefix: string): string {
  return `${prefix}_${crypto.randomUUID().replaceAll("-", "")}`;
}

function message(error: unknown): string {
  return error instanceof Error ? error.message : String(error);
}

function iconButton(icon: string, title: string, action: string): HTMLButtonElement {
  const button = document.createElement("button");
  button.type = "button";
  button.className = "echoes-icon-button";
  button.dataset.apiAction = action;
  button.title = title;
  button.setAttribute("aria-label", title);
  button.innerHTML = `<i class="fa-solid fa-${icon}"></i>`;
  return button;
}

function commandButton(icon: string, label: string, action: string, primary = false): HTMLButtonElement {
  const button = document.createElement("button");
  button.type = "button";
  button.className = `menu_button${primary ? " echoes-primary" : ""}`;
  button.dataset.apiAction = action;
  button.innerHTML = `<i class="fa-solid fa-${icon}"></i> ${label}`;
  return button;
}

async function waitJob<T>(job: JobRecord<T>): Promise<JobRecord<T>> {
  let current = job;
  while (!TERMINAL_STATES.has(current.status)) {
    await new Promise((resolve) => setTimeout(resolve, 500));
    current = await echoesApi.getJob<T>(job.id);
  }
  if (current.status !== "succeeded") throw new Error(current.error?.message ?? current.message);
  return current;
}

function fieldValue<T extends HTMLInputElement | HTMLSelectElement>(root: ParentNode, selector: string): string {
  return root.querySelector<T>(selector)?.value.trim() ?? "";
}

export class ApiConfigPanel {
  private tab: ApiTab = "workflows";
  private credentials: CredentialMetadata[] = [];
  private renderSequence = 0;

  constructor(private readonly root: HTMLElement) {
    this.bindEvents();
  }

  async render(tab = this.tab): Promise<void> {
    this.tab = tab;
    const sequence = ++this.renderSequence;
    const host = this.root.querySelector<HTMLElement>(".echoes-grid-host")!;
    host.innerHTML = '<div class="echoes-grid-message">正在读取 API 配置...</div>';
    this.credentials = await echoesApi.listCredentials().catch(() => []);
    if (sequence !== this.renderSequence || !this.root.classList.contains("echoes-api-view")) return;
    host.innerHTML = `
      <div class="echoes-api-page">
        <nav class="echoes-section-tabs" aria-label="API 配置分类">
          <button type="button" data-api-action="tab" data-api-tab="workflows">工作流分配</button>
          <button type="button" data-api-action="tab" data-api-tab="generation">生成模型</button>
          <button type="button" data-api-action="tab" data-api-tab="embedding">Embedding</button>
          <button type="button" data-api-action="tab" data-api-tab="rerank">Rerank</button>
          <button type="button" data-api-action="tab" data-api-tab="credentials">凭据</button>
        </nav>
        <div class="echoes-api-content" data-api-content></div>
      </div>`;
    host.querySelectorAll<HTMLElement>("[data-api-tab]").forEach((button) => {
      button.classList.toggle("active", button.dataset.apiTab === this.tab);
    });
    this.renderTab();
  }

  private bindEvents(): void {
    this.root.addEventListener("click", (event) => {
      const target = (event.target as HTMLElement).closest<HTMLElement>("[data-api-action]");
      if (!target) return;
      void this.handleAction(target.dataset.apiAction ?? "", target).catch((error) => {
        toastr.error(message(error), "Echoes API配置");
      });
    });
    this.root.addEventListener("change", (event) => {
      const target = event.target as HTMLInputElement | HTMLSelectElement;
      if (target.matches("[data-api-workflow]")) this.saveWorkflowBindings();
      else if (target.matches("[data-api-generation-toggle]")) this.toggleGenerationEndpoint(target as HTMLInputElement);
      else if (target.matches("[data-api-retrieval-toggle]")) this.toggleRetrievalEndpoint(target as HTMLInputElement);
    });
    this.root.addEventListener("submit", (event) => {
      const form = event.target as HTMLFormElement;
      if (!form.matches("[data-api-credential-form]")) return;
      event.preventDefault();
      void this.addCredential(form).catch((error) => toastr.error(message(error), "Echoes 凭据"));
    });
  }

  private async handleAction(action: string, target: HTMLElement): Promise<void> {
    if (action === "tab") await this.render(target.dataset.apiTab as ApiTab);
    else if (action === "refresh") await this.render();
    else if (action === "add-generation-group") await this.addGenerationGroup();
    else if (action === "delete-generation-group") this.deleteGenerationGroup(target.dataset.groupId ?? "");
    else if (action === "add-generation-endpoint") await this.editGenerationEndpoint(target.dataset.groupId ?? "");
    else if (action === "edit-generation-endpoint") await this.editGenerationEndpoint(target.dataset.groupId ?? "", target.dataset.endpointId);
    else if (action === "delete-generation-endpoint") this.deleteGenerationEndpoint(target.dataset.groupId ?? "", target.dataset.endpointId ?? "");
    else if (action === "generation-up") this.moveGenerationEndpoint(target.dataset.groupId ?? "", target.dataset.endpointId ?? "", -1);
    else if (action === "generation-down") this.moveGenerationEndpoint(target.dataset.groupId ?? "", target.dataset.endpointId ?? "", 1);
    else if (action === "test-generation") await this.testGenerationEndpoint(target.dataset.groupId ?? "", target.dataset.endpointId ?? "");
    else if (action === "add-retrieval-group") await this.editRetrievalGroup(target.dataset.kind as RetrievalKind);
    else if (action === "edit-retrieval-group") await this.editRetrievalGroup(target.dataset.kind as RetrievalKind, target.dataset.groupId);
    else if (action === "delete-retrieval-group") this.deleteRetrievalGroup(target.dataset.kind as RetrievalKind, target.dataset.groupId ?? "");
    else if (action === "test-retrieval") await this.testRetrievalEndpoint(target);
    else if (action === "delete-credential") await this.deleteCredential(target.dataset.id ?? "");
    else if (action === "migrate-credentials") await this.migrateCredentials();
  }

  private renderTab(): void {
    if (this.tab === "workflows") this.renderWorkflows();
    else if (this.tab === "generation") this.renderGenerationGroups();
    else if (this.tab === "embedding") this.renderRetrievalGroups("embedding");
    else if (this.tab === "rerank") this.renderRetrievalGroups("rerank");
    else this.renderCredentials();
  }

  private content(): HTMLElement {
    return this.root.querySelector<HTMLElement>("[data-api-content]")!;
  }

  private renderWorkflows(): void {
    const settings = getSettings();
    const host = this.content();
    host.innerHTML = `
      <section class="echoes-settings-section">
        <div class="echoes-section-heading"><div><h2>工作流分配</h2><span>所有模型、端点组和故障策略统一在此绑定</span></div></div>
        <div class="echoes-workflow-grid">
          <div class="echoes-workflow-row"><strong>结构化记忆提取</strong><label>生成端点组<select data-api-workflow="extractionGroup"></select></label><label>故障策略<select data-api-workflow="extractionPolicy"></select></label></div>
          <div class="echoes-workflow-row"><strong>总结记忆生成</strong><label>生成端点组<select data-api-workflow="summaryGroup"></select></label><label>故障策略<select data-api-workflow="summaryPolicy"></select></label></div>
          <div class="echoes-workflow-row"><strong>总结向量化</strong><label>Embedding 组<select data-api-workflow="summaryEmbedding"><option value="">暂不同步向量</option></select></label><span></span></div>
          <div class="echoes-workflow-row"><strong>总结召回重排序</strong><label>Rerank 组<select data-api-workflow="recallRerank"><option value="">不使用 Rerank</option></select></label><span></span></div>
          <div class="echoes-workflow-row"><strong>状态记忆更新</strong><label>生成端点组<select data-api-workflow="statusGroup"></select></label><label>故障策略<select data-api-workflow="statusPolicy"></select></label></div>
          <div class="echoes-workflow-row"><strong>通用检索调用</strong><label>故障策略<select data-api-workflow="retrievalPolicy"></select></label><span></span></div>
        </div>
        <div class="echoes-api-binding-status" data-api-binding-status></div>
      </section>`;
    const groupOptions = (select: HTMLSelectElement, current: string) => {
      select.add(new Option("未选择", ""));
      settings.generationGroups.forEach((group) => select.add(new Option(group.name, group.id)));
      select.value = current;
    };
    groupOptions(host.querySelector("[data-api-workflow=extractionGroup]")!, settings.generationWorkflows.extraction.groupId);
    groupOptions(host.querySelector("[data-api-workflow=summaryGroup]")!, settings.generationWorkflows.summary.groupId);
    groupOptions(host.querySelector("[data-api-workflow=statusGroup]")!, settings.generationWorkflows.status.groupId);
    const policyOptions = (select: HTMLSelectElement, current: string) => {
      select.add(new Option("不确定时确认", "confirm_ambiguous"));
      select.add(new Option("始终自动切换", "always"));
      select.add(new Option("仅明确失败切换", "definitive_only"));
      select.value = current;
    };
    policyOptions(host.querySelector("[data-api-workflow=extractionPolicy]")!, settings.generationWorkflows.extraction.failoverPolicy);
    policyOptions(host.querySelector("[data-api-workflow=summaryPolicy]")!, settings.generationWorkflows.summary.failoverPolicy);
    policyOptions(host.querySelector("[data-api-workflow=statusPolicy]")!, settings.generationWorkflows.status.failoverPolicy);
    policyOptions(host.querySelector("[data-api-workflow=retrievalPolicy]")!, settings.retrieval.failoverPolicy);
    const embedding = host.querySelector<HTMLSelectElement>("[data-api-workflow=summaryEmbedding]")!;
    settings.retrieval.embeddingGroups.forEach((group) => embedding.add(new Option(group.name, group.id)));
    embedding.value = settings.summary.embeddingGroupId;
    const rerank = host.querySelector<HTMLSelectElement>("[data-api-workflow=recallRerank]")!;
    settings.retrieval.rerankSets.forEach((group) => rerank.add(new Option(group.name, group.id)));
    rerank.value = settings.retrieval.recall.rerankSetId;
    this.renderBindingStatus();
  }

  private renderBindingStatus(): void {
    const host = this.root.querySelector<HTMLElement>("[data-api-binding-status]");
    if (!host) return;
    const settings = getSettings();
    const generationIds = new Set(settings.generationGroups.map((group) => group.id));
    const embeddingIds = new Set(settings.retrieval.embeddingGroups.map((group) => group.id));
    const rerankIds = new Set(settings.retrieval.rerankSets.map((group) => group.id));
    const states = [
      ["结构化记忆", generationIds.has(settings.generationWorkflows.extraction.groupId)],
      ["总结生成", generationIds.has(settings.generationWorkflows.summary.groupId)],
      ["总结向量", !settings.summary.embeddingGroupId || embeddingIds.has(settings.summary.embeddingGroupId)],
      ["总结重排序", !settings.retrieval.recall.rerankSetId || rerankIds.has(settings.retrieval.recall.rerankSetId)],
      ["状态更新", generationIds.has(settings.generationWorkflows.status.groupId)],
    ] as const;
    host.replaceChildren(...states.map(([label, ready]) => {
      const item = document.createElement("span");
      item.dataset.state = ready ? "ready" : "missing";
      item.innerHTML = `<i class="fa-solid fa-${ready ? "circle-check" : "triangle-exclamation"}"></i> ${label}：${ready ? "已配置" : "未配置"}`;
      return item;
    }));
  }

  private saveWorkflowBindings(): void {
    const settings = getSettings();
    const value = (key: string) => this.root.querySelector<HTMLSelectElement>(`[data-api-workflow=${key}]`)?.value ?? "";
    settings.generationWorkflows.extraction = { groupId: value("extractionGroup"), failoverPolicy: value("extractionPolicy") as typeof settings.generationWorkflows.extraction.failoverPolicy };
    settings.generationWorkflows.summary = { groupId: value("summaryGroup"), failoverPolicy: value("summaryPolicy") as typeof settings.generationWorkflows.summary.failoverPolicy };
    settings.generationWorkflows.status = { groupId: value("statusGroup"), failoverPolicy: value("statusPolicy") as typeof settings.generationWorkflows.status.failoverPolicy };
    settings.summary.embeddingGroupId = value("summaryEmbedding");
    settings.retrieval.recall.rerankSetId = value("recallRerank");
    settings.retrieval.failoverPolicy = value("retrievalPolicy") as typeof settings.retrieval.failoverPolicy;
    saveSettings(settings);
    this.renderBindingStatus();
  }

  private renderGenerationGroups(): void {
    const host = this.content();
    host.innerHTML = '<section class="echoes-settings-section"><div class="echoes-section-heading"><div><h2>生成模型端点组</h2><span>供结构化提取、总结生成和状态更新复用</span></div><div data-api-section-actions></div></div><div data-generation-groups></div></section>';
    host.querySelector<HTMLElement>("[data-api-section-actions]")!.append(commandButton("plus", "新增端点组", "add-generation-group", true));
    const list = host.querySelector<HTMLElement>("[data-generation-groups]")!;
    const groups = getSettings().generationGroups;
    if (groups.length === 0) list.innerHTML = '<p class="echoes-empty-note">尚未配置生成端点组。</p>';
    groups.forEach((group) => list.append(this.generationGroup(group)));
  }

  private generationGroup(group: GenerationEndpointGroup): HTMLElement {
    const section = document.createElement("article");
    section.className = "echoes-api-group";
    const header = document.createElement("header");
    header.innerHTML = `<div><strong></strong><small>${group.endpoints.length} 个端点</small></div><div data-actions></div>`;
    header.querySelector("strong")!.textContent = group.name;
    const add = commandButton("plus", "添加端点", "add-generation-endpoint");
    add.dataset.groupId = group.id;
    const remove = iconButton("trash", "删除端点组", "delete-generation-group");
    remove.dataset.groupId = group.id;
    header.querySelector<HTMLElement>("[data-actions]")!.append(add, remove);
    section.append(header);
    const table = document.createElement("table");
    table.className = "echoes-data-table echoes-endpoint-table";
    table.innerHTML = "<thead><tr><th>启用</th><th>顺序</th><th>名称</th><th>模型</th><th>地址</th><th>操作</th></tr></thead>";
    const body = document.createElement("tbody");
    const endpoints = [...group.endpoints].sort((a, b) => a.order - b.order);
    endpoints.forEach((endpoint, index) => {
      const row = document.createElement("tr");
      const enabledCell = document.createElement("td");
      const enabled = document.createElement("input");
      enabled.type = "checkbox";
      enabled.checked = endpoint.enabled;
      enabled.dataset.apiGenerationToggle = endpoint.id;
      enabled.dataset.groupId = group.id;
      enabled.setAttribute("aria-label", `启用${endpoint.name}`);
      enabledCell.append(enabled);
      row.append(enabledCell);
      [String(index + 1), endpoint.name, endpoint.model, endpoint.baseUrl].forEach((value) => {
        const cell = document.createElement("td");
        cell.textContent = value;
        cell.title = value;
        row.append(cell);
      });
      const actions = document.createElement("td");
      actions.className = "echoes-row-actions";
      for (const [icon, title, action] of [
        ["arrow-up", "上移", "generation-up"],
        ["arrow-down", "下移", "generation-down"],
        ["vial", "测试", "test-generation"],
        ["pen", "编辑", "edit-generation-endpoint"],
        ["trash", "删除", "delete-generation-endpoint"],
      ]) {
        const control = iconButton(icon!, title!, action!);
        control.dataset.groupId = group.id;
        control.dataset.endpointId = endpoint.id;
        if (action === "generation-up") control.disabled = index === 0;
        if (action === "generation-down") control.disabled = index === endpoints.length - 1;
        actions.append(control);
      }
      row.append(actions);
      body.append(row);
    });
    table.append(body);
    section.append(table);
    return section;
  }

  private async addGenerationGroup(): Promise<void> {
    const dialog = dialogShell("新增生成端点组");
    dialog.querySelector<HTMLElement>(".echoes-dialog-body")!.innerHTML = '<div class="echoes-form-grid"><label>名称<input name="name" required maxlength="120"></label></div>';
    const saved = await submitDialog(dialog, () => {
      const name = fieldValue<HTMLInputElement>(dialog, "[name=name]");
      if (!name) throw new Error("端点组名称不能为空。");
      return { id: uid("generation_group"), name, endpoints: [] } satisfies GenerationEndpointGroup;
    }, { errorTitle: "生成端点组无效" });
    if (!saved) return;
    const settings = getSettings();
    settings.generationGroups.push(saved);
    saveSettings(settings);
    await this.render("generation");
  }

  private async editGenerationEndpoint(groupId: string, endpointId?: string): Promise<void> {
    const settings = getSettings();
    const group = settings.generationGroups.find((item) => item.id === groupId);
    const current = group?.endpoints.find((item) => item.id === endpointId);
    if (!group) throw new Error("生成端点组不存在。");
    const dialog = dialogShell(current ? "编辑生成端点" : "添加生成端点");
    const body = dialog.querySelector<HTMLElement>(".echoes-dialog-body")!;
    body.innerHTML = `<div class="echoes-form-grid"><label>名称<input name="name" required></label><label class="echoes-form-span">API 地址<input name="baseUrl" type="url" required></label><label>模型<input name="model" required></label><label>服务端凭据<select name="credentialId"><option value="">无凭据</option></select></label><label>超时（秒）<input name="timeout" type="number" min="10" max="1800"></label><label>温度<input name="temperature" type="number" min="0" max="2" step="0.1"></label><label class="echoes-check"><input name="streaming" type="checkbox">流式</label><label class="echoes-check"><input name="jsonMode" type="checkbox">JSON 模式</label><label class="echoes-check"><input name="enabled" type="checkbox">启用</label></div>`;
    const credential = body.querySelector<HTMLSelectElement>("[name=credentialId]")!;
    this.credentials.forEach((item) => credential.add(new Option(item.name, item.id)));
    if (current?.credentialId && !this.credentials.some((item) => item.id === current.credentialId)) credential.add(new Option(`缺失：${current.credentialId}`, current.credentialId));
    const set = (name: string, value: string) => { body.querySelector<HTMLInputElement>(`[name=${name}]`)!.value = value; };
    set("name", current?.name ?? "新端点");
    set("baseUrl", current?.baseUrl ?? "");
    set("model", current?.model ?? "");
    set("timeout", String((current?.timeoutMs ?? 300_000) / 1_000));
    set("temperature", String(current?.temperature ?? 0.1));
    credential.value = current?.credentialId ?? "";
    body.querySelector<HTMLInputElement>("[name=streaming]")!.checked = current?.streaming ?? true;
    body.querySelector<HTMLInputElement>("[name=jsonMode]")!.checked = current?.jsonMode ?? true;
    body.querySelector<HTMLInputElement>("[name=enabled]")!.checked = current?.enabled ?? true;
    const endpoint = await submitDialog(dialog, () => {
      const credentialId = credential.value;
      return {
        id: current?.id ?? uid("generation_endpoint"),
        name: fieldValue<HTMLInputElement>(body, "[name=name]"),
        baseUrl: fieldValue<HTMLInputElement>(body, "[name=baseUrl]"),
        model: fieldValue<HTMLInputElement>(body, "[name=model]"),
        ...(credentialId ? { credentialId } : current?.apiKey ? { apiKey: current.apiKey } : {}),
        timeoutMs: Number(fieldValue<HTMLInputElement>(body, "[name=timeout]")) * 1_000,
        temperature: Number(fieldValue<HTMLInputElement>(body, "[name=temperature]")),
        streaming: body.querySelector<HTMLInputElement>("[name=streaming]")!.checked,
        jsonMode: body.querySelector<HTMLInputElement>("[name=jsonMode]")!.checked,
        enabled: body.querySelector<HTMLInputElement>("[name=enabled]")!.checked,
        order: current?.order ?? group.endpoints.length,
      } satisfies GenerationEndpoint;
    }, { errorTitle: "生成端点无效" });
    if (!endpoint) return;
    const parsed = generationEndpointGroupSchema.parse({ ...group, endpoints: current ? group.endpoints.map((item) => item.id === current.id ? endpoint : item) : [...group.endpoints, endpoint] });
    settings.generationGroups[settings.generationGroups.findIndex((item) => item.id === group.id)] = parsed;
    saveSettings(settings);
    await this.render("generation");
  }

  private deleteGenerationGroup(groupId: string): void {
    if (!confirm("删除该生成端点组？所有引用它的工作流会变为未配置。")) return;
    const settings = getSettings();
    settings.generationGroups = settings.generationGroups.filter((group) => group.id !== groupId);
    for (const workflow of Object.values(settings.generationWorkflows)) if (workflow.groupId === groupId) workflow.groupId = "";
    saveSettings(settings);
    void this.render("generation");
  }

  private deleteGenerationEndpoint(groupId: string, endpointId: string): void {
    if (!confirm("删除该生成端点？")) return;
    const settings = getSettings();
    const group = settings.generationGroups.find((item) => item.id === groupId);
    if (!group) return;
    group.endpoints = group.endpoints.filter((item) => item.id !== endpointId);
    group.endpoints.forEach((item, index) => { item.order = index; });
    saveSettings(settings);
    void this.render("generation");
  }

  private moveGenerationEndpoint(groupId: string, endpointId: string, offset: number): void {
    const settings = getSettings();
    const group = settings.generationGroups.find((item) => item.id === groupId);
    if (!group) return;
    group.endpoints.sort((a, b) => a.order - b.order);
    const index = group.endpoints.findIndex((item) => item.id === endpointId);
    const target = index + offset;
    if (index < 0 || target < 0 || target >= group.endpoints.length) return;
    const [endpoint] = group.endpoints.splice(index, 1);
    group.endpoints.splice(target, 0, endpoint!);
    group.endpoints.forEach((item, position) => { item.order = position; });
    saveSettings(settings);
    void this.render("generation");
  }

  private toggleGenerationEndpoint(input: HTMLInputElement): void {
    const settings = getSettings();
    const endpoint = settings.generationGroups.find((group) => group.id === input.dataset.groupId)?.endpoints.find((item) => item.id === input.dataset.apiGenerationToggle);
    if (!endpoint) return;
    endpoint.enabled = input.checked;
    saveSettings(settings);
  }

  private async testGenerationEndpoint(groupId: string, endpointId: string): Promise<void> {
    const endpoint = getSettings().generationGroups.find((group) => group.id === groupId)?.endpoints.find((item) => item.id === endpointId);
    if (!endpoint) throw new Error("生成端点不存在。");
    const completed = await waitJob(await echoesApi.testGenerationEndpoint(endpoint));
    toastr.success(`连接成功：${completed.result?.latencyMs ?? 0} ms`, "生成端点");
  }

  private renderRetrievalGroups(kind: RetrievalKind): void {
    const settings = getSettings();
    const groups = kind === "embedding" ? settings.retrieval.embeddingGroups : settings.retrieval.rerankSets;
    const title = kind === "embedding" ? "Embedding 端点组" : "Rerank 端点组";
    const host = this.content();
    host.innerHTML = `<section class="echoes-settings-section"><div class="echoes-section-heading"><div><h2>${title}</h2><span>${kind === "embedding" ? "嵌入空间和维度必须与模型保持一致" : "用于总结召回结果重排序"}</span></div><div data-api-section-actions></div></div><div data-retrieval-groups></div></section>`;
    const add = commandButton("plus", `新增${kind === "embedding" ? "嵌入" : "重排序"}组`, "add-retrieval-group", true);
    add.dataset.kind = kind;
    host.querySelector<HTMLElement>("[data-api-section-actions]")!.append(add);
    const list = host.querySelector<HTMLElement>("[data-retrieval-groups]")!;
    if (groups.length === 0) list.innerHTML = `<p class="echoes-empty-note">尚未配置${title}。</p>`;
    groups.forEach((group) => list.append(this.retrievalGroup(kind, group)));
  }

  private retrievalGroup(kind: RetrievalKind, group: EmbeddingEndpointGroup | RerankEndpointSet): HTMLElement {
    const section = document.createElement("article");
    section.className = "echoes-api-group";
    const header = document.createElement("header");
    const detail = kind === "embedding" ? `${(group as EmbeddingEndpointGroup).embeddingSpaceId} · ${(group as EmbeddingEndpointGroup).dimensions} 维` : `${group.endpoints.length} 个端点`;
    header.innerHTML = "<div><strong></strong><small></small></div><div data-actions></div>";
    header.querySelector("small")!.textContent = detail;
    header.querySelector("strong")!.textContent = group.name;
    const edit = iconButton("pen", "编辑端点组", "edit-retrieval-group");
    const remove = iconButton("trash", "删除端点组", "delete-retrieval-group");
    for (const control of [edit, remove]) { control.dataset.kind = kind; control.dataset.groupId = group.id; }
    header.querySelector<HTMLElement>("[data-actions]")!.append(edit, remove);
    section.append(header);
    const table = document.createElement("table");
    table.className = "echoes-data-table echoes-endpoint-table";
    table.innerHTML = "<thead><tr><th>启用</th><th>顺序</th><th>名称</th><th>模型</th><th>地址</th><th>测试</th></tr></thead>";
    const body = document.createElement("tbody");
    [...group.endpoints].sort((a, b) => a.order - b.order).forEach((endpoint, index) => {
      const row = document.createElement("tr");
      const enabledCell = document.createElement("td");
      const enabled = document.createElement("input");
      enabled.type = "checkbox";
      enabled.checked = endpoint.enabled;
      enabled.dataset.apiRetrievalToggle = endpoint.id;
      enabled.dataset.kind = kind;
      enabled.dataset.groupId = group.id;
      enabled.setAttribute("aria-label", `启用${endpoint.name}`);
      enabledCell.append(enabled);
      row.append(enabledCell);
      [String(index + 1), endpoint.name, endpoint.model, endpoint.baseUrl].forEach((value) => { const cell = document.createElement("td"); cell.textContent = value; cell.title = value; row.append(cell); });
      const testCell = document.createElement("td");
      const test = iconButton("vial", "测试端点", "test-retrieval");
      test.dataset.kind = kind;
      test.dataset.groupId = group.id;
      test.dataset.endpointId = endpoint.id;
      testCell.append(test);
      row.append(testCell);
      body.append(row);
    });
    table.append(body);
    section.append(table);
    return section;
  }

  private async editRetrievalGroup(kind: RetrievalKind, groupId?: string): Promise<void> {
    const settings = getSettings();
    const current = (kind === "embedding" ? settings.retrieval.embeddingGroups : settings.retrieval.rerankSets).find((group) => group.id === groupId);
    const saved = await this.retrievalGroupDialog(kind, current);
    if (!saved) return;
    if (kind === "embedding") {
      const parsed = embeddingEndpointGroupSchema.parse(saved);
      const index = settings.retrieval.embeddingGroups.findIndex((group) => group.id === parsed.id);
      if (index >= 0) settings.retrieval.embeddingGroups[index] = parsed;
      else settings.retrieval.embeddingGroups.push(parsed);
    } else {
      const parsed = rerankEndpointSetSchema.parse(saved);
      const index = settings.retrieval.rerankSets.findIndex((group) => group.id === parsed.id);
      if (index >= 0) settings.retrieval.rerankSets[index] = parsed;
      else settings.retrieval.rerankSets.push(parsed);
    }
    saveSettings(settings);
    await this.render(kind);
  }

  private async retrievalGroupDialog(kind: RetrievalKind, current?: EmbeddingEndpointGroup | RerankEndpointSet): Promise<EmbeddingEndpointGroup | RerankEndpointSet | null> {
    const dialog = dialogShell(kind === "embedding" ? "Embedding 端点组" : "Rerank 端点组");
    const body = dialog.querySelector<HTMLElement>(".echoes-dialog-body")!;
    body.innerHTML = `<div class="echoes-form-grid"><label>组名<input name="name" required maxlength="120"></label><label>组 ID<input name="id" required pattern="[a-zA-Z][a-zA-Z0-9_-]*"></label>${kind === "embedding" ? '<label>嵌入空间 ID<input name="embeddingSpaceId" required pattern="[a-zA-Z][a-zA-Z0-9_-]*"></label><label>维度<input name="dimensions" type="number" min="1" max="65536" required></label>' : ""}</div><div class="echoes-section-heading"><h3>端点</h3><button type="button" class="menu_button" data-add-retrieval-endpoint><i class="fa-solid fa-plus"></i> 添加端点</button></div><div class="echoes-endpoint-editor" data-endpoint-editor></div>`;
    body.querySelector<HTMLInputElement>("[name=name]")!.value = current?.name ?? "";
    body.querySelector<HTMLInputElement>("[name=id]")!.value = current?.id ?? uid(kind);
    if (kind === "embedding") {
      const embedding = current as EmbeddingEndpointGroup | undefined;
      body.querySelector<HTMLInputElement>("[name=embeddingSpaceId]")!.value = embedding?.embeddingSpaceId ?? uid("space");
      body.querySelector<HTMLInputElement>("[name=dimensions]")!.value = String(embedding?.dimensions ?? 1536);
    }
    const rows = structuredClone(current?.endpoints ?? []);
    const editor = body.querySelector<HTMLElement>("[data-endpoint-editor]")!;
    const redraw = () => this.renderRetrievalEndpointEditor(editor, rows, redraw);
    redraw();
    body.querySelector("[data-add-retrieval-endpoint]")!.addEventListener("click", () => {
      this.syncRetrievalEndpointEditor(editor, rows);
      rows.push({ id: uid("endpoint"), name: `端点 ${rows.length + 1}`, baseUrl: "https://", model: "", timeoutMs: 30_000, enabled: true, order: rows.length });
      redraw();
    });
    return submitDialog(dialog, () => {
      this.syncRetrievalEndpointEditor(editor, rows);
      if (rows.length === 0) throw new Error("至少需要一个端点。");
      const base = { id: fieldValue<HTMLInputElement>(body, "[name=id]"), name: fieldValue<HTMLInputElement>(body, "[name=name]"), endpoints: rows.map((endpoint, index) => ({ ...endpoint, order: index })) };
      return kind === "embedding" ? { ...base, embeddingSpaceId: fieldValue<HTMLInputElement>(body, "[name=embeddingSpaceId]"), dimensions: Number(fieldValue<HTMLInputElement>(body, "[name=dimensions]")) } : base;
    }, { errorTitle: `${kind === "embedding" ? "Embedding" : "Rerank"} 端点组无效` });
  }

  private renderRetrievalEndpointEditor(host: HTMLElement, rows: RetrievalEndpoint[], redraw: () => void): void {
    host.replaceChildren();
    rows.forEach((endpoint, index) => {
      const row = document.createElement("div");
      row.className = "echoes-endpoint-editor-row";
      row.dataset.index = String(index);
      row.innerHTML = '<label>名称<input data-field="name" required></label><label>地址<input data-field="baseUrl" type="url" required></label><label>模型<input data-field="model" required></label><label>服务端凭据<select data-field="credentialId"><option value="">无凭据</option></select></label><label>超时（秒）<input data-field="timeout" type="number" min="1" max="600" required></label><label class="echoes-check"><input data-field="enabled" type="checkbox">启用</label><div class="echoes-endpoint-editor-actions"></div>';
      row.querySelector<HTMLInputElement>("[data-field=name]")!.value = endpoint.name;
      row.querySelector<HTMLInputElement>("[data-field=baseUrl]")!.value = endpoint.baseUrl;
      row.querySelector<HTMLInputElement>("[data-field=model]")!.value = endpoint.model;
      const credential = row.querySelector<HTMLSelectElement>("[data-field=credentialId]")!;
      this.credentials.forEach((item) => credential.add(new Option(item.name, item.id)));
      if (endpoint.credentialId && !this.credentials.some((item) => item.id === endpoint.credentialId)) credential.add(new Option(`缺失：${endpoint.credentialId}`, endpoint.credentialId));
      credential.value = endpoint.credentialId ?? "";
      row.querySelector<HTMLInputElement>("[data-field=timeout]")!.value = String(endpoint.timeoutMs / 1_000);
      row.querySelector<HTMLInputElement>("[data-field=enabled]")!.checked = endpoint.enabled;
      const up = iconButton("arrow-up", "上移", "noop");
      const down = iconButton("arrow-down", "下移", "noop");
      const remove = iconButton("trash", "删除", "noop");
      delete up.dataset.apiAction; delete down.dataset.apiAction; delete remove.dataset.apiAction;
      up.disabled = index === 0; down.disabled = index === rows.length - 1;
      up.addEventListener("click", () => { this.syncRetrievalEndpointEditor(host, rows); [rows[index - 1], rows[index]] = [rows[index]!, rows[index - 1]!]; redraw(); });
      down.addEventListener("click", () => { this.syncRetrievalEndpointEditor(host, rows); [rows[index], rows[index + 1]] = [rows[index + 1]!, rows[index]!]; redraw(); });
      remove.addEventListener("click", () => { this.syncRetrievalEndpointEditor(host, rows); rows.splice(index, 1); redraw(); });
      row.querySelector<HTMLElement>(".echoes-endpoint-editor-actions")!.append(up, down, remove);
      host.append(row);
    });
  }

  private syncRetrievalEndpointEditor(host: HTMLElement, rows: RetrievalEndpoint[]): void {
    host.querySelectorAll<HTMLElement>(".echoes-endpoint-editor-row").forEach((row) => {
      const endpoint = rows[Number(row.dataset.index)];
      if (!endpoint) return;
      endpoint.name = fieldValue<HTMLInputElement>(row, "[data-field=name]");
      endpoint.baseUrl = fieldValue<HTMLInputElement>(row, "[data-field=baseUrl]");
      endpoint.model = fieldValue<HTMLInputElement>(row, "[data-field=model]");
      const credentialId = fieldValue<HTMLSelectElement>(row, "[data-field=credentialId]");
      if (credentialId) { endpoint.credentialId = credentialId; delete endpoint.apiKey; } else delete endpoint.credentialId;
      endpoint.timeoutMs = Number(fieldValue<HTMLInputElement>(row, "[data-field=timeout]")) * 1_000;
      endpoint.enabled = row.querySelector<HTMLInputElement>("[data-field=enabled]")!.checked;
    });
  }

  private deleteRetrievalGroup(kind: RetrievalKind, groupId: string): void {
    if (!confirm("删除该端点组？所有引用它的工作流会变为未配置。")) return;
    const settings = getSettings();
    if (kind === "embedding") {
      settings.retrieval.embeddingGroups = settings.retrieval.embeddingGroups.filter((group) => group.id !== groupId);
      if (settings.summary.embeddingGroupId === groupId) settings.summary.embeddingGroupId = "";
    } else {
      settings.retrieval.rerankSets = settings.retrieval.rerankSets.filter((group) => group.id !== groupId);
      if (settings.retrieval.recall.rerankSetId === groupId) settings.retrieval.recall.rerankSetId = "";
    }
    saveSettings(settings);
    void this.render(kind);
  }

  private toggleRetrievalEndpoint(input: HTMLInputElement): void {
    const settings = getSettings();
    const groups = input.dataset.kind === "rerank" ? settings.retrieval.rerankSets : settings.retrieval.embeddingGroups;
    const endpoint = groups.find((group) => group.id === input.dataset.groupId)?.endpoints.find((item) => item.id === input.dataset.apiRetrievalToggle);
    if (!endpoint) return;
    endpoint.enabled = input.checked;
    saveSettings(settings);
  }

  private async testRetrievalEndpoint(target: HTMLElement): Promise<void> {
    const settings = getSettings();
    const kind = target.dataset.kind === "rerank" ? "rerank" : "embedding";
    const groups = kind === "rerank" ? settings.retrieval.rerankSets : settings.retrieval.embeddingGroups;
    const group = groups.find((item) => item.id === target.dataset.groupId);
    const endpoint = group?.endpoints.find((item) => item.id === target.dataset.endpointId);
    if (!group || !endpoint) throw new Error("端点配置不存在。");
    const completed = await waitJob(await echoesApi.testRetrievalEndpoint({ kind, endpoint, ...(kind === "embedding" ? { expectedDimensions: (group as EmbeddingEndpointGroup).dimensions } : {}) }));
    toastr.success(`${completed.result?.latencyMs ?? 0} ms${completed.result?.dimensions ? ` · ${completed.result.dimensions} 维` : ""}`, "端点测试完成");
  }

  private renderCredentials(): void {
    const legacy = legacyCredentialEndpoints();
    const host = this.content();
    host.innerHTML = `<section class="echoes-settings-section"><div class="echoes-section-heading"><div><h2>服务端凭据</h2><span>密钥不会回传到浏览器；维护页中的凭据入口暂时保留</span></div><button type="button" class="echoes-icon-button" data-api-action="refresh" title="刷新" aria-label="刷新"><i class="fa-solid fa-rotate"></i></button></div>${legacy.length ? `<div class="echoes-warning-band"><strong>检测到 ${legacy.length} 个前端明文密钥</strong><button type="button" class="menu_button echoes-primary" data-api-action="migrate-credentials">原子迁移</button></div>` : ""}<form class="echoes-inline-form" data-api-credential-form><input name="name" placeholder="凭据名称" required maxlength="120"><input name="secret" type="password" placeholder="API 密钥" required autocomplete="new-password"><button type="submit" class="menu_button echoes-primary"><i class="fa-solid fa-key"></i> 添加凭据</button></form><div class="echoes-credential-list" data-credential-list></div></section>`;
    const list = host.querySelector<HTMLElement>("[data-credential-list]")!;
    if (this.credentials.length === 0) list.innerHTML = '<p class="echoes-empty-note">尚无服务端凭据。</p>';
    this.credentials.forEach((credential) => {
      const row = document.createElement("div");
      row.className = "echoes-credential-row";
      const meta = document.createElement("span");
      const name = document.createElement("strong");
      name.textContent = credential.name;
      const id = document.createElement("small");
      id.textContent = credential.id;
      meta.append(name, id);
      const time = document.createElement("time");
      time.textContent = new Date(credential.updatedAt).toLocaleString();
      const remove = iconButton("trash", "删除凭据", "delete-credential");
      remove.dataset.id = credential.id;
      row.append(meta, time, remove);
      list.append(row);
    });
  }

  private async addCredential(form: HTMLFormElement): Promise<void> {
    const name = fieldValue<HTMLInputElement>(form, "[name=name]");
    const secret = form.querySelector<HTMLInputElement>("[name=secret]")!.value;
    if (!name || !secret) throw new Error("凭据名称和密钥不能为空。");
    await echoesApi.createCredential({ name, secret });
    form.reset();
    await this.render("credentials");
  }

  private async deleteCredential(id: string): Promise<void> {
    if (!confirm("删除该服务端凭据？引用它的端点将无法调用。")) return;
    await echoesApi.deleteCredential(id);
    await this.render("credentials");
  }

  private async migrateCredentials(): Promise<void> {
    const legacy = legacyCredentialEndpoints();
    if (legacy.length === 0 || !confirm(`将 ${legacy.length} 个明文密钥迁移到服务端凭据库？`)) return;
    const inputs = legacy.map((endpoint) => ({ id: `credential_${crypto.randomUUID().replaceAll("-", "")}`, name: `${endpoint.endpointName} (${endpoint.kind})`, secret: endpoint.apiKey }));
    const previous = structuredClone(getSettings());
    const created = await echoesApi.migrateCredentials(inputs);
    try {
      if (created.length !== inputs.length || created.some((credential, index) => credential.id !== inputs[index]!.id)) throw new Error("服务端未能验证全部迁移凭据。");
      applyCredentialMigration(legacy.map((endpoint, index) => ({ kind: endpoint.kind, containerId: endpoint.containerId, endpointId: endpoint.endpointId, credentialId: created[index]!.id })));
    } catch (error) {
      saveSettings(previous);
      await Promise.allSettled(created.map((credential) => echoesApi.deleteCredential(credential.id)));
      throw error;
    }
    await this.render("credentials");
  }
}
