export interface EchoesDialogOptions {
  className?: string;
  submitLabel?: string;
  showCancel?: boolean;
  closeOnly?: boolean;
}

export function dialogShell(title: string, options: string | EchoesDialogOptions = ""): HTMLDialogElement {
  const { className = "", submitLabel = "保存", showCancel = true, closeOnly = false } =
    typeof options === "string" ? { className: options } : options;
  const dialog = document.createElement("dialog");
  dialog.className = `echoes-dialog ${className}`.trim();
  const footer = closeOnly
    ? '<button type="submit" class="menu_button echoes-primary">关闭</button>'
    : `${showCancel ? '<button type="button" class="menu_button" data-close>取消</button>' : ""}<button type="submit" class="menu_button echoes-primary">${submitLabel}</button>`;
  dialog.innerHTML = `
    <form class="echoes-dialog-frame" method="dialog">
      <header class="echoes-dialog-header">
        <h2></h2>
        <button type="button" class="echoes-icon-button" data-close title="关闭" aria-label="关闭">
          <i class="fa-solid fa-xmark"></i>
        </button>
      </header>
      <div class="echoes-dialog-body"></div>
      <footer class="echoes-dialog-footer">${footer}</footer>
    </form>`;
  dialog.querySelector("h2")!.textContent = title;
  document.body.append(dialog);
  dialog.querySelectorAll("[data-close]").forEach((button) => {
    button.addEventListener("click", () => dialog.close("cancel"));
  });
  dialog.addEventListener("close", () => dialog.remove(), { once: true });
  return dialog;
}

export interface DialogSubmitOptions {
  errorTitle?: string;
}

export function submitDialog<T>(
  dialog: HTMLDialogElement,
  submit: () => T | Promise<T>,
  options: DialogSubmitOptions = {},
): Promise<T | null> {
  const form = dialog.querySelector<HTMLFormElement>("form")!;
  const body = dialog.querySelector<HTMLElement>(".echoes-dialog-body")!;
  const errorHost = document.createElement("div");
  errorHost.className = "echoes-dialog-error echoes-hidden";
  errorHost.setAttribute("role", "alert");
  body.append(errorHost);

  return new Promise((resolve) => {
    let settled = false;
    let submitting = false;
    const closeControls = [...dialog.querySelectorAll<HTMLButtonElement>("[data-close]")];
    const submitControl = form.querySelector<HTMLButtonElement>('button[type="submit"]');

    const setSubmitting = (value: boolean) => {
      submitting = value;
      if (submitControl) submitControl.disabled = value;
      closeControls.forEach((control) => { control.disabled = value; });
      form.setAttribute("aria-busy", String(value));
    };

    form.addEventListener("submit", (event) => {
      event.preventDefault();
      if (submitting) return;
      errorHost.classList.add("echoes-hidden");
      errorHost.textContent = "";
      setSubmitting(true);
      void Promise.resolve()
        .then(submit)
        .then((value) => {
          settled = true;
          resolve(value);
          if (dialog.open) dialog.close("saved");
        })
        .catch((error: unknown) => {
          const message = error instanceof Error ? error.message : String(error);
          errorHost.textContent = options.errorTitle ? `${options.errorTitle}：${message}` : message;
          errorHost.classList.remove("echoes-hidden");
          setSubmitting(false);
        });
    });
    dialog.addEventListener("cancel", (event) => {
      if (submitting) event.preventDefault();
    });
    dialog.addEventListener("close", () => {
      if (!settled) resolve(null);
    }, { once: true });
    dialog.showModal();
  });
}

function slugify(value: string): string {
  const slug = value
    .normalize("NFKD")
    .replace(/[^a-zA-Z0-9_-]+/g, "_")
    .replace(/^_+|_+$/g, "")
    .toLowerCase();
  return slug || "field";
}

function renderColumnRow(column?: MemoryColumnDefinition): HTMLElement {
  const row = document.createElement("div");
  row.className = "echoes-column-editor-row";
  row.innerHTML = `
    <input data-field="name" type="text" placeholder="显示名称" required>
    <input data-field="id" type="text" placeholder="column_id" required>
    <select data-field="type"></select>
    <label class="echoes-check"><input data-field="required" type="checkbox">必填</label>
    <input data-field="description" type="text" placeholder="字段用途说明">
    <input data-field="enumValues" type="text" placeholder="枚举值，以逗号分隔">
    <button type="button" class="echoes-icon-button" data-action="remove" title="删除列" aria-label="删除列">
      <i class="fa-solid fa-trash"></i>
    </button>`;

  const typeSelect = row.querySelector<HTMLSelectElement>("[data-field=type]")!;
  const typeLabels: Record<string, string> = {
    text: "短文本",
    long_text: "长文本",
    number: "数字",
    boolean: "布尔值",
    date: "日期",
    enum: "枚举",
    json: "JSON",
  };
  for (const type of MEMORY_COLUMN_TYPES) {
    const option = document.createElement("option");
    option.value = type;
    option.textContent = typeLabels[type] ?? type;
    typeSelect.append(option);
  }

  const nameInput = row.querySelector<HTMLInputElement>("[data-field=name]")!;
  const idInput = row.querySelector<HTMLInputElement>("[data-field=id]")!;
  nameInput.value = column?.name ?? "";
  idInput.value = column?.id ?? "";
  idInput.dataset.auto = column ? "false" : "true";
  typeSelect.value = column?.type ?? "text";
  row.querySelector<HTMLInputElement>("[data-field=required]")!.checked = column?.required ?? false;
  row.querySelector<HTMLInputElement>("[data-field=description]")!.value = column?.description ?? "";
  row.querySelector<HTMLInputElement>("[data-field=enumValues]")!.value = column?.enumValues?.join(", ") ?? "";
  nameInput.addEventListener("input", () => {
    if (idInput.dataset.auto === "true") idInput.value = slugify(nameInput.value);
  });
  idInput.addEventListener("input", () => {
    idInput.dataset.auto = "false";
  });
  row.querySelector("[data-action=remove]")!.addEventListener("click", () => row.remove());
  return row;
}

function readColumns(host: HTMLElement): MemoryColumnDefinition[] {
  return [...host.querySelectorAll<HTMLElement>(".echoes-column-editor-row")].map((row) => {
    const type = row.querySelector<HTMLSelectElement>("[data-field=type]")!.value;
    const enumValues = row
      .querySelector<HTMLInputElement>("[data-field=enumValues]")!
      .value.split(",")
      .map((value) => value.trim())
      .filter(Boolean);
    const description = row.querySelector<HTMLInputElement>("[data-field=description]")!.value.trim();
    return {
      id: row.querySelector<HTMLInputElement>("[data-field=id]")!.value.trim(),
      name: row.querySelector<HTMLInputElement>("[data-field=name]")!.value.trim(),
      type: type as MemoryColumnDefinition["type"],
      required: row.querySelector<HTMLInputElement>("[data-field=required]")!.checked,
      ...(description ? { description } : {}),
      ...(type === "enum" ? { enumValues } : {}),
    };
  });
}

function fillDefinition(
  body: HTMLElement,
  value: Pick<MemoryTypeTemplate, "name" | "description" | "columns" | "writePrompt">,
): void {
  body.querySelector<HTMLInputElement>("[name=name]")!.value = value.name;
  body.querySelector<HTMLTextAreaElement>("[name=description]")!.value = value.description;
  body.querySelector<HTMLTextAreaElement>("[name=writePrompt]")!.value = value.writePrompt;
  const host = body.querySelector<HTMLElement>(".echoes-column-editor")!;
  host.replaceChildren(...value.columns.map((column) => renderColumnRow(column)));
}

function definitionMarkup(includeTemplate: boolean): string {
  return `
    <div class="echoes-form-grid">
      ${includeTemplate ? '<label>基于模板<select name="templateId" required></select></label>' : ""}
      <label>名称<input name="name" type="text" required></label>
      <label class="echoes-form-span">用途说明<textarea name="description" rows="2"></textarea></label>
      <label class="echoes-form-span">写表提示词<textarea name="writePrompt" rows="6" required></textarea></label>
    </div>
    <div class="echoes-section-heading">
      <h3>自定义数据表头</h3>
      <button type="button" class="echoes-icon-button" data-add-column title="添加列" aria-label="添加列"><i class="fa-solid fa-plus"></i></button>
    </div>
    <div class="echoes-column-editor"></div>`;
}

export function openTypeDialog(
  templates: MemoryTypeTemplate[],
  current?: MemoryTypeDefinition,
): Promise<MemoryTypeInput | null> {
  const dialog = dialogShell(current ? "编辑记忆类型" : "新建记忆类型");
  const body = dialog.querySelector<HTMLElement>(".echoes-dialog-body")!;
  body.innerHTML = definitionMarkup(true);
  const templateSelect = body.querySelector<HTMLSelectElement>("[name=templateId]")!;
  for (const template of templates) {
    const option = document.createElement("option");
    option.value = template.id;
    option.textContent = template.name;
    templateSelect.append(option);
  }
  if (current && !templates.some((template) => template.id === current.templateId)) {
    const option = document.createElement("option");
    option.value = current.templateId;
    option.textContent = "已删除的原始模板";
    templateSelect.append(option);
  }
  const initialTemplate = templates.find((template) => template.id === current?.templateId)
    ?? templates[0];
  if (current) {
    templateSelect.value = current.templateId;
    templateSelect.disabled = true;
    fillDefinition(body, current);
  } else if (initialTemplate) {
    templateSelect.value = initialTemplate.id;
    fillDefinition(body, { ...initialTemplate, name: initialTemplate.name.replace(/模板$/, "") });
  }
  templateSelect.addEventListener("change", () => {
    const template = templates.find((candidate) => candidate.id === templateSelect.value);
    if (template) fillDefinition(body, { ...template, name: template.name.replace(/模板$/, "") });
  });
  body.querySelector("[data-add-column]")!.addEventListener("click", () => {
    body.querySelector(".echoes-column-editor")!.append(renderColumnRow());
  });

  return new Promise((resolve) => {
    let settled = false;
    dialog.querySelector("form")!.addEventListener("submit", (event) => {
      event.preventDefault();
      try {
        const parsed = memoryTypeInputSchema.parse({
          ...(current ? { id: current.id } : {}),
          templateId: templateSelect.value,
          name: body.querySelector<HTMLInputElement>("[name=name]")!.value,
          description: body.querySelector<HTMLTextAreaElement>("[name=description]")!.value,
          writePrompt: body.querySelector<HTMLTextAreaElement>("[name=writePrompt]")!.value,
          columns: readColumns(body.querySelector<HTMLElement>(".echoes-column-editor")!),
          enabled: current?.enabled ?? true,
        });
        settled = true;
        resolve(parsed);
        dialog.close("saved");
      } catch (error) {
        toastr.error(error instanceof Error ? error.message : String(error), "类型定义无效");
      }
    });
    dialog.addEventListener("close", () => {
      if (!settled) resolve(null);
    }, { once: true });
    dialog.showModal();
  });
}

export function openTemplateDialog(
  current?: MemoryTypeTemplate,
): Promise<MemoryTypeTemplateInput | null> {
  const dialog = dialogShell(current ? "编辑类型模板" : "新建类型模板");
  const body = dialog.querySelector<HTMLElement>(".echoes-dialog-body")!;
  body.innerHTML = definitionMarkup(false);
  if (current) fillDefinition(body, current);
  else body.querySelector<HTMLElement>(".echoes-column-editor")!.append(renderColumnRow());
  body.querySelector("[data-add-column]")!.addEventListener("click", () => {
    body.querySelector(".echoes-column-editor")!.append(renderColumnRow());
  });

  return new Promise((resolve) => {
    let settled = false;
    dialog.querySelector("form")!.addEventListener("submit", (event) => {
      event.preventDefault();
      try {
        const parsed = memoryTypeTemplateInputSchema.parse({
          ...(current ? { id: current.id } : {}),
          name: body.querySelector<HTMLInputElement>("[name=name]")!.value,
          description: body.querySelector<HTMLTextAreaElement>("[name=description]")!.value,
          writePrompt: body.querySelector<HTMLTextAreaElement>("[name=writePrompt]")!.value,
          columns: readColumns(body.querySelector<HTMLElement>(".echoes-column-editor")!),
        });
        settled = true;
        resolve(parsed);
        dialog.close("saved");
      } catch (error) {
        toastr.error(error instanceof Error ? error.message : String(error), "模板定义无效");
      }
    });
    dialog.addEventListener("close", () => {
      if (!settled) resolve(null);
    }, { once: true });
    dialog.showModal();
  });
}

function valueInput(column: MemoryColumnDefinition, value: unknown): HTMLElement {
  const label = document.createElement("label");
  label.textContent = column.name;
  let input: HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement;
  if (column.type === "long_text" || column.type === "json") {
    input = document.createElement("textarea");
    input.rows = 4;
  } else if (column.type === "enum") {
    input = document.createElement("select");
    if (!column.required) input.append(new Option("", ""));
    for (const enumValue of column.enumValues ?? []) input.append(new Option(enumValue, enumValue));
  } else {
    input = document.createElement("input");
    input.type = column.type === "number"
      ? "number"
      : column.type === "date"
        ? "date"
        : column.type === "boolean"
          ? "checkbox"
          : "text";
  }
  input.dataset.columnId = column.id;
  input.dataset.columnType = column.type;
  if (column.required && !(input instanceof HTMLInputElement && input.type === "checkbox")) {
    input.required = true;
  }
  if (input instanceof HTMLInputElement && input.type === "checkbox") input.checked = Boolean(value);
  else if (value !== undefined) input.value = column.type === "json" ? JSON.stringify(value, null, 2) : String(value);
  label.append(input);
  return label;
}

export function openRowDialog(
  type: MemoryTypeDefinition,
  current?: MemoryRow,
): Promise<MemoryRowInput | null> {
  const dialog = dialogShell(current ? "编辑长期记忆" : "添加长期记忆");
  const body = dialog.querySelector<HTMLElement>(".echoes-dialog-body")!;
  body.innerHTML = `
    <div class="echoes-form-grid echoes-fixed-fields">
      <label>数据名<input name="dataName" type="text" required></label>
      <label>条目状态<select name="status">
        <option value="permanent">永久</option>
        <option value="keyword">关键词</option>
        <option value="vectorized">向量化</option>
      </select></label>
      <label class="echoes-form-span">关键词<input name="keywords" type="text" placeholder="可以为空；多个关键词以逗号分隔"></label>
    </div>
    <div class="echoes-section-heading"><h3>自定义数据</h3></div>
    <div class="echoes-form-grid" data-row-values></div>`;
  body.querySelector<HTMLInputElement>("[name=dataName]")!.value = current?.dataName ?? "";
  body.querySelector<HTMLSelectElement>("[name=status]")!.value = current?.status ?? "keyword";
  body.querySelector<HTMLInputElement>("[name=keywords]")!.value = current?.keywords.join(", ") ?? "";
  const valuesHost = body.querySelector<HTMLElement>("[data-row-values]")!;
  for (const column of type.columns) valuesHost.append(valueInput(column, current?.values[column.id]));

  return new Promise((resolve) => {
    let settled = false;
    dialog.querySelector("form")!.addEventListener("submit", (event) => {
      event.preventDefault();
      try {
        const values: Record<string, unknown> = {};
        for (const input of valuesHost.querySelectorAll<HTMLInputElement | HTMLTextAreaElement | HTMLSelectElement>("[data-column-id]")) {
          const id = input.dataset.columnId!;
          const columnType = input.dataset.columnType!;
          if (input instanceof HTMLInputElement && input.type === "checkbox") values[id] = input.checked;
          else if (!input.value.trim()) continue;
          else if (columnType === "number") values[id] = Number(input.value);
          else if (columnType === "json") values[id] = JSON.parse(input.value);
          else values[id] = input.value;
        }
        const keywords = body.querySelector<HTMLInputElement>("[name=keywords]")!.value
          .split(/[,\n]/)
          .map((keyword) => keyword.trim())
          .filter((keyword, index, all) => Boolean(keyword) && all.indexOf(keyword) === index);
        const parsed = memoryRowInputSchema.parse({
          dataName: body.querySelector<HTMLInputElement>("[name=dataName]")!.value,
          keywords,
          status: body.querySelector<HTMLSelectElement>("[name=status]")!.value,
          values,
          source: { kind: "manual", messageIds: [] },
        });
        settled = true;
        resolve(parsed);
        dialog.close("saved");
      } catch (error) {
        toastr.error(error instanceof Error ? error.message : String(error), "行数据无效");
      }
    });
    dialog.addEventListener("close", () => {
      if (!settled) resolve(null);
    }, { once: true });
    dialog.showModal();
  });
}

export function openPromptItemDialog(
  types: MemoryTypeDefinition[],
  current?: PromptPresetItem,
): Promise<PromptPresetItem | null> {
  const dialog = dialogShell(current ? "编辑提示词条目" : "添加提示词条目");
  const body = dialog.querySelector<HTMLElement>(".echoes-dialog-body")!;
  body.innerHTML = `
    <div class="echoes-form-grid">
      <label>条目类型<select name="kind">
        <option value="main">主提示词</option>
        <option value="type_writer">类型写表提示词</option>
        <option value="custom">自定义提示词</option>
      </select></label>
      <label>角色<select name="role"><option value="system">System</option><option value="user">User</option><option value="assistant">Assistant</option></select></label>
      <label>标题<input name="title" type="text" required></label>
      <label data-type-picker>记忆类型<select name="typeId"></select></label>
      <label class="echoes-form-span" data-content-field>内容<textarea name="content" rows="10"></textarea></label>
      <label class="echoes-check"><input name="enabled" type="checkbox">启用该提示词</label>
    </div>`;
  const kind = body.querySelector<HTMLSelectElement>("[name=kind]")!;
  const role = body.querySelector<HTMLSelectElement>("[name=role]")!;
  const title = body.querySelector<HTMLInputElement>("[name=title]")!;
  const typeSelect = body.querySelector<HTMLSelectElement>("[name=typeId]")!;
  const content = body.querySelector<HTMLTextAreaElement>("[name=content]")!;
  const enabled = body.querySelector<HTMLInputElement>("[name=enabled]")!;
  for (const type of types) typeSelect.append(new Option(type.name, type.id));
  kind.value = current?.kind ?? "custom";
  role.value = current?.role ?? "system";
  title.value = current?.title ?? "新提示词";
  enabled.checked = current?.enabled ?? true;
  if (current?.kind === "type_writer") typeSelect.value = current.typeId;
  else content.value = current?.content ?? "";

  const refresh = () => {
    const writer = kind.value === "type_writer";
    body.querySelector<HTMLElement>("[data-type-picker]")!.classList.toggle("echoes-hidden", !writer);
    body.querySelector<HTMLElement>("[data-content-field]")!.classList.toggle("echoes-hidden", writer);
    if (writer) {
      const type = types.find((candidate) => candidate.id === typeSelect.value) ?? types[0];
      if (type && (!current || title.value === "新提示词")) title.value = `${type.name}写表提示词`;
    }
  };
  kind.addEventListener("change", refresh);
  typeSelect.addEventListener("change", refresh);
  refresh();

  return new Promise((resolve) => {
    let settled = false;
    dialog.querySelector("form")!.addEventListener("submit", (event) => {
      event.preventDefault();
      if (kind.value === "type_writer" && !typeSelect.value) {
        toastr.error("没有可引用的记忆类型。", "提示词无效");
        return;
      }
      const base = {
        id: current?.id ?? newPromptItemId(),
        title: title.value.trim(),
        role: role.value as PromptRole,
        enabled: enabled.checked,
      };
      const item: PromptPresetItem = kind.value === "type_writer"
        ? { ...base, kind: "type_writer", typeId: typeSelect.value }
        : {
            ...base,
            kind: kind.value as "main" | "custom",
            content: content.value,
          };
      settled = true;
      resolve(item);
      dialog.close("saved");
    });
    dialog.addEventListener("close", () => {
      if (!settled) resolve(null);
    }, { once: true });
    dialog.showModal();
  });
}

export function openPreviewDialog(
  blocks: Array<{ title: string; role: PromptRole; content: string }>,
  runtimeInput: string,
): void {
  const dialog = dialogShell("副 API 请求预览", "echoes-preview-dialog");
  const footer = dialog.querySelector<HTMLElement>(".echoes-dialog-footer")!;
  footer.innerHTML = '<button type="button" class="menu_button echoes-primary" data-close>关闭</button>';
  footer.querySelector("[data-close]")!.addEventListener("click", () => dialog.close());
  const body = dialog.querySelector<HTMLElement>(".echoes-dialog-body")!;
  for (const block of [...blocks, { title: "运行时表格与增量对话", role: "user" as const, content: runtimeInput }]) {
    const section = document.createElement("section");
    section.className = "echoes-preview-block";
    const heading = document.createElement("header");
    heading.textContent = `${block.role.toUpperCase()} · ${block.title}`;
    const pre = document.createElement("pre");
    pre.textContent = block.content;
    section.append(heading, pre);
    body.append(section);
  }
  dialog.showModal();
}

export interface ExtractionReviewDecision {
  action: "submit" | "rerun";
  selectedIndexes: number[];
}

function extractionOperationTarget(
  item: ExtractionReviewItem,
  types: MemoryTypeDefinition[],
  rows: MemoryRow[],
): string {
  const operation = item.operation;
  const type = types.find((candidate) => candidate.id === operation.typeId);
  const typeName = type?.name ?? operation.typeId;
  if (operation.action === "add") return `${typeName} / ${operation.dataName}`;
  const row = rows.find((candidate) => candidate.id === operation.rowId);
  return `${typeName} / ${row?.dataName ?? operation.rowId}`;
}

export function openExtractionReviewDialog(
  items: ExtractionReviewItem[],
  types: MemoryTypeDefinition[],
  rows: MemoryRow[],
): Promise<ExtractionReviewDecision | null> {
  const dialog = dialogShell("审核结构化记忆批次", "echoes-extraction-review-dialog");
  const body = dialog.querySelector<HTMLElement>(".echoes-dialog-body")!;
  const notice = document.createElement("p");
  notice.className = "echoes-extraction-review-notice";
  notice.textContent = "有效操作默认选中；无效操作不可提交。提交后，未选项与无效项会被明确跳过并推进检查点。审核仅保存在当前页面内存中。";
  const list = document.createElement("div");
  list.className = "echoes-extraction-review-list";
  for (const item of items) {
    const row = document.createElement("article");
    row.className = `echoes-extraction-review-item ${item.state}`;
    const select = document.createElement("input");
    select.type = "checkbox";
    select.value = String(item.index);
    select.checked = item.state === "valid";
    select.disabled = item.state === "rejected";
    select.setAttribute("aria-label", `选择操作 ${item.index + 1}`);
    const summary = document.createElement("div");
    summary.className = "echoes-extraction-review-summary";
    const heading = document.createElement("strong");
    heading.textContent = `${item.index + 1}. ${item.operation.action.toUpperCase()} · ${extractionOperationTarget(item, types, rows)}`;
    const evidence = document.createElement("small");
    evidence.textContent = `证据消息：${item.operation.evidenceMessageIds.join(", ") || "无"}`;
    summary.append(heading, evidence);
    if (item.reason) {
      const reason = document.createElement("p");
      reason.textContent = item.reason;
      summary.append(reason);
    }
    const details = document.createElement("pre");
    details.textContent = JSON.stringify(item.operation, null, 2);
    row.append(select, summary, details);
    list.append(row);
  }
  body.append(notice, list);

  const footer = dialog.querySelector<HTMLElement>(".echoes-dialog-footer")!;
  footer.innerHTML = `
    <button type="button" class="menu_button" data-close>取消</button>
    <button type="button" class="menu_button" data-review-rerun><i class="fa-solid fa-rotate"></i> 重跑批次</button>
    <button type="submit" class="menu_button echoes-primary"><i class="fa-solid fa-check"></i> 提交选中项</button>`;
  footer.querySelector("[data-close]")!.addEventListener("click", () => dialog.close("cancel"));

  return new Promise((resolve) => {
    let settled = false;
    footer.querySelector("[data-review-rerun]")!.addEventListener("click", () => {
      settled = true;
      resolve({ action: "rerun", selectedIndexes: [] });
      dialog.close("rerun");
    });
    dialog.querySelector("form")!.addEventListener("submit", (event) => {
      event.preventDefault();
      const selectedIndexes = [...list.querySelectorAll<HTMLInputElement>('input[type="checkbox"]:checked')]
        .map((input) => Number(input.value));
      settled = true;
      resolve({ action: "submit", selectedIndexes });
      dialog.close("submit");
    });
    dialog.addEventListener("close", () => {
      if (!settled) resolve(null);
    }, { once: true });
    dialog.showModal();
  });
}

export interface MigrationSelection {
  sourceWorldbookName: string;
  typeIds: string[];
  policy: MigrationPolicy;
}

export function openMigrationDialog(options: {
  worldbookNames: string[];
  currentWorldbookName: string;
  loadTypes(worldbookName: string): Promise<MemoryTypeDefinition[]>;
}): Promise<MigrationSelection | null> {
  const dialog = dialogShell("迁移结构化长期记忆");
  const body = dialog.querySelector<HTMLElement>(".echoes-dialog-body")!;
  body.innerHTML = `
    <div class="echoes-form-grid">
      <label class="echoes-form-span">来源世界书<select name="source"></select></label>
      <label>冲突处理<select name="policy"><option value="skip">跳过已有类型</option><option value="overwrite">替换同一类型及其全部数据</option><option value="copy">创建副本</option></select></label>
    </div>
    <div class="echoes-section-heading"><h3>迁移类型</h3></div>
    <div class="echoes-migration-types"></div>`;
  const source = body.querySelector<HTMLSelectElement>("[name=source]")!;
  const host = body.querySelector<HTMLElement>(".echoes-migration-types")!;
  for (const name of options.worldbookNames.filter((name) => name !== options.currentWorldbookName)) {
    source.append(new Option(name, name));
  }

  const load = async () => {
    host.textContent = "正在读取来源世界书...";
    try {
      const types = await options.loadTypes(source.value);
      host.replaceChildren();
      for (const type of types) {
        const label = document.createElement("label");
        label.className = "echoes-migration-option";
        const checkbox = document.createElement("input");
        checkbox.type = "checkbox";
        checkbox.value = type.id;
        checkbox.checked = true;
        label.append(checkbox, document.createTextNode(type.name));
        host.append(label);
      }
      if (types.length === 0) host.textContent = "该世界书没有 Echoes 结构化记忆。";
    } catch (error) {
      host.textContent = error instanceof Error ? error.message : String(error);
    }
  };
  source.addEventListener("change", () => void load());
  if (source.value) void load();
  else host.textContent = "没有其他可迁移的世界书。";

  return new Promise((resolve) => {
    let settled = false;
    dialog.querySelector("form")!.addEventListener("submit", (event) => {
      event.preventDefault();
      const typeIds = [...host.querySelectorAll<HTMLInputElement>('input[type="checkbox"]:checked')]
        .map((input) => input.value);
      if (!source.value || typeIds.length === 0) {
        toastr.warning("请选择来源世界书和至少一个类型。", "无法迁移");
        return;
      }
      settled = true;
      resolve({
        sourceWorldbookName: source.value,
        typeIds,
        policy: body.querySelector<HTMLSelectElement>("[name=policy]")!.value as MigrationPolicy,
      });
      dialog.close("saved");
    });
    dialog.addEventListener("close", () => {
      if (!settled) resolve(null);
    }, { once: true });
    dialog.showModal();
  });
}
